(function(){
  var H=tg&&tg.HapticFeedback; if(!H) return;
  ['impactOccurred','notificationOccurred','selectionChanged'].forEach(function(m){
    var orig=H[m];
    if(typeof orig!=='function') return;
    var mia=(m==='notificationOccurred')?4:(m==='selectionChanged'?1:0);
    H[m]=function(k){
      if(!HAP.on) return;
      var f=mia||HAP_FORZA[String(k||'light')]||1;
      var now=Date.now();
      if(now-HAP.last<HAP.gap && f<=HAP.forza) return;
      HAP.last=now; HAP.forza=f;
      try{ return orig.apply(H,arguments); }catch(_h4){}
    };
  });
})();
function hapTap(kind){
  try{
    var H=tg&&tg.HapticFeedback; if(!H) return;
    if(kind==='sel'){ if(H.selectionChanged)H.selectionChanged(); else if(H.impactOccurred)H.impactOccurred('soft'); }
    else if(kind==='forte'){ if(H.impactOccurred)H.impactOccurred('medium'); }
    else if(H.impactOccurred) H.impactOccurred('light');
  }catch(_h5){}
}
