function getLevel(xp){
  var cur=LEVELS[0],next=LEVELS[1];
  for(var i=LEVELS.length-1;i>=0;i--){
    if(xp>=LEVELS[i].xp){cur=LEVELS[i];next=LEVELS[i+1]||null;break;}
  }
  var inLv=xp-cur.xp;
  var lvRange=next?(next.xp-cur.xp):1;
  return{level:cur.lv,icon:cur.icon,title:cur.title,
    pct:Math.min(100,Math.round(inLv/lvRange*100)),
    next:next,toNext:next?(next.xp-xp):0};
}
