function capTonSetta(d){
  if(!d)return;
  var haT=(d.eur_ton!==undefined&&d.eur_ton!==null);
  var haG=(d.eur_giocabile!==undefined&&d.eur_giocabile!==null&&
           d.eur_btc!==undefined&&d.eur_btc!==null);
  if(!haT&&!haG)return;
  var t=haT?(+d.eur_ton):((+d.eur_giocabile)-(+d.eur_btc));
  if(!(t>0))t=0;
  S.eurTon=t;
  S.eurTonTs=Date.now();
  S._capBtcVisto=S.btc;
  if(d.eur_giocabile!==undefined&&d.eur_giocabile!==null)S.eurGioc=+d.eur_giocabile;
  if(d.ton_gioco!==undefined)S.tonGioco=!!d.ton_gioco;
  if(d.ton_fresh!==undefined)S.tonFresh=!!d.ton_fresh;
  if(d.eur_totale!==undefined&&d.eur_totale!==null&&
     d.eur_btc!==undefined&&d.eur_btc!==null){
    var p=(+d.eur_totale)-(+d.eur_btc);
    S.eurPoss=(p>0)?p:0;
  }
  if(d.eur_parziale!==undefined)S.eurParz=!!d.eur_parziale;
  if(d.perche!==undefined)S.eurPerche=d.perche;
  if(d.motivo!==undefined)S.eurMotivo=d.motivo;
}
function capVeglia(){
  var prima=S._capBtcVisto;
  S._capBtcVisto=S.btc;
  if(capTonEur()<=0)return;
  if(prima===null||prima===undefined)return;
  if(Math.abs(prima-S.btc)<1e-12)return;
  if((S.btc*S.rate)>0.02)return;
  var ora=Date.now();
  if(ora-(S._capVegliaTs||0)<3000)return;
  S._capVegliaTs=ora;
  setTimeout(function(){if(typeof loadBalance==='function')loadBalance();},600);
}
