function grPreloadVideos(){
  if(GR._preloaded) return; GR._preloaded=true;
  var grun=document.getElementById('grun'); if(!grun) return;
  var host=document.getElementById('gr-vid-preload');
  if(!host){ host=document.createElement('div'); host.id='gr-vid-preload'; host.style.cssText='position:absolute;width:0;height:0;overflow:hidden;opacity:0;pointer-events:none;'; grun.appendChild(host); }
  var srcs=[], seen={};
  Object.keys(GR_VIDS).forEach(function(k){ var s=GR_VIDS[k]; if(s&&!seen[s]){ seen[s]=1; srcs.push(s); } });
  var idx=0;
  function next(){
    if(idx>=srcs.length || CUR!=='grun') return;
    var s=srcs[idx++];
    var pv=document.createElement('video'); pv.muted=true; pv.setAttribute('playsinline',''); pv.preload='auto'; pv.src=s;
    var moved=false;
    function go(){ if(moved)return; moved=true; setTimeout(next, 250); }
    pv.addEventListener('loadeddata', go, {once:true});
    pv.addEventListener('error', go, {once:true});
    setTimeout(go, 6000);
    try{ pv.load(); }catch(e){}
    host.appendChild(pv);
  }
  setTimeout(next, 2500);
}
