    c.fillStyle='#d9d2ef'; rr(-13,-22,26,21,6); c.fill();
    c.fillStyle='#0a0d14'; rr(-10,-16,20,9,3); c.fill();
    c.fillStyle='#37e0c8';
    c.fillRect(-8,-14,3,5); c.fillRect(5,-14,3,5);
    c.fillStyle='#a8fff0'; c.fillRect(-1.5,-14,3,5);
