    g.addColorStop(0,'#5a2438'); g.addColorStop(1,'#241019');
    c.fillStyle=g; rr(-15,-2,30,28,7); c.fill();
    c.fillStyle='#3a2030'; rr(-12,-20,24,20,6); c.fill();
