    var sy=(shake>0)?(Math.random()-0.5)*shake*22:0;
    c.clearRect(0,0,280,200);
    c.save(); c.translate(sx,sy);
    c.fillStyle='#0a0d14'; c.fillRect(0,0,280,200);
