    for(var gy=40;gy<200;gy+=26){ c.beginPath(); c.moveTo(0,gy); c.lineTo(280,gy); c.stroke(); }
    if(state==='carica'){
      var ramp=1-(dur-st)/dur; if(ramp<0)ramp=0; if(ramp>1)ramp=1;
      var near=(dur-st<0.18);
      c.fillStyle='rgba(255,84,112,'+(0.12+0.30*ramp+(near?0.30:0))+')';
      c.fillRect(targetX-32,26,64,158);
      c.strokeStyle=near?'#fff':'#ff5470'; c.lineWidth=near?3:2;
      c.strokeRect(targetX-32,26,64,158);
      if(near){
        c.fillStyle='rgba(255,255,255,'+(0.10+0.30*ramp)+')';
        c.fillRect(targetX-32,26,64,158);
      }
    }
    var col='#b06bff', pulse=0;
    if(state==='scoperto'){ col='#39d98a'; pulse=0.5+0.5*Math.sin(now/70); }
    else if(state==='carica'){ col='#ff5470'; pulse=0.5+0.5*Math.sin(now/50); }
    var lunge=(state==='carica' && dur-st<0.18)?18:0;
    drawRival(rivalX,58,col,pulse,lunge);
    var dist=Math.abs(playerX-rivalX);
    if(dist<48 && state!=='carica'){
      c.strokeStyle='rgba(55,224,200,0.4)'; c.lineWidth=1;
      c.beginPath(); c.moveTo(playerX,150); c.lineTo(rivalX,80); c.stroke();
    }
    drawPlayer(playerX,150);
