    if(counterFx>0){ c.fillStyle='rgba(255,84,112,'+(counterFx*0.5)+')'; c.fillRect(0,0,280,200); }
    drawPips(280-5*13-4,6,rivalHP,5,'#ff5470');
    drawPips(6,188,3-taken,3,'#37e0c8');
    c.fillStyle='#8a93a6'; c.font='7px monospace'; c.textAlign='left'; c.textBaseline='top';
    c.fillText('RIVALE',280-5*13-4,15);
    c.fillStyle='rgba(255,255,255,0.1)'; c.fillRect(6,6,90,5);
    c.fillStyle=timeLeft<4?'#ff5470':'#ffcf5a'; c.fillRect(6,6,90*Math.max(0,timeLeft)/14,5);
    var lab=(state==='scoperto')?'SCOPERTO!':(state==='carica')?'CARICA — SCHIVA':'IN GUARDIA';
    c.fillStyle=col; c.font='bold 11px monospace'; c.textAlign='center'; c.textBaseline='middle';
    c.fillText(lab,140,120);
    c.restore();
    raf=grRaf(loop);
