    var right=-999;
    for(var i=0;i<roofs.length;i++){ var r=roofs[i]; r.x-=speed*dt; if(r.x+r.w>right) right=r.x+r.w; }
    for(var i=roofs.length-1;i>=0;i--){ if(roofs[i].x+roofs[i].w<-40) roofs.splice(i,1); }
    if(right<300){ makeRoof(right); }
    var sliding=slideT>0;
    var bt=(sliding?groundY-15:groundY-30)-jy, bb=groundY-jy;
