    el+=dt;
    if(tapLock>0)tapLock-=dt;
    if(hitFx>0)hitFx-=dt; if(missFx>0)missFx-=dt; if(tapFx>0)tapFx-=dt; if(shake>0)shake-=dt;
    spd=Math.min(2.6,1.7+el*0.05);
