    c.fillStyle='#b9c3d6';c.strokeStyle='#7f8aa3';c.lineWidth=1;
    c.beginPath();c.rect(-8,-3,16,12);c.fill();c.stroke();
    c.fillStyle='#e6ecf7';c.fillRect(-7,-2,3,10);
    c.fillStyle='#20242e';c.fillRect(-7,-13,14,7);
    c.fillStyle='#151820';c.fillRect(-8,-7,16,2);
    c.fillStyle='#2fe08a';c.fillRect(-7,-10,14,3);
    c.fillStyle='#0a0d14';c.font='bold 4px monospace';c.textAlign='center';c.textBaseline='middle';
    c.fillText('G',0,-8.4);
    c.fillStyle='#3ad6c0';c.beginPath();c.arc(-3,2,1.7,0,6.28);c.arc(3,2,1.7,0,6.28);c.fill();
