function grSkillBrief(meta,onGo){
  meta=meta||{};
  var _bt=meta.t||'⚔️ SFIDA', _bd=meta.d||'Preparati alla prova.', _bg=meta.g||'', _bv='VIA ▸';
  if(typeof gbT==='function'){ _bt=gbT(_bt); _bd=gbT(_bd); if(_bg)_bg=gbT(_bg); _bv=gbT(_bv); }
  var ov=document.createElement('div'); ov.className='gr-skill-ov'; ov.id='gr-skill-brief';
  ov.innerHTML='<div class="gr-skill-card">'
    +'<div class="gr-skill-ttl">'+_bt+'</div>'
    +'<div class="gr-skill-desc">'+_bd+'</div>'
    +(_bg?'<div class="gr-brief-gesture">'+_bg+'</div>':'')
    +'<button class="gr-skill-btn gr-brief-go" id="gr-brief-go">'+_bv+'</button>'
    +'</div>';
  var host=document.getElementById('grun')||document.body; host.appendChild(ov);
  try{grSound&&grSound('click');}catch(e){}
  var go=document.getElementById('gr-brief-go'),fired=false;
  function start(){ if(fired)return; fired=true; if(ov.parentNode)ov.parentNode.removeChild(ov); onGo(); }
  if(go)go.onclick=start;
}
