function grcMergeMutators(ids){
  var mut={ enCountAdd:0, dropMul:1, playerRate:1, heartsAdd:0, eliteChanceAdd:0 }, i, k, byId={};
  for(i=0;i<MUTATOR_DEFS.length;i++) byId[MUTATOR_DEFS[i].id]=MUTATOR_DEFS[i];
  ids=ids||[]; for(i=0;i<ids.length;i++){ var d=byId[ids[i]]; if(!d) continue; var mm=d.mut||{};
    for(k in mm){ if(mm.hasOwnProperty(k)){ if(k==='dropMul'||k==='playerRate') mut[k]=(mut[k]||1)*mm[k]; else mut[k]=(mut[k]||0)+mm[k]; } } }
  return mut;
}
