function grcHash(s){ s=String(s==null?'':s); var h=2166136261>>>0,i;
  for(i=0;i<s.length;i++){ h^=s.charCodeAt(i); h=Math.imul(h,16777619)>>>0; } return h>>>0; }
var GR_XMEM_KEY='gr_xmem_v1';
var GR_XMEM=null, GR_XMEM_LOADED=false;
function grcXmemDefault(){ return { v:1, spared:{}, killed:{}, npcMemory:{}, endings:{}, runs:0 }; }
function grcXmemObj(o){ return (o&&typeof o==='object')?o:{}; }
function grcXmemLoad(){
  if(GR_XMEM_LOADED) return GR_XMEM;
  GR_XMEM_LOADED=true;
  var d=grcXmemDefault();
  try{
    var raw=(typeof localStorage!=='undefined'&&localStorage)?localStorage.getItem(GR_XMEM_KEY):null;
    if(raw){ var p=JSON.parse(raw); if(p&&typeof p==='object'){
      d.spared=grcXmemObj(p.spared); d.killed=grcXmemObj(p.killed);
      d.npcMemory=grcXmemObj(p.npcMemory); d.endings=grcXmemObj(p.endings);
      d.runs=+p.runs||0;
    } }
  }catch(e){ try{ grWarn('grcXmemLoad',e); }catch(_a){} }
  GR_XMEM=d; return d;
}
function grcXmemSave(){
  try{
    if(typeof localStorage==='undefined'||!localStorage) return false;
    localStorage.setItem(GR_XMEM_KEY, JSON.stringify(GR_XMEM||grcXmemDefault()));
    return true;
  }catch(e){ try{ grWarn('grcXmemSave',e); }catch(_a){} return false; }
}
function grcRunProfile(){
  var s=(typeof GRX!=='undefined'&&GRX.story)?GRX.story:null;
  var mercy=s?(+s.mercy||0):0, slain=s?(+s.slain||0):0, cheat=s?(+s.cheat||0):0;
  var st=(typeof GR!=='undefined'&&GR.view&&GR.view.story)?GR.view.story:{};
  var greed=+st.greed||0, caution=+st.caution||0, honor=+st.honor||0;
  if(cheat>=3 && greed>=3) return 'SECRET';
  if(mercy>=3 && mercy>slain) return 'MISERICORDIOSO';
  if(slain>=3 && slain>mercy) return 'SPIETATO';
  if(greed>=4 && (mercy+slain)<2) return 'AVIDO';
  if(honor>=3 && mercy>=slain) return 'MISERICORDIOSO';
  if(honor<=-2 && slain>=1) return 'SPIETATO';
  return 'NEUTRALE';
}
