function grcMemLine(id){
  try{
    var xm=grcXmemLoad(); var mm=xm.npcMemory&&xm.npcMemory[id];
    if(!mm||!mm.state) return null;
    var pool=GR_NPC_MEMBARKS[id]&&GR_NPC_MEMBARKS[id][mm.state];
    if(!pool||!pool.length) return null;
    var rc=(typeof grcRunConfig==='function'&&typeof grcRunSeed==='function')?grcRunConfig(grcRunSeed()):null;
    var bs=(rc&&rc.beatSalt)?rc.beatSalt:1;
    var r=grcRng((bs^grcHash(id))>>>0)();
    var k=Math.floor(r*pool.length); if(k<0||k>=pool.length)k=0;
    return pool[k];
  }catch(e){ return null; }
}
