    P.walk += Math.min(1,Math.hypot(P.mvx,P.mvy))*dt*13;
    P.x+=P.mvx*GR_C.PL_SPD*dt; P.y+=P.mvy*GR_C.PL_SPD*dt;
    if(P.x<fx0+GR_C.PL_R)P.x=fx0+GR_C.PL_R; if(P.x>fx1-GR_C.PL_R)P.x=fx1-GR_C.PL_R;
    if(P.y<fy0+GR_C.PL_R)P.y=fy0+GR_C.PL_R; if(P.y>fy1-GR_C.PL_R)P.y=fy1-GR_C.PL_R;
    if(P.aon){ var am=Math.hypot(P.ax,P.ay); if(am>0.02) P.face=Math.atan2(P.ay,P.ax); }
    else { var mv=Math.hypot(P.mvx,P.mvy); if(mv>0.05) P.face=Math.atan2(P.mvy,P.mvx); }
