    for(var i=0;i<rects.length;i++){ var dr=rects[i];
      if(Math.hypot(P.x-dr.zx,P.y-dr.zy) >= dr.gw*0.5){ dr._cool=false; continue; }
      if(dr._ask || dr._cool) break;
      if(dr.locked){ if(doorNag<=0){ doorNag=0.6; shake=Math.max(shake,4); grcMsg('🔒 SIGILLATA'); try{ grHaptic('lose'); }catch(_){} } }
      else { doorEnter=dr; grcMsg(dr.cashout?'💰 ESCI COL POT — tieni premuto':'▸ ENTRA ◂'); try{ grHaptic('enter'); }catch(_){} try{ grSound('chip'); }catch(_){} }
      break;
    }
