    g.strokeStyle='#17c964'; g.lineWidth=1.6; g.beginPath(); g.arc(0,0,R*0.51,0,6.283); g.stroke();
    var cg=g.createRadialGradient(-R*0.16,-R*0.16,0.5,0,0,R*0.52); cg.addColorStop(0,'#243049'); cg.addColorStop(0.7,'#131a29'); cg.addColorStop(1,'#0a0f18');
    g.fillStyle=cg; g.beginPath(); g.arc(0,0,R*0.50,0,6.283); g.fill();
    g.fillStyle='rgba(210,224,255,.35)'; g.beginPath(); g.arc(-R*0.17,-R*0.19,R*0.13,0,6.283); g.fill();
    g.fillStyle='#ffcf5a'; g.font='bold '+Math.round(R*0.62)+'px monospace'; g.fillText('G',0,0.5);
    g.fillStyle='#0c1220'; g.beginPath(); g.arc(0,0,R-0.6,-0.62,0.62); g.arc(0,0,R*0.56,0.62,-0.62,true); g.closePath(); g.fill();
