  g.quadraticCurveTo(W*0.84,H*0.62,W*0.88,H); g.closePath(); g.fill();
  g.fillStyle=p.skin; g.beginPath(); g.arc(W/2,H*0.42,W*0.20,0,6.283); g.fill();
