function grDialog(title, body, opts, cb, ex){
  var host=document.getElementById('grun')||document.body;
  grDialogClose();
  var ov=document.createElement('div');
  ov.className='gr-skill-ov'; ov.id='gr-dlg-ov';
  opts=opts||[];
  var optHtml='', i, lbl;
  for(i=0;i<opts.length;i++){
    lbl=(typeof opts[i]==='string')?opts[i]:((opts[i]&&opts[i].label)||('Opzione '+(i+1)));
    optHtml+='<button class="gr-ev-opt" data-i="'+i+'" disabled>'+grNpcEsc(lbl)+'</button>';
  }
  var pid=(ex && ex.portrait && GR_NPC_META[ex.portrait])?ex.portrait:null;
  ov.innerHTML='<div class="gr-ev-card">'+
    (pid?'<canvas class="gr-dlg-face" width="76" height="76" style="display:block;margin:0 auto 8px;width:64px;height:64px;border-radius:50%;box-shadow:0 0 0 2px rgba(255,255,255,.15),0 4px 14px rgba(0,0,0,.5);background:#0d0f1a;"></canvas>':'')+
    '<div class="gr-ev-ttl">'+grNpcEsc(title||'')+'</div>'+
    '<div class="gr-ev-body gr-dlg-body"></div>'+
    '<div class="gr-ev-opts">'+optHtml+'</div></div>';
  host.appendChild(ov);
  if(pid){ try{ grNpcPortrait(ov.querySelector('.gr-dlg-face'), GR_NPC_META[pid]); }catch(e0){} }
  if(typeof grSound==='function'){ try{ grSound('tick'); }catch(e1){} }
  var bodyEl=ov.querySelector('.gr-dlg-body');
  var full=String(body==null?'':body), pos=0, done=false;
  var btns=ov.querySelectorAll('.gr-ev-opt');
  function enable(){ var k; for(k=0;k<btns.length;k++) btns[k].removeAttribute('disabled'); }
  ov._tw=setInterval(function(){
    pos+=2; if(pos>full.length) pos=full.length;
    bodyEl.innerHTML=grNpcEsc(full.slice(0,pos))+(pos<full.length?'<span class="cur">▌</span>':'');
    if(pos>=full.length && !done){ done=true; clearInterval(ov._tw); ov._tw=null; enable(); }
  },18);
  function skip(){
    if(done) return;
    done=true;
    if(ov._tw){ clearInterval(ov._tw); ov._tw=null; }
    bodyEl.innerHTML=grNpcEsc(full); enable();
  }
  ov.addEventListener('click',function(e){
    var c=e.target&&e.target.className;
    if(e.target===ov || e.target===bodyEl || (typeof c==='string' && c.indexOf('gr-ev-card')>=0)) skip();
  });
  var b;
  for(b=0;b<btns.length;b++){
    btns[b].onclick=function(){
      if(this.hasAttribute('disabled')) return;
      var ci=parseInt(this.getAttribute('data-i'),10);
      grDialogClose();
      if(typeof cb==='function'){ try{ cb(ci); }catch(e2){} }
    };
  }
  return ov;
}
function grDialogClose(){
  var ov=document.getElementById('gr-dlg-ov');
  if(!ov) return;
  if(ov._tw){ try{ clearInterval(ov._tw); }catch(e){} ov._tw=null; }
  if(ov.parentNode) ov.parentNode.removeChild(ov);
}
function grNpcTalk(npc){
  var id=(typeof npc==='string')?npc:(npc&&npc.npc);
  var meta=GR_NPC_META[id];
  if(!meta) return;
  var B=GR_NPC_BARKS[id]||{};
  var v=(typeof GR!=='undefined'&&GR.view)?GR.view:{};
  var st=v.story||{};
  var flags=(st.flags||[]).concat(st.items||[]);
  var conv=null, i;
  if(B.talkFlags){
    for(i=0;i<flags.length;i++){
      if(B.talkFlags[flags[i]]){ conv=B.talkFlags[flags[i]]; break; }
    }
  }
  if(!conv){
    var ts=B.talk||[];
    conv=ts.length?ts[Math.floor(Math.random()*ts.length)]:null;
  }
  if(!conv || !conv.length) conv=['...'];
  if(typeof GR_META_ON!=='undefined' && GR_META_ON){
    try{
      var _rb=(typeof grMetaBarkReturn==='function')?grMetaBarkReturn(id):null;
      if(_rb){ conv=[_rb].concat(conv); }
      if(typeof grMetaRecordNpc==='function') grMetaRecordNpc(id);
    }catch(_eRb){ grWarn('grNpcTalk.metaBark', _eRb); }
  }
  if(typeof grHaptic==='function'){ try{ grHaptic('sel'); }catch(e){} }
  function step(k){
    var last=(k>=conv.length-1);
    grDialog(meta.emoji+' '+meta.nm, conv[k],
      [ last?'👋 CI VEDIAMO':'CONTINUA ▸' ],
      function(){ if(!last) step(k+1); },
      { portrait:id });
  }
  step(0);
}
