var GRS = {
  _timers: [],
  acts: {},
  tac: null,
  tacOpen: false
};
function grStoryOn(){ return (typeof GR_RPG_ON!=='undefined') && !!GR_RPG_ON; }
function grStoryEsc(s){
  if(typeof dlEsc==='function') return dlEsc(s);
  return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}
function grStoryTimer(fn, ms, iv){
  var id = iv ? setInterval(fn, ms) : setTimeout(fn, ms);
  GRS._timers.push({id:id, iv:!!iv});
  return id;
}
function grStoryKill(id){
  for(var i=0;i<GRS._timers.length;i++){
    if(GRS._timers[i].id===id){
      if(GRS._timers[i].iv) clearInterval(id); else clearTimeout(id);
      GRS._timers.splice(i,1); return;
    }
  }
}
function grStoryClearTimers(){
  for(var i=0;i<GRS._timers.length;i++){
    var t=GRS._timers[i];
    if(t.iv) clearInterval(t.id); else clearTimeout(t.id);
  }
  GRS._timers=[];
}
function grStoryType(el, txt, ms, done){
  var full=String(txt==null?'':txt), pos=0, fin=false;
  function finish(){
    if(fin) return; fin=true;
    grStoryKill(tw);
    el.innerHTML=grStoryEsc(full);
    if(done) done();
  }
  var tw=grStoryTimer(function(){
    pos+=2; if(pos>=full.length){ pos=full.length; }
    if(!el || !el.parentNode){ finish(); return; }
    el.innerHTML=grStoryEsc(full.slice(0,pos))+(pos<full.length?'<span class="cur">▌</span>':'');
    if(pos>=full.length) finish();
  }, ms||18, true);
  return finish;
}
