function grContractCard(d, cb){
  var fired=false;
  function go(){ if(fired) return; fired=true; if(typeof cb==='function') cb(); }
  try{
    GRS.acts={}; GRS.tac=null; GRS.tacOpen=false;
    grStoryRm('gr-tac-ov');
    var c = grStoryOn() && d && d.story && d.story.contract;
    if(!c || !c.title){ go(); return false; }
    grStoryRm('gr-ctr-ov');
    var ov=document.createElement('div'); ov.className='gr-skill-ov'; ov.id='gr-ctr-ov';
    ov.innerHTML='<div class="gr-ev-card gr-ctr-card">'+
      '<div class="gr-ctr-eyebrow">IL PALAZZO · UN CONTRATTO, UNA NOTTE</div>'+
      '<div class="gr-ctr-ttl">✉️ '+grStoryEsc(c.title)+'</div>'+
      '<div class="gr-ctr-body" id="gr-ctr-body"></div>'+
      '<button class="gr-ctr-sign" id="gr-ctr-sign" disabled>🖋️ FIRMA. E SCENDI. ▸</button></div>';
    var host=document.getElementById('grun')||document.body;
    host.appendChild(ov);
    if(typeof grSound==='function'){ try{ grSound('tick'); }catch(e){} }
    if(typeof grHaptic==='function'){ try{ grHaptic('sel'); }catch(e){} }
    var body=document.getElementById('gr-ctr-body');
    var btn=document.getElementById('gr-ctr-sign');
    var skip=grStoryType(body, c.text||'', 18, function(){ if(btn) btn.removeAttribute('disabled'); });
    ov.addEventListener('click', function(e){ if(e.target===ov||e.target===body) skip(); });
    btn.onclick=function(){
      if(this.hasAttribute('disabled')) return;
      if(typeof grSound==='function'){ try{ grSound('chip'); }catch(e){} }
      if(typeof grHaptic==='function'){ try{ grHaptic('enter'); }catch(e){} }
      grStoryRm('gr-ctr-ov');
      go();
    };
    return true;
  }catch(e){ grStoryRm('gr-ctr-ov'); go(); return false; }
}
function grActInterstitial(row){
  try{
    if(!grStoryOn()) return false;
    row=row|0;
    if(row!==5 && row!==10) return false;
    var act=grStoryActFor(row);
    if(GRS.acts[act]) return false;
    GRS.acts[act]=1;
    var pal=GR_ACT_PALETTES[act];
    grStoryRm('gr-act-ov');
    var ov=document.createElement('div'); ov.className='gr-skill-ov gr-act-ov'; ov.id='gr-act-ov';
    ov.style.background='linear-gradient(180deg,'+pal.bg0+' 0%,'+pal.bg1+' 100%)';
    ov.innerHTML='<div class="gr-act-card" style="color:'+pal.neon+';">'+
      '<div class="gr-act-eyebrow" style="color:'+pal.ink+';">'+grStoryEsc(pal.act)+'</div>'+
      '<div class="gr-act-nome" id="gr-act-nome"></div>'+
      '<div class="gr-act-sub" style="color:'+pal.ink+';">'+grStoryEsc(pal.sub)+'</div></div>';
    var host=document.getElementById('grun')||document.body;
    host.appendChild(ov);
    if(typeof grSound==='function'){ try{ grSound('win-small'); }catch(e){} }
    if(typeof grHaptic==='function'){ try{ grHaptic('pick'); }catch(e){} }
    if(typeof GBMusic!=='undefined' && GBMusic && GBMusic.play){ try{ GBMusic.play(pal.theme); }catch(e){} }
    grStoryType(document.getElementById('gr-act-nome'), pal.nome, 34);
    function close(){ grStoryRm('gr-act-ov'); }
    ov.addEventListener('click', close);
    grStoryTimer(close, 2600, false);
    return true;
  }catch(e){ grStoryRm('gr-act-ov'); return false; }
}
function grTaccuino(d){
  try{
    var btn=document.getElementById('gr-tac-btn');
    var has = grStoryOn() && d && ((d.story&&d.story.contract) || (d.contracts&&d.contracts.length));
    if(!has){
      if(btn && btn.parentNode) btn.parentNode.removeChild(btn);
      grStoryRm('gr-tac-ov'); GRS.tac=null; GRS.tacOpen=false;
      return false;
    }
    GRS.tac={
      contract:(d.story&&d.story.contract)||null,
      contracts:(d.contracts||[]),
      chains:(d.story&&d.story.chains)||{}
    };
    var doneN=0, i;
    for(i=0;i<GRS.tac.contracts.length;i++){ if(GRS.tac.contracts[i].done) doneN++; }
    var label='📓 TACCUINO';
    if(GRS.tac.contracts.length) label+='<span class="gr-tac-badge">'+doneN+'/'+GRS.tac.contracts.length+'</span>';
    if(!btn){
      btn=document.createElement('button'); btn.id='gr-tac-btn'; btn.className='gr-tac-btn';
      btn.onclick=function(){ grTaccuinoOpen(); };
      var hud=document.getElementById('gr-story-hud');
      if(hud && hud.parentNode) hud.parentNode.insertBefore(btn, hud.nextSibling);
      else { var run=document.getElementById('gr-run'); if(run) run.appendChild(btn); else return false; }
    }
    btn.innerHTML=label;
    if(GRS.tacOpen) grTaccuinoRender();
    return true;
  }catch(e){ return false; }
}
function grTaccuinoHtml(){
  var t=GRS.tac||{}, h='', i;
  h+='<div class="gr-tac-h">📓 IL TACCUINO</div>';
  if(t.contract && t.contract.title){
    h+='<div class="gr-tac-sec">IL CONTRATTO</div>'+
       '<div class="gr-tac-ctr-t">✉️ '+grStoryEsc(t.contract.title)+'</div>'+
       (t.contract.text?('<div class="gr-tac-ctr-b">'+grStoryEsc(t.contract.text)+'</div>'):'');
  }
  var cs=t.contracts||[];
  if(cs.length){
    h+='<div class="gr-tac-sec">I FAVORI DELLA NOTTE</div>';
    for(i=0;i<cs.length;i++){
      var c=cs[i]||{};
      var tgt=Math.max(1, c.target||1);
      var prg=Math.max(0, Math.min(tgt, c.progress||0));
      var pct=c.done?100:Math.round(prg/tgt*100);
      h+='<div class="gr-tac-fav'+(c.done?' done':'')+'">'+
         '<div class="gr-tac-fav-t">'+(c.done?'✓ ':'')+grStoryEsc(c.title||'Favore')+(c.done?' — ONORATO':'')+'</div>'+
         (c.reward_desc?('<div class="gr-tac-fav-r">In cambio: '+grStoryEsc(c.reward_desc)+'</div>'):'')+
         '<div class="gr-tac-bar"><div style="width:'+pct+'%;"></div></div>'+
         '<div class="gr-tac-fav-r">'+prg+' / '+tgt+'</div></div>';
    }
  }
  var ch=t.chains||{}, rows='';
  for(var k in ch){
    if(!ch.hasOwnProperty(k)) continue;
    var stg=ch[k]|0; if(stg<=0) continue;
    var dots=''; for(i=0;i<Math.min(stg,6);i++) dots+='●';
    rows+='<div class="gr-tac-chain">🕯️ '+grStoryEsc(grChainName(k))+' <span style="color:#ffd700;letter-spacing:2px;">'+dots+'</span></div>';
  }
  if(rows) h+='<div class="gr-tac-sec">LE VOCI DEL PALAZZO</div>'+rows;
  h+='<button class="gr-tac-close" id="gr-tac-close">RICHIUDI IL TACCUINO</button>';
  return h;
}
function grTaccuinoRender(){
  var card=document.getElementById('gr-tac-card');
  if(!card) return;
  card.innerHTML=grTaccuinoHtml();
  var cl=document.getElementById('gr-tac-close');
  if(cl) cl.onclick=function(){ grStoryRm('gr-tac-ov'); GRS.tacOpen=false; };
}
function grTaccuinoOpen(){
  try{
    if(!GRS.tac) return;
    grStoryRm('gr-tac-ov');
    var ov=document.createElement('div'); ov.className='gr-skill-ov'; ov.id='gr-tac-ov';
    ov.innerHTML='<div class="gr-ev-card gr-tac-card" id="gr-tac-card"></div>';
    var host=document.getElementById('grun')||document.body;
    host.appendChild(ov);
    GRS.tacOpen=true;
    if(typeof grSound==='function'){ try{ grSound('click'); }catch(e){} }
    ov.addEventListener('click', function(e){ if(e.target===ov){ grStoryRm('gr-tac-ov'); GRS.tacOpen=false; } });
    grTaccuinoRender();
  }catch(e){ grStoryRm('gr-tac-ov'); GRS.tacOpen=false; }
}
function grEndEpilogue(d){
  try{
    if(!grStoryOn()) return false;
    var e = d && d.event && d.event.ending;
    if(!e || typeof e!=='object' || !e.text) return false;
    var card=document.querySelector('#gr-end .gr-endcard');
    if(!card) return false;
    var old=document.getElementById('gr-epi'); if(old&&old.parentNode) old.parentNode.removeChild(old);
    var box=document.createElement('div'); box.className='gr-epi'; box.id='gr-epi';
    var badge=(e.idx&&e.total)?('EPILOGO '+e.idx+' DI '+e.total):'EPILOGO';
    var favH='', cs=(d.contracts||[]), done=[], i;
    for(i=0;i<cs.length;i++){ if(cs[i]&&cs[i].done) done.push(cs[i].title||'favore'); }
    if(cs.length){
      favH='<div class="gr-epi-fav">🤝 Favori onorati: <b>'+done.length+'/'+cs.length+'</b>'+
           (done.length?(' — '+grStoryEsc(done.join(' · '))):'')+'</div>';
    }
    box.innerHTML='<div class="gr-epi-badge">'+grStoryEsc(badge)+'</div>'+
      '<div class="gr-epi-ttl" id="gr-epi-ttl"></div>'+
      '<div class="gr-epi-txt">'+grStoryEsc(e.text)+'</div>'+favH;
    card.insertBefore(box, card.firstChild);
    grStoryType(document.getElementById('gr-epi-ttl'), e.title||'LA NOTTE È FINITA', 26);
    return true;
  }catch(err){ return false; }
}
