function grMetaObj(o){ return (o && typeof o==='object') ? o : {}; }
function grMetaMerge(base, p){
  base.nights=+p.nights||0; base.busts=+p.busts||0; base.wins=+p.wins||0;
  base.best_pot=+p.best_pot||0; base.last_result=String(p.last_result||'');
  base.endings=grMetaArrU(p.endings); base.ending_titles=grMetaObj(p.ending_titles);
  base.endings_total=+p.endings_total||24;
  base.muts_seen=grMetaArrU(p.muts_seen); base.rares_seen=grMetaArrU(p.rares_seen);
  base.secrets_found=+p.secrets_found||0; base.npc=grMetaObj(p.npc);
  base.v2=1;
  base.pu_seen=grMetaArrU(p.pu_seen); base.syn_seen=grMetaArrU(p.syn_seen);
  base.unlocks=grMetaArrU(p.unlocks);
  base.chars_unlocked=grMetaArrU(p.chars_unlocked); if(base.chars_unlocked.indexOf('gambler')<0) base.chars_unlocked.push('gambler');
  base.char_selected=String(p.char_selected||'gambler');
  base.runs=(p.runs&&p.runs.length)?p.runs.slice(-30):[];
  base.kills_total=+p.kills_total||0; base.spares_total=+p.spares_total||0;
  base.deepest_floor=+p.deepest_floor||0; base.bosses_beaten=+p.bosses_beaten||0;
  return base;
}
function grMetaLoad(){
  if(GR_META_S.loaded) return GR_META_S.data;
  GR_META_S.loaded=true;
  var d=grMetaDefault();
  try{
    var raw=(typeof localStorage!=='undefined' && localStorage)?localStorage.getItem(GR_META_KEY):null;
    if(raw){ var p=JSON.parse(raw); if(p && typeof p==='object'){ d=grMetaMerge(d,p); } }
  }catch(e){ grWarn('grMetaLoad', e); }
  GR_META_S.data=d; return d;
}
function grMetaSave(){
  if(!grMetaOn() || GR_META_S.dead) return false;
  try{
    if(typeof localStorage==='undefined' || !localStorage){ GR_META_S.dead=true; return false; }
    localStorage.setItem(GR_META_KEY, JSON.stringify(GR_META_S.data));
    return true;
  }catch(e){ GR_META_S.dead=true; grWarn('grMetaSave', e); return false; }
}
function grMetaChronNew(){
  return { _row:null, depth:0, nearBust:false, nearBustPot:null, nightName:null,
           muts:[], rares:[], secrets:0, npcMet:{}, _seen:{} };
}
function grMetaTrack(d){
  if(!grMetaOn() || !d || typeof GRS==='undefined') return;
  var row=d.row||0, ch=GRS.chron;
  if(!ch || (ch._row!=null && row < ch._row - 1)){ ch=GRS.chron=grMetaChronNew(); }
  ch._row=row;
  if(row>ch.depth) ch.depth=row;
  var lives=d.lives||0;
  if(lives<=1 && row>0){ ch.nearBust=true; var p=(d.pot||0); if(ch.nearBustPot==null || p<ch.nearBustPot) ch.nearBustPot=p; }
  try{
    var mut=d.mut||d.muts||d.night, i, mm, mid, mnm;
    if(mut && mut.length){
      for(i=0;i<mut.length;i++){ mm=mut[i]; mid=(mm&&mm.id)||mm; mnm=(mm&&(mm.name||mm.nm))||null;
        if(mid){ grMetaPush(ch.muts, mid); if(mnm && !ch.nightName) ch.nightName=mnm; } }
    } else if(mut && typeof mut==='object'){
      if(mut.id) grMetaPush(ch.muts, mut.id);
      if((mut.name||mut.nm) && !ch.nightName) ch.nightName=mut.name||mut.nm;
    }
  }catch(eM){}
  try{
    var ev=d.event||d.last;
    if(ev){
      if(ev.rare || ev.kind==='rare' || ev.room==='rare'){
        var rid='R:'+((ev.rare_id!=null?ev.rare_id:(ev.id!=null?ev.id:ev.room))||ch.rares.length);
        if(!ch._seen[rid]){ ch._seen[rid]=1; ch.rares.push(ev.rare_id!=null?ev.rare_id:(ev.id!=null?ev.id:'rara')); }
      }
    }
    var fl=d.floor;
    if(fl && fl.nodes && fl.nodes.length){
      var j, n, k;
      for(j=0;j<fl.nodes.length;j++){ n=fl.nodes[j]; if(!n||!n.used) continue;
        if(n.kind==='rare'){ k='r:'+(n.id!=null?n.id:j); if(!ch._seen[k]){ ch._seen[k]=1; ch.rares.push(n.type||n.id||'rara'); } }
        else if(n.kind==='secret'){ k='s:'+(n.id!=null?n.id:j); if(!ch._seen[k]){ ch._seen[k]=1; ch.secrets++; } }
      }
    }
  }catch(eR){}
}
function grMetaRecordEnd(d){
  try{ if(typeof grcRecordEnding==='function') grcRecordEnding(d); }catch(_re3){}
  if(!grMetaOn() || !d) return;
  var m=grMetaLoad(); if(!m) return;
  m.nights=(+m.nights||0)+1;
  var res=d.result||''; m.last_result=res;
  if(res==='bust'||res==='combat_bust') m.busts=(+m.busts||0)+1; else m.wins=(+m.wins||0)+1;
  var bp=+((d.pot!=null)?d.pot:0); if(bp>(+m.best_pot||0)) m.best_pot=Math.round(bp*10000)/10000;
  var e=d.event&&d.event.ending;
  if(e && typeof e==='object' && e.idx!=null){
    grMetaPush(m.endings, e.idx);
    if(e.title) m.ending_titles[''+e.idx]=String(e.title);
    if(e.total) m.endings_total=+e.total;
  }
  var ch=(typeof GRS!=='undefined'&&GRS.chron)?GRS.chron:null, i;
  if(ch){
    if(ch.muts)  for(i=0;i<ch.muts.length;i++)  grMetaPush(m.muts_seen,  ch.muts[i]);
    if(ch.rares) for(i=0;i<ch.rares.length;i++) grMetaPush(m.rares_seen, ch.rares[i]);
    if(ch.secrets>0) m.secrets_found=(+m.secrets_found||0)+ch.secrets;
  }
  grMetaNpcFromEnd(m, d);
  try{
    var depth=(ch&&ch.depth)||(+d.row||0);
    if(depth>(+m.deepest_floor||0)) m.deepest_floor=depth;
    if(res==='beat_house') m.bosses_beaten=(+m.bosses_beaten||0)+1;
    try{ var xm=(typeof grcXmemLoad==='function')?grcXmemLoad():null, sp=0, kk;
      if(xm&&xm.spared){ for(kk in xm.spared){ if(xm.spared.hasOwnProperty(kk)) sp+=(+xm.spared[kk]||0); } }
      if(sp>(+m.spares_total||0)) m.spares_total=sp; }catch(_sp){}
    var prof=''; try{ if(typeof grcRunProfile==='function') prof=grcRunProfile(); }catch(_pr){}
    if(!m.runs) m.runs=[];
    m.runs.push({ n:(+m.nights||0), res:res, depth:depth, potX:Math.round(((d.pot!=null)?d.pot:0)*100)/100, prof:prof, t:(+new Date()) });
    if(m.runs.length>30) m.runs=m.runs.slice(-30);
    if(typeof grMetaCheckUnlocks==='function'){ var newU=grMetaCheckUnlocks(m);
      for(i=0;i<newU.length;i++){ try{ if(typeof toast==='function') toast('🔓 SBLOCCATO: '+newU[i].nm,'ok',3200); }catch(_tu){} } }
  }catch(_m4e){ grWarn('grMetaRecordEnd.m4', _m4e); }
  grMetaSave();
}
function grMetaNpcFromEnd(m, d){
  try{
    var st=(d.story)||{}, fl=(st.flags||[]);
    function ens(id){ if(!m.npc[id]) m.npc[id]={met:0,beaten:0,lost_to_dea:0,spia:0,crew:0}; return m.npc[id]; }
    if(fl.indexOf('spia_del_registro')>=0) ens('lena').spia=1;
    if(fl.indexOf('membro_della_crew')>=0) ens('crew').crew=1;
    var nm=d.npc_mem;
    if(nm && typeof nm==='object'){
      for(var id in nm){ if(!nm.hasOwnProperty(id)) continue; var r=nm[id]; if(!r) continue;
        var o=ens(id);
        if((+r.sfide_v||0)>0) o.beaten=Math.max(+o.beaten||0, +r.sfide_v||0);
        if(id==='dea' && (+r.sfide_p||0)>0) o.lost_to_dea=1;
      }
    }
  }catch(e){ grWarn('grMetaNpcFromEnd', e); }
}
function grMetaRecordNpc(id){
  if(!grMetaOn() || !id) return;
  if(typeof GRS!=='undefined' && GRS.chron){
    if(!GRS.chron.npcMet) GRS.chron.npcMet={};
    if(GRS.chron.npcMet[id]) return;
    GRS.chron.npcMet[id]=1;
  }
  var m=grMetaLoad(); if(!m) return;
  if(!m.npc[id]) m.npc[id]={met:0,beaten:0,lost_to_dea:0,spia:0,crew:0};
  m.npc[id].met=(+m.npc[id].met||0)+1;
  grMetaSave();
}
