function grMetaHost(){ return document.getElementById('grun') || document.body; }
function grGalleryClose(){
  var o=document.getElementById('gr-gal-ov');
  if(o && o.parentNode) o.parentNode.removeChild(o);
}
function grMetaInitStart(){
  if(!grMetaOn()) return;
  if(typeof GRS!=='undefined' && typeof grMetaChronNew==='function') GRS.chron=grMetaChronNew();
  GR_META_S.barked={};
  grGalleryClose();
  var m=grMetaLoad(), btn=document.getElementById('gr-galbtn');
  if(btn){
    var n=(m.endings||[]).length, tot=m.endings_total||24;
    btn.style.display=(m.nights>0 || n>0) ? '' : 'none';
    btn.innerHTML='📖 I FINALI DELLA NOTTE · '+n+'/'+tot;
  }
}
function grColBar(label, n, tot){
  var pct = tot>0 ? Math.max(0, Math.min(100, Math.round(n/tot*100))) : 0;
  return '<div class="gr-col"><div class="gr-col-lbl"><span>'+grStoryEsc(label)+'</span>'+
         '<b>'+n+(tot>0?('/'+tot):'')+'</b></div>'+
         '<div class="gr-col-bar"><div class="gr-col-fill" style="width:'+pct+'%;"></div></div></div>';
}
function grGalleryOpen(){
  if(!grMetaOn()) return;
  try{ if(typeof grcGalleryStoryInject==='function') setTimeout(function(){ try{ grcGalleryStoryInject(); }catch(_gz){} },0); }catch(_gsi){}
  try{ if(typeof grcGalleryMetaInject==='function') setTimeout(function(){ try{ grcGalleryMetaInject(); }catch(_gm){} },0); }catch(_gmi){}
  try{
    grMetaCSS();
    grGalleryClose();
    var m=grMetaLoad();
    var tot=m.endings_total||24, unlocked={}, i;
    for(i=0;i<(m.endings||[]).length;i++){ unlocked[''+m.endings[i]]=1; }
    var nEnd=(m.endings||[]).length;
    var grid='';
    for(i=1;i<=tot;i++){
      var key=''+i, on=!!unlocked[key];
      if(on){
        var t=m.ending_titles[key]||('EPILOGO '+i);
        grid+='<div class="gr-gal-c ok"><div class="gr-gal-i">📜</div>'+
              '<div class="gr-gal-t">'+grStoryEsc(t)+'</div><div class="gr-gal-n">#'+i+'</div></div>';
      } else {
        grid+='<div class="gr-gal-c"><div class="gr-gal-i">🔒</div>'+
              '<div class="lock">— ? —</div><div class="gr-gal-n">#'+i+'</div></div>';
      }
    }
    var cols =
      grColBar('📖 Epiloghi',   nEnd,                        tot) +
      grColBar('🌙 Mutatori',   (m.muts_seen||[]).length,    16)  +
      grColBar('🚪 Sale rare',  (m.rares_seen||[]).length,   4)   +
      grColBar('🔍 Segreti trovati', (+m.secrets_found||0),  0);
    var html =
      '<div class="gr-gal-hd">'+
        '<div class="gr-gal-ttl">📖 I FINALI DELLA NOTTE · '+nEnd+'/'+tot+'</div>'+
        '<button class="gr-gal-x" onclick="grGalleryClose()">CHIUDI ✕</button>'+
      '</div>'+
      '<div class="gr-gal-sub">Il Palazzo ha ancora stanze che non hai visto.</div>'+
      '<div class="gr-gal-grid">'+grid+'</div>'+
      cols+
      '<div class="gr-col-foot">'+grStoryEsc(grMetaFootline(m))+'</div>';
    var ov=document.createElement('div'); ov.className='gr-gal-ov'; ov.id='gr-gal-ov';
    ov.innerHTML=html;
    grMetaHost().appendChild(ov);
    if(typeof grSound==='function'){ try{ grSound('chip'); }catch(e){} }
  }catch(e){ grWarn('grGalleryOpen', e); grGalleryClose(); }
}
function grMetaFootline(m){
  var parts=[];
  parts.push('Notti: '+(+m.nights||0));
  parts.push('Vittorie: '+(+m.wins||0));
  parts.push('Bust: '+(+m.busts||0));
  if((+m.best_pot||0)>0) parts.push('Miglior pot ×'+(+m.best_pot).toFixed(2));
  return parts.join('  ·  ');
}
