function grChronBeats(d){
  var beats=[], ch=(typeof GRS!=='undefined'&&GRS.chron)?GRS.chron:null;
  if(ch && ch.nightName) beats.push('🌙 '+ch.nightName);
  if(ch && ch.rares && ch.rares.length) beats.push('🚪 Hai varcato una sala rara');
  if(ch && ch.secrets>0) beats.push('🔍 Segreti scoperti stanotte: '+ch.secrets);
  if(ch && ch.nearBust){
    var np=(ch.nearBustPot!=null)?ch.nearBustPot:(d.pot||0);
    beats.push('🫀 Un soffio dal baratro — ultima vita, pot ×'+(+np).toFixed(2));
  }
  var res=d.result, depth=(ch&&ch.depth)||(d.row||0), maxr=d.max_rows||12;
  if(res==='bust'||res==='combat_bust') beats.push('💀 Bruciato al piano '+depth+' di '+maxr);
  else if(res==='beat_house') beats.push('🏛️ Hai battuto la Casa · pot ×'+(+(d.pot||1)).toFixed(2));
  else                        beats.push('💰 Incassato al piano '+depth+' · pot ×'+(+(d.pot||1)).toFixed(2));
  var e=d.event&&d.event.ending;
  if(e && typeof e==='object' && e.idx!=null){
    beats.push('📖 Epilogo '+e.idx+(e.total?('/'+e.total):'')+(e.title?(' · '+e.title):''));
  }
  return beats.slice(0,6);
}
function grChronicle(d){
  if(!grMetaOn() || !d) return false;
  try{
    var card=document.querySelector('#gr-end .gr-endcard');
    if(!card) return false;
    var beats=grChronBeats(d);
    if(!beats.length) return false;
    grChronCSS();
    var old=document.getElementById('gr-chron'); if(old&&old.parentNode) old.parentNode.removeChild(old);
    var i, rows='';
    for(i=0;i<beats.length;i++){ rows+='<div class="gr-chron-b">'+grStoryEsc(beats[i])+'</div>'; }
    var box=document.createElement('div'); box.className='gr-chron'; box.id='gr-chron';
    box.innerHTML='<div class="gr-chron-ttl">🎟️ LA CRONACA DELLA NOTTE</div>'+rows+
      '<button class="gr-chron-share" id="gr-chron-share" onclick="grChronShare()">🎟️ Copia il biglietto del Palazzo</button>';
    box.setAttribute('data-share', 'GAMBLER RUN — La cronaca della notte\n• '+beats.join('\n• '));
    var epi=document.getElementById('gr-epi');
    if(epi && epi.nextSibling) card.insertBefore(box, epi.nextSibling);
    else card.insertBefore(box, card.firstChild);
    return true;
  }catch(e){ grWarn('grChronicle', e); return false; }
}
function grChronShare(){
  try{
    var box=document.getElementById('gr-chron'); if(!box) return;
    var txt=box.getAttribute('data-share')||'';
    var done=function(){ if(typeof toast==='function'){ try{ toast('🎟️ Biglietto copiato','gold',2200); }catch(e){} } };
    if(navigator && navigator.clipboard && navigator.clipboard.writeText){
      navigator.clipboard.writeText(txt).then(done, function(){ grChronShareFallback(txt, done); });
    } else { grChronShareFallback(txt, done); }
  }catch(e){ grWarn('grChronShare', e); }
}
function grChronShareFallback(txt, done){
  try{
    var ta=document.createElement('textarea'); ta.value=txt;
    ta.style.cssText='position:fixed;left:-9999px;top:0;opacity:0;';
    document.body.appendChild(ta); ta.focus(); ta.select();
    try{ document.execCommand('copy'); }catch(e){}
    document.body.removeChild(ta); if(done) done();
  }catch(e){ grWarn('grChronShareFallback', e); }
}
