function grRpgAct(){
  if(typeof GR_RPG_ON==='undefined' || !GR_RPG_ON) return false;
  if(!GRX.floorData || GRX.nearIt==null || GRX.nearIt<0) return false;
  var its=GRX.interactables||[], it=its[GRX.nearIt];
  if(!it) return false;
  if(GR.busy || !GR.view || GR.view.over || GRX.entering) return true;
  if(it.kind==='npc'){
    if(typeof grNpcTalk!=='function') return true;
    var e=null, i;
    if(GRX.npcs){ for(i=0;i<GRX.npcs.length;i++){ if(GRX.npcs[i].id===it.idx){ e=GRX.npcs[i]; break; } } }
    try{
      if(e) grNpcTalk(e);
      else if(it.node && it.node.npc) grNpcTalk(it.node.npc);
    }catch(e1){ grWarn('grExpTap.npcTalk', e1); }
    return true;
  }
  if(it.kind==='parley'){
    if(typeof GR_TALK_ON!=='undefined' && !GR_TALK_ON){
      if(typeof grNpcTalk==='function' && it.node && it.node.npc){
        try{ grNpcTalk(it.node.npc); }catch(ept){ grWarn('grExpTap.parleyTalk', ept); }
      }
      return true;
    }
    try{ grActEvent(it.idx); }catch(ep){ grWarn('grExpTap.parley', ep); }
    return true;
  }
  if(it.kind==='secret'){
    try{ grActEvent(it.idx); }catch(e2){ grWarn('grExpTap.secretEvent', e2); }
    return true;
  }
  if(it.kind==='merchant' && typeof grMerchantOverlay==='function'){
    try{
      grMerchantOverlay({ idx:it.idx,
                          type:(it.node&&it.node.type)||it.type||'',
                          charm:(it.node&&it.node.charm)||null });
      return true;
    }catch(e3){ grWarn('grExpTap.merchant', e3); }
  }
  if(it.locked){
    try{ toast('🔒 Serve la chiave del piano','warn',2000); }catch(e4){}
    try{ grSound('tick'); }catch(e5){}
    return true;
  }
  if(it.si>=0){ grExpEnter(it.si); }
  else { try{ grAct(it.idx); }catch(e6){ grWarn('grExpTap.act', e6); } }
  return true;
}
var GBMusic=(function(){
  var ctx=null, master=null, enabled=true, theme=null, curName=null, timer=null, step=0, booted=false;
  function mtof(n){ return 440*Math.pow(2,(n-69)/12); }
  var THEMES={
    menu:      {bpm:124, root:48, wave:'square',   bass:[0,7,0,7,5,7,5,2],     lead:[24,28,31,28,24,28,31,35]},
    run:       {bpm:98,  root:45, wave:'square',   bass:[0,0,3,3,7,5,3,0],     lead:[24,27,31,27,24,22,24,19]},
    table:     {bpm:112, root:48, wave:'square',   bass:[0,5,7,5,0,5,7,9],     lead:[24,28,31,28,29,28,24,21]},
    highroller:{bpm:150, root:50, wave:'square',   bass:[0,0,5,5,7,7,10,10],   lead:[26,31,34,31,38,34,31,26]},
    vault:     {bpm:120, root:53, wave:'triangle', bass:[0,4,7,4,9,7,4,0],     lead:[28,31,36,31,33,31,28,24]},
    fixer:     {bpm:84,  root:46, wave:'square',   bass:[0,1,3,1,6,3,1,-1],    lead:[24,25,28,25,30,28,25,22]},
    duel:      {bpm:138, root:45, wave:'square',   bass:[0,0,7,7,3,3,7,7],     lead:[24,24,27,31,30,27,24,19]},
    house:     {bpm:88,  root:40, wave:'sawtooth', bass:[0,0,1,1,3,3,1,0],     lead:[12,15,12,18,17,15,12,11]},
    arena:     {bpm:144, root:48, wave:'square',   bass:[0,7,0,7,3,10,7,5],    lead:[24,27,31,34,31,27,24,22]},
    win:       {bpm:150, root:53, wave:'square',   bass:[0,7,12,7,0,7,12,16],  lead:[28,31,36,40,36,31,36,40]}
  };
  var SCENE={home:'menu',grun:'run',duel:'arena',slots:'highroller',roulette:'table',wheel:'table',
             plinko:'table',dice:'table',poker:'duel',scratch:'fixer',crash:'highroller',lotto:'vault',bj:'table'};
  function ensure(){
    if(ctx) return true;
    var AC=window.AudioContext||window.webkitAudioContext; if(!AC) return false;
    try{ ctx=new AC(); master=ctx.createGain(); master.gain.value=0.085; master.connect(ctx.destination); }catch(e){ return false; }
    return !!ctx;
  }
  function blip(freq,dur,wave,vol){
    if(!ctx||!isFinite(freq)) return;
    try{
      var o=ctx.createOscillator(), g=ctx.createGain(), t=ctx.currentTime;
      o.type=wave||'square'; o.frequency.value=freq;
      g.gain.setValueAtTime(0.0001,t); g.gain.linearRampToValueAtTime(vol||0.2,t+0.012);
      g.gain.exponentialRampToValueAtTime(0.0008,t+dur);
      o.connect(g); g.connect(master); o.start(t); o.stop(t+dur+0.03);
    }catch(e){}
  }
  function tick(){
    if(!theme||!enabled||!ctx) return;
    var s=step%8, dur=theme.stepDur;
    blip(mtof(theme.root+theme.bass[s])/2, dur*0.95, 'triangle', 0.30);
    blip(mtof(theme.root+theme.lead[s]),    dur*0.5,  theme.wave,  0.12);
    if(s%2===0) blip(mtof(theme.root+theme.lead[(s+2)%8]+7), dur*0.3, theme.wave, 0.05);
    step++;
  }
  function start(){
    if(timer) clearInterval(timer); timer=null;
    if(!enabled||!theme) return;
    if(!ensure()) return;
    if(ctx.state==='suspended'){ try{ ctx.resume(); }catch(e){} }
    timer=setInterval(tick, theme.stepDur*1000);
  }
  function play(name){
    if(!THEMES[name]) return;
    if(name===curName && timer) return;
    curName=name; var t=THEMES[name];
    theme={root:t.root,wave:t.wave,bass:t.bass,lead:t.lead,stepDur:(60/t.bpm)/2};
    step=0; start();
  }
  function stop(){ if(timer){ clearInterval(timer); timer=null; } curName=null; theme=null; }
  function inRun(){ return (typeof CUR!=='undefined') && CUR==='grun'; }
  function boot(){
    if(booted) return; booted=true;
    try{ var m=localStorage.getItem('gb_music'); if(m==='off') enabled=false; }catch(e){}
    var btn=document.createElement('button'); btn.id='gb-music-btn';
    btn.setAttribute('aria-label','Music'); btn.textContent=enabled?'🔊':'🔇';
    btn.style.display='none';
    btn.onclick=function(ev){ ev.stopPropagation(); toggle(); };
    if(document.body) document.body.appendChild(btn);
    var kick=function(){ if(ensure()&&ctx.state==='suspended'){ try{ctx.resume();}catch(e){} } if(enabled&&!timer&&theme&&inRun()) start(); };
    ['pointerdown','touchstart','click','keydown'].forEach(function(ev){ document.addEventListener(ev,kick,{once:false,passive:true}); });
  }
  function toggle(){
    enabled=!enabled;
    try{ localStorage.setItem('gb_music', enabled?'on':'off'); }catch(e){}
    var b=document.getElementById('gb-music-btn'); if(b) b.textContent=enabled?'🔊':'🔇';
    if(enabled && inRun()){ if(!theme) curName=null, play('run'); else start(); }
    else { if(timer){ clearInterval(timer); timer=null; } }
  }
  function scene(id){
    boot();
    var b=document.getElementById('gb-music-btn');
    if(id==='grun'){ if(b)b.style.display=''; play('run'); }
    else { if(b)b.style.display='none'; stop(); }
  }
  return {boot:boot, scene:scene, play:play, stop:stop, toggle:toggle, has:function(n){return !!THEMES[n];}};
})();
