function slv2EnsureAudio(){
  if(SL2.audioCtx) return SL2.audioCtx;
  try {
    var Ctx = window.AudioContext || window.webkitAudioContext;
    if(Ctx){
      SL2.audioCtx = new Ctx();
      var comp = SL2.audioCtx.createDynamicsCompressor();
      comp.threshold.value = -10;
      comp.knee.value      = 8;
      comp.ratio.value     = 6;
      comp.attack.value    = 0.003;
      comp.release.value   = 0.18;
      var masterGain = SL2.audioCtx.createGain();
      masterGain.gain.value = 0.92;
      comp.connect(masterGain).connect(SL2.audioCtx.destination);
      SL2.audioMaster = comp;
    }
  } catch(e){}
  return SL2.audioCtx;
}
function slv2AudioDest(){
  if(!SL2.audioCtx) slv2EnsureAudio();
  return (SL2 && SL2.audioMaster) || (SL2.audioCtx && SL2.audioCtx.destination);
}
function slv2QueueSpin(delayMs, options){
  var delay = typeof delayMs === 'number' ? delayMs : 600;
  var requireAuto = !!(options && options.requireAuto);
  var pollStart = performance.now();
  function tryFire(){
    if(!SL2) return;
    if(requireAuto && !SL2.autoActive) return;
    var blocked = SL2.spinning || SL2.fakeRevealActive || SL2.scatterIntroActive ||
                  SL2.pendingWheelTrigger || SL2.bonusWheelOpen || SL2.vaultOpen ||
                  SL2.fsIntroActive;
    if(!blocked){
      if(SL2.srvMode && !SL2.fsActive){ slv2SpinFetch(); }
      else { slv2Spin(); }
      return;
    }
    if(performance.now() - pollStart > 12000){
      if(SL2.autoActive){
        SL2.autoActive = false;
        if(typeof slv2EnableSpinIfIdle === 'function') slv2EnableSpinIfIdle();
      }
      return;
    }
    setTimeout(tryFire, 220);
  }
  setTimeout(tryFire, delay);
}
function slv2HardResetSpinState(){
  SL2.spinning            = false;
  SL2.fakeRevealActive    = false;
  SL2.scatterIntroActive  = false;
  SL2.pendingWheelTrigger = false;
  SL2.fsIntroActive       = false;
  if(SL2._wheelHeartbeatId){
    clearInterval(SL2._wheelHeartbeatId);
    SL2._wheelHeartbeatId = null;
  }
  if(SL2._crawlTimers){
    for(var ci in SL2._crawlTimers){
      if(SL2._crawlTimers[ci]) SL2._crawlTimers[ci].forEach(function(t){ clearTimeout(t); });
      SL2._crawlTimers[ci] = [];
    }
  }
  if(SL2.reelTimers){
    for(var ri in SL2.reelTimers){
      if(SL2.reelTimers[ri]) clearTimeout(SL2.reelTimers[ri]);
      SL2.reelTimers[ri] = null;
    }
  }
  if(SL2.reelWatchdogs){
    for(var rwi in SL2.reelWatchdogs){
      if(SL2.reelWatchdogs[rwi]) clearTimeout(SL2.reelWatchdogs[rwi]);
      SL2.reelWatchdogs[rwi] = null;
    }
  }
  if(SL2.reelSpinning){
    for(var rsi in SL2.reelSpinning) SL2.reelSpinning[rsi] = false;
  }
  if(typeof slv2ClearAnticipation === 'function') slv2ClearAnticipation();
  if(typeof slv2StopRouletteTicker === 'function') slv2StopRouletteTicker();
  if(typeof slv2RemoveWheelTriggerBeams === 'function') slv2RemoveWheelTriggerBeams();
  if(!SL2.bonusWheelOpen && !SL2.vaultOpen && !SL2.fsActive){
    if(typeof slv2EnableSpin === 'function') slv2EnableSpin();
  }
}
