function slv2PlayTone(freq, durSec, type, vol){
  if(!SL2.soundsEnabled) return;
  var ctx = slv2EnsureAudio();
  if(!ctx) return;
  try {
    var osc = ctx.createOscillator();
    var gain = ctx.createGain();
    osc.type = type || 'sine';
    osc.frequency.value = freq;
    gain.gain.value = 0;
    osc.connect(gain);
    gain.connect(slv2AudioDest());
    var t0 = ctx.currentTime;
    var v = vol || 0.15;
    gain.gain.setValueAtTime(0, t0);
    gain.gain.linearRampToValueAtTime(v, t0 + 0.005);
    gain.gain.exponentialRampToValueAtTime(0.0001, t0 + durSec);
    osc.start(t0);
    osc.stop(t0 + durSec + 0.05);
  } catch(e){}
}
function slv2GetReverb(){
  if(SL2.reverbNode) return SL2.reverbNode;
  var ctx = slv2EnsureAudio();
  if(!ctx) return null;
  try {
    var convolver = ctx.createConvolver();
    var sr = ctx.sampleRate;
    var len = Math.floor(sr * 2.4);
    var impulse = ctx.createBuffer(2, len, sr);
    for(var ch = 0; ch < 2; ch++){
      var data = impulse.getChannelData(ch);
      for(var i = 0; i < len; i++){
        var t = i / len;
        data[i] = (Math.random() * 2 - 1) * Math.pow(1 - t, 2.4);
      }
    }
    convolver.buffer = impulse;
    var wet = ctx.createGain();
    wet.gain.value = 0.42;
    convolver.connect(wet);
    wet.connect(slv2AudioDest());
    SL2.reverbNode = convolver;
    SL2.reverbWet  = wet;
    return convolver;
  } catch(e){ return null; }
}
function slv2PlayToneEx(freq, durSec, type, vol, opts){
  if(!SL2.soundsEnabled) return;
  opts = opts || {};
  var ctx = slv2EnsureAudio();
  if(!ctx) return;
  try {
    var osc  = ctx.createOscillator();
    var gain = ctx.createGain();
    osc.type = type || 'sine';
    osc.frequency.value = freq;
    gain.gain.value = 0;
    osc.connect(gain);
    gain.connect(slv2AudioDest());
    if(opts.reverb){
      var rev = slv2GetReverb();
      if(rev){
        var send = ctx.createGain();
        send.gain.value = (opts.revSend != null) ? opts.revSend : 0.6;
        gain.connect(send);
        send.connect(rev);
      }
    }
    var t0  = ctx.currentTime;
    var v   = (vol != null) ? vol : 0.15;
    var atk = opts.attack  != null ? opts.attack  : 0.006;
    var rel = opts.release != null ? opts.release : durSec * 0.5;
    gain.gain.setValueAtTime(0, t0);
    gain.gain.linearRampToValueAtTime(v, t0 + atk);
    gain.gain.exponentialRampToValueAtTime(0.0001, t0 + durSec + rel);
    osc.start(t0);
    osc.stop(t0 + durSec + rel + 0.1);
  } catch(e){}
}
function slv2PlayNoise(durSec, vol, filterFreq, q, reverb){
  if(!SL2.soundsEnabled) return;
  var ctx = slv2EnsureAudio();
  if(!ctx) return;
  try {
    var bufSize = Math.max(1, Math.floor(ctx.sampleRate * durSec));
    var buf = ctx.createBuffer(1, bufSize, ctx.sampleRate);
    var data = buf.getChannelData(0);
    for(var i = 0; i < bufSize; i++){
      data[i] = (Math.random() * 2 - 1) * (1 - i / bufSize);
    }
    var src  = ctx.createBufferSource();
    src.buffer = buf;
    var filt = ctx.createBiquadFilter();
    filt.type = 'bandpass';
    filt.frequency.value = filterFreq || 2200;
    filt.Q.value = q || 1.4;
    var gain = ctx.createGain();
    gain.gain.value = vol || 0.06;
    src.connect(filt); filt.connect(gain); gain.connect(slv2AudioDest());
    if(reverb){
      var rev = slv2GetReverb();
      if(rev){
        var send = ctx.createGain(); send.gain.value = 0.45;
        gain.connect(send); send.connect(rev);
      }
    }
    src.start();
  } catch(e){}
}
