function gPlayNoiseBuf(ctx, durSec, filterFreq, gen){
  try {
    var sr = ctx.sampleRate;
    var len = Math.floor(sr * durSec);
    var buf = ctx.createBuffer(1, len, sr);
    var data = buf.getChannelData(0);
    for(var i = 0; i < len; i++) data[i] = gen(i / sr);
    var src = ctx.createBufferSource();
    src.buffer = buf;
    var filt = ctx.createBiquadFilter();
    filt.type = 'lowpass';
    filt.frequency.value = filterFreq;
    src.connect(filt);
    filt.connect(slv2AudioDest());
    src.start();
  } catch(e){}
}
function slv2BuildStrip(reelIdx){
  var strip = document.getElementById('slv2-strip-' + reelIdx);
  if(!strip) return;
  strip.innerHTML = '';
  SL2.stripSyms[reelIdx] = [];
  var arr = [];
  for(var rep = 0; rep < Math.ceil(SL2_STRIP_LEN / SL2_REEL.length) + 1; rep++){
    var copy = SL2_REEL.slice();
    for(var i = copy.length - 1; i > 0; i--){
      var j = Math.floor(Math.random() * (i + 1));
      var tmp = copy[i]; copy[i] = copy[j]; copy[j] = tmp;
    }
    arr = arr.concat(copy);
  }
  for(var k = 0; k < SL2_STRIP_LEN; k++){
    var sym = arr[k];
    SL2.stripSyms[reelIdx].push(sym);
    var div = document.createElement('div');
    div.className = 'slv2-sym sym-' + sym;
    if(sym === 'btc'){
      div.innerHTML = slv2GbLogoHTML();
    } else if(sym === 'gblogo'){
      div.innerHTML = slv2BtcCoinHTML();
    } else if(sym === 'ton'){
      div.innerHTML = slv2TonCoinHTML();
    } else if(sym === 'wheel'){
      div.innerHTML = slv2WheelSVG();
    } else {
      div.textContent = SL2_CHAR[sym];
    }
    strip.appendChild(div);
  }
  var startIdx = 5 + Math.floor(Math.random() * 10);
  SL2.positions[reelIdx] = startIdx;
  strip.style.transition = 'none';
  var offset = -((startIdx - 1) * SL2_SYM_H);
  strip.style.setProperty('--final-y', offset + 'px');
  strip.style.transform = 'translateY(' + offset + 'px)';
  slv2UpdateGridFromStrip(reelIdx);
}
function slv2UpdateGridFromStrip(reelIdx){
  var pos = SL2.positions[reelIdx];
  var syms = SL2.stripSyms[reelIdx];
  SL2.grid[reelIdx] = [
    syms[pos - 1] || syms[0],
    syms[pos] || syms[0],
    syms[pos + 1] || syms[0]
  ];
  var strip = document.getElementById('slv2-strip-' + reelIdx);
  if(strip){
    if(strip._lastActive){
      strip._lastActive.forEach(function(el){ if(el) el.classList.remove('slv2-sym-active'); });
    }
    var active = [];
    [pos - 1, pos, pos + 1].forEach(function(idx){
      if(idx >= 0 && idx < strip.children.length){
        var el = strip.children[idx];
        if(el){ el.classList.add('slv2-sym-active'); active.push(el); }
      }
    });
    strip._lastActive = active;
  }
}
function slv2Init(){
  for(var i = 0; i < 5; i++) slv2BuildStrip(i);
  slv2RenderPaytable();
  var disp = document.getElementById('slv2-spin-bet');
  if(disp) disp.textContent = '\u20ac' + SL2.bet.toFixed(2);
  slv2UpdateJackpotDisplay();
  slv2StartJackpotPolling();
  var fsCard = document.getElementById('slv2-fs-card');
  var fsCount = document.getElementById('slv2-fs-count');
  if(fsCard) fsCard.classList.remove('active');
  if(fsCount) fsCount.textContent = '0';
  var lw = document.getElementById('slv2-last-win');
  if(lw){ lw.className = 'slv2-stat-val'; lw.textContent = '\u20ac0.00'; }
  if(typeof currentBet !== 'undefined') currentBet.slots = SL2.bet;
}
function slv2SetBet(amount, btn){
  if(SL2.spinning || SL2.autoActive) return;
  SL2.bet = amount;
  slv2Sound('click');
  var row = btn ? btn.parentElement : null;
  if(row){
    row.querySelectorAll('.slv2-bet').forEach(function(b){ b.classList.remove('active'); });
    btn.classList.add('active');
  }
  var disp = document.getElementById('slv2-spin-bet');
  if(disp) disp.textContent = '\u20ac' + amount.toFixed(2);
  if(typeof currentBet !== 'undefined') currentBet.slots = amount;
}
function slv2ToggleTurbo(){
  SL2.turbo = !SL2.turbo;
  slv2Sound('click');
  var btn = document.getElementById('slv2-turbo-btn');
  if(btn){
    if(SL2.turbo) btn.classList.add('active');
    else btn.classList.remove('active');
  }
}
function slv2UpdateJackpotDisplay(){
  var jp = document.getElementById('slv2-jackpot');
  if(jp) jp.textContent = '\u20ac' + SL2.jackpotEur.toFixed(2);
}
function slv2FetchJackpot(){
  if(typeof BACKEND === 'undefined') return;
  fetch(BACKEND + '/jackpot', {
    headers: {'ngrok-skip-browser-warning': '1', 'Accept': 'application/json'}
  })
  .then(function(r){ return r.json(); })
  .then(function(data){
    if(data && typeof data.pool_eur === 'number'){
      SL2.jackpotEur = data.pool_eur;
      slv2UpdateJackpotDisplay();
      SL2.jackpotLastWinner = data.last_winner;
      SL2.jackpotLastAmount = data.last_amount_eur || 0;
    }
  })
  .catch(function(){   });
}
function slv2SendSlotEvent(eventName, extra){
  if(typeof BACKEND === 'undefined') return;
  var userId = (window.S && window.S.userId) ? window.S.userId : null;
  if(!userId) return;
  try {
    fetch(BACKEND + '/slot_event', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'ngrok-skip-browser-warning': '1'
      },
      body: JSON.stringify({
        user_id: userId,
        event: eventName,
        extra: extra || {}
      }),
      keepalive: true
    }).catch(function(){});
  } catch(e){}
}
function slv2ContributeJackpot(betEur){
  if(typeof BACKEND === 'undefined') return;
  var userId = (window.S && window.S.userId) ? window.S.userId : null;
  if(!userId || !betEur || betEur <= 0) return;
  var rate = (window.S && window.S.btcRate) ? window.S.btcRate : 90000;
  var betBtc = betEur / rate;
  fetch(BACKEND + '/jackpot/contribute', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'ngrok-skip-browser-warning': '1'
    },
    body: JSON.stringify({ user_id: userId, bet_btc: betBtc }),
    keepalive: true
  })
  .then(function(r){ return r.json(); })
  .then(function(data){
    if(data && typeof data.pool_eur === 'number'){
      SL2.jackpotEur = data.pool_eur;
      slv2UpdateJackpotDisplay();
    }
  })
  .catch(function(){   });
}
SL2.jackpotPollTimer = null;
function slv2StartJackpotPolling(){
  slv2FetchJackpot();
  if(SL2.jackpotPollTimer) clearInterval(SL2.jackpotPollTimer);
  SL2.jackpotPollTimer = setInterval(slv2FetchJackpot, 8000);
}
function slv2StopJackpotPolling(){
  if(SL2.jackpotPollTimer){
    clearInterval(SL2.jackpotPollTimer);
    SL2.jackpotPollTimer = null;
  }
}
