function slv2OpenPaytable(){
  var sh = document.getElementById('slv2-paytable-sheet');
  if(!sh) return;
  var pt = document.getElementById('slv2-paytable-content');
  if(pt && !pt.children.length) slv2RenderPaytable();
  sh.classList.add('visible');
  slv2Sound('click');
}
function slv2ClosePaytable(ev){
  if(ev && ev.currentTarget && ev.target !== ev.currentTarget) return;
  var sh = document.getElementById('slv2-paytable-sheet');
  if(!sh) return;
  sh.classList.remove('visible');
  slv2Sound('click');
}
function slv2SpinFetch(){
  if(SL2.spinning) return;
  var bet = SL2.bet;
  if(!hasFunds(bet)){ toast('Insufficient balance', 'err'); slv2StopAuto(); return; }
  if(!S.userId){ toast('Open in Telegram to play', 'err'); slv2StopAuto(); return; }
  var btn = document.getElementById('slv2-spin-btn'); if(btn) btn.disabled = true;
  uiBusy(true, 'Spinning…');
  fetch(BACKEND + '/play/slots', {
    method:'POST', headers:{'Content-Type':'application/json','ngrok-skip-browser-warning':'1'},
    body:JSON.stringify({user_id:S.userId, ...postaCent(bet)})
  }).then(function(r){ return r.json(); }).then(function(d){
    if(btn) btn.disabled = false;
    if(!d || d.error){
      uiBusy(false);
      toast('⚠️ ' + ((d && d.error) || 'Network error - retry'), 'err');
      slv2StopAuto();
      if(typeof loadBalance === 'function') loadBalance();
      return;
    }
    SL2.srv = { round: d.round, cursor: 0, wheelShown: false,
                finalBtc: d.btc, jackpot: !!d.jackpot,
                wins: d.wins, losses: d.losses,
                total_bet_eur: d.total_bet_eur, biggest_win_eur: d.biggest_win_eur };
    SL2.srvMode = true;
    SL2.srvFsWheelCursor = 0;
    SL2.srvWheel = null;
    if(typeof slv2ContributeJackpot === 'function'){ try{ slv2ContributeJackpot(bet); }catch(e){} }
    S.btc = Math.max(0, S.btc - eurToBtc(bet)); refresh();
    uiBusy(false);
    slv2Spin();
  }).catch(function(e){
    if(btn) btn.disabled = false;
    uiBusy(false);
    toast('Network error', 'err');
    slv2StopAuto();
    if(typeof loadBalance === 'function') loadBalance();
  });
}
function slv2StampCell(strip, symbols, idx, sym){
  if(idx < 0 || idx >= symbols.length) return;
  symbols[idx] = sym;
  var cell = strip.children[idx];
  if(!cell) return;
  cell.className = 'slv2-sym sym-' + sym;
  if(sym === 'btc'){ cell.innerHTML = slv2GbLogoHTML(); }
  else if(sym === 'gblogo'){ cell.innerHTML = slv2BtcCoinHTML(); }
  else if(sym === 'ton'){ cell.innerHTML = slv2TonCoinHTML(); }
  else if(sym === 'wheel'){ cell.innerHTML = slv2WheelSVG(); }
  else { cell.textContent = SL2_CHAR[sym]; }
}
function slv2SrvReconcile(){
  if(!SL2.srvMode || !SL2.srv) return;
  var s = SL2.srv;
  if(!s.jackpot && s.finalBtc !== undefined) S.btc = s.finalBtc;
  if(s.wins !== undefined) S.wins = s.wins;
  if(s.losses !== undefined) S.losses = s.losses;
  if(s.total_bet_eur !== undefined) S.totalBet = s.total_bet_eur;
  if(s.biggest_win_eur !== undefined) S.biggestWin = s.biggest_win_eur;
  SL2.srvMode = false; SL2.srv = null; SL2.srvCols = null; SL2.srvWheel = null;
  SL2.srvTumbles = null; SL2.srvCascCur = null;
  refresh(); if(CUR === 'profile') renderProfile();
}
function slv2SpinOrStop(){
  if(SL2.fakeRevealActive)    return;
  if(SL2.bonusWheelOpen)      return;
  if(SL2.vaultOpen)           return;
  if(SL2.fsIntroActive)       return;
  if(SL2.scatterIntroActive)  return;
  if(SL2.pendingWheelTrigger) return;
  if(SL2.spinning){
    var anySpinning = false;
    if(SL2.reelSpinning){
      for(var r = 0; r < 5; r++){
        if(SL2.reelSpinning[r]){ anySpinning = true; break; }
      }
    }
    if(anySpinning){
      if(!SL2.srvMode) slv2QuickStopAllReels();
      return;
    }
    return;
  }
  slv2SpinFetch();
}
function slv2SetSpinButtonMode(mode){
  var btn = document.getElementById('slv2-spin-btn');
  if(!btn) return;
  var icon = btn.querySelector('.slv2-spin-icon');
  var txt  = btn.querySelector('.slv2-spin-txt');
  if(mode === 'stop'){
    btn.classList.add('stop-mode');
    if(icon) icon.textContent = '✋';
    if(txt)  txt.textContent  = 'STOP';
  } else {
    btn.classList.remove('stop-mode');
    if(icon) icon.textContent = '🎰';
    if(txt)  txt.textContent  = 'SPIN';
  }
}
function slv2Spin(){
  if(SL2.spinning) return;
  if(SL2.fakeRevealActive) return;
  if(SL2.scatterIntroActive) return;
  if(SL2.pendingWheelTrigger) return;
  if(SL2.bonusWheelOpen) return;
  if(SL2.vaultOpen) return;
  if(SL2.fsIntroActive) return;
  if(!SL2._videosWarmed){
    SL2._videosWarmed = true;
    ['slv2-fs-intro-video', 'slv2-bw-video', 'slv2-vg-video'].forEach(function(id){
      var v = document.getElementById(id);
      if(!v || !v.getAttribute('src')) return;
      try {
        v.muted = true;
        var p = v.play();
        if(p && p.then){
          p.then(function(){
            try { v.pause(); v.currentTime = 0; } catch(_e){}
          }).catch(function(){   });
        }
      } catch(e){   }
    });
    try {
      var ctx = (typeof slv2EnsureAudio === 'function') ? slv2EnsureAudio() : null;
      if(ctx && ctx.state === 'suspended') ctx.resume();
    } catch(e){}
  }
  var isFreeSpin = SL2.fsActive && SL2.fsRemaining > 0;
  if(!isFreeSpin){
    var bet = SL2.bet;
    if(!hasFunds(bet)){
      toast('Insufficient balance', 'err');
      slv2StopAuto();
      return;
    }
    if(!SL2.srvMode){ if(!placeBet(bet, 'slots')){ slv2StopAuto(); return; } }
    slv2ContributeJackpot(bet);
  }
  SL2.spinning = true;
  SL2.cascadeLevel = 0;
  SL2.cascadeWinTotal = 0;
  if(SL2.srvMode){ slv2DisableSpin(); } else { slv2SetSpinButtonMode('stop'); }
  var betRow = document.querySelector('.slv2-bet-row');
  if(betRow) betRow.classList.add('locked');
  var slvRoot = document.querySelector('.slv2');
  if(slvRoot) slvRoot.classList.add('is-spinning');
  var svg = document.getElementById('slv2-payline-svg');
  if(svg) svg.innerHTML = '';
  var ov = document.getElementById('slv2-win-overlay');
  if(ov) ov.innerHTML = '';
  for(var r = 0; r < 5; r++){
    var strip = document.getElementById('slv2-strip-' + r);
    if(strip) strip.querySelectorAll('.slv2-sym.winning, .slv2-sym.exploding')
      .forEach(function(el){ el.classList.remove('winning','exploding'); });
  }
  var lw = document.getElementById('slv2-last-win');
  if(lw){ lw.className = 'slv2-stat-val'; lw.textContent = '...'; }
  var targets = [];
  if(SL2.srvMode && SL2.srv){
    var _ss = SL2.srv.round.spins[SL2.srv.cursor++] ||
              {cols:[['spade','spade','spade'],['spade','spade','spade'],['spade','spade','spade'],['spade','spade','spade'],['spade','spade','spade']], tumbles:[]};
    SL2.srvCols = _ss.cols;
    SL2.srvTumbles = _ss.tumbles || [];
    SL2.srvTumbleCursor = 0;
    for(var i = 0; i < 5; i++){ targets.push(_ss.cols[i][1]); }
  } else {
    for(var i = 0; i < 5; i++){
      targets.push(SL2_REEL[Math.floor(Math.random() * SL2_REEL.length)]);
    }
  }
  var baseDur = SL2.turbo ? SL2_SPIN_BASE * SL2_TURBO_MULT : SL2_SPIN_BASE;
  var stagger = SL2.turbo ? SL2_SPIN_STAGGER * SL2_TURBO_MULT : SL2_SPIN_STAGGER;
  var lastReelIdx = 4;
  slv2ClearAnticipation();
  SL2._wheelAnticipationAudioPlayed = false;
  SL2._wheelCountLastDetected = 0;
  SL2._wheelAnticipationLayersPlayed = 0;
  if(SL2._wheelHeartbeatId){
    clearInterval(SL2._wheelHeartbeatId);
    SL2._wheelHeartbeatId = null;
  }
  if(SL2._crawlTimers){
    for(var ci in SL2._crawlTimers){
      if(SL2._crawlTimers[ci]){
        SL2._crawlTimers[ci].forEach(function(t){ clearTimeout(t); });
        SL2._crawlTimers[ci] = [];
      }
    }
  }
  SL2.grid = [[], [], [], [], []];
  for(var rr = 0; rr < 5; rr++){
    (function(reelIdx){
      var dur = baseDur + reelIdx * stagger;
      if(reelIdx === 4) dur += SL2.turbo ? 120 : 320;
      slv2ScheduleReelTicks(dur);
      slv2SpinReel(reelIdx, targets[reelIdx], dur, function(){
        slv2Sound('reel-stop');
        slv2UpdateGridFromStrip(reelIdx);
        if(reelIdx <= 2){
          var wheelsFound = slv2CheckWheelAnticipation(reelIdx);
          if(wheelsFound > 0){
            var prevCount = SL2._wheelCountLastDetected || 0;
            var newWheels = wheelsFound - prevCount;
            SL2._wheelCountLastDetected = wheelsFound;
            if(newWheels > 0){
              var TIER_MS = [1000, 1700, 2500, 3000];
              for(var nw = 0; nw < newWheels; nw++){
                var tier = prevCount + nw;
                var addMs = TIER_MS[tier] || 3000;
                for(var r2 = reelIdx + 1; r2 <= 4; r2++){
                  var cascadeSteps = r2 - reelIdx;
                  slv2SlowDownReel(r2, addMs, cascadeSteps);
                }
              }
            }
          }
        }
        if(reelIdx === 3){
          if(slv2CheckAnticipation()){
            slv2PlayTone(330, 0.2, 'sine', 0.1);
            setTimeout(function(){ slv2PlayTone(330, 0.2, 'sine', 0.1); }, 250);
            setTimeout(function(){ slv2PlayTone(440, 0.3, 'sine', 0.12); }, 500);
          }
        }
        if(reelIdx === lastReelIdx){
          slv2ClearAnticipation();
          var cab = document.querySelector('.slv2-cabinet');
          if(cab){
            cab.classList.remove('hard-stop');
            void cab.offsetWidth;
            cab.classList.add('hard-stop');
            setTimeout(function(){ cab.classList.remove('hard-stop'); }, 240);
          }
          if(SL2.fsActive) slv2ApplyStickyWilds();
          setTimeout(slv2ProcessSpinResult, 200);
        }
      });
    })(rr);
  }
}
function slv2ScheduleReelTicks(durationMs){
  if(!SL2.soundsEnabled) return;
  var n = 3 + Math.floor(Math.random() * 3);
  var start = durationMs * 0.20;
  var end   = durationMs * 0.80;
  for(var i = 0; i < n; i++){
    (function(i){
      var t = start + (end - start) * (i / Math.max(1, n - 1)) + (Math.random() * 60 - 30);
      setTimeout(function(){
        try { slv2PlayTone(95 + Math.random() * 40, 0.025, 'square', 0.045); } catch(e){}
      }, Math.max(0, t));
    })(i);
  }
}
function slv2SpinReel(reelIdx, targetSymbol, durationMs, cb){
  if(SL2.reelTimers[reelIdx])     { clearTimeout(SL2.reelTimers[reelIdx]);     SL2.reelTimers[reelIdx] = null; }
  if(SL2.reelWatchdogs[reelIdx])  { clearTimeout(SL2.reelWatchdogs[reelIdx]);  SL2.reelWatchdogs[reelIdx] = null; }
  SL2.reelSpinning[reelIdx] = true;
  var strip = document.getElementById('slv2-strip-' + reelIdx);
  if(!strip){
    SL2.reelSpinning[reelIdx] = false;
    if(cb) cb();
    return;
  }
  var symbols = SL2.stripSyms[reelIdx];
  var currentPos = SL2.positions[reelIdx] || 0;
  var isLastReel = (reelIdx === 4);
  var baseDist  = isLastReel ? 42 : 30;
  var jitter    = isLastReel ? 22 : 15;
  var minDistance = baseDist + Math.floor(Math.random() * jitter);
  var targetIdx = null;
  for(var i = currentPos + minDistance; i < SL2_STRIP_LEN - 1; i++){
    if(symbols[i] === targetSymbol){ targetIdx = i; break; }
  }
  if(targetIdx === null){
    slv2BuildStrip(reelIdx);
    strip = document.getElementById('slv2-strip-' + reelIdx);
    symbols = SL2.stripSyms[reelIdx];
    targetIdx = isLastReel ? 50 : 40;
    symbols[targetIdx] = targetSymbol;
    var cell = strip.children[targetIdx];
    if(cell){
      cell.className = 'slv2-sym sym-' + targetSymbol;
      if(targetSymbol === 'btc'){
        cell.innerHTML = slv2GbLogoHTML();
      } else if(targetSymbol === 'gblogo'){
        cell.innerHTML = slv2BtcCoinHTML();
      } else if(targetSymbol === 'ton'){
        cell.innerHTML = slv2TonCoinHTML();
      } else if(targetSymbol === 'wheel'){
        cell.innerHTML = slv2WheelSVG();
      } else {
        cell.textContent = SL2_CHAR[targetSymbol];
      }
    }
    var resetStartIdx = 4 + Math.floor(Math.random() * 6);
    var resetY = -((resetStartIdx - 1) * SL2_SYM_H);
    strip.style.transition = 'none';
    strip.style.animation  = '';
    strip.style.filter     = '';
    strip.style.transform  = 'translateY(' + resetY + 'px)';
    void strip.offsetWidth;
  }
  SL2.positions[reelIdx] = targetIdx;
  if(SL2.srvMode && SL2.srvCols && SL2.srvCols[reelIdx]){
    var _col = SL2.srvCols[reelIdx];
    slv2StampCell(strip, symbols, targetIdx - 1, _col[0]);
    slv2StampCell(strip, symbols, targetIdx,     _col[1]);
    slv2StampCell(strip, symbols, targetIdx + 1, _col[2]);
  }
  var finalOffset = -((targetIdx - 1) * SL2_SYM_H);
  SL2.reelFinalOffsets = SL2.reelFinalOffsets || [];
  SL2.reelFinalOffsets[reelIdx] = finalOffset;
  strip.dataset.slowdownMs = '0';
  strip.style.setProperty('--spin-dur', (durationMs / 1000) + 's');
  strip.classList.remove('stopped');
  void strip.offsetWidth;
  strip.classList.add('spinning');
  strip.style.transition = 'transform ' + (durationMs / 1000) + 's cubic-bezier(0.12, 0.7, 0.28, 1)';
  strip.style.transform = 'translateY(' + finalOffset + 'px)';
  strip.style.setProperty('--final-y', finalOffset + 'px');
  var finalized = false;
  var finalize = function(reason){
    if(finalized) return;
    finalized = true;
    if(SL2.reelTimers[reelIdx])    { clearTimeout(SL2.reelTimers[reelIdx]);    SL2.reelTimers[reelIdx] = null; }
    if(SL2.reelWatchdogs[reelIdx]) { clearTimeout(SL2.reelWatchdogs[reelIdx]); SL2.reelWatchdogs[reelIdx] = null; }
    try { strip.removeEventListener('transitionend', onTrans); } catch(e){}
    if(reason === 'watchdog'){
      try {
        strip.style.transition = 'none';
        strip.style.transform = 'translateY(' + finalOffset + 'px)';
        void strip.offsetWidth;
      } catch(e){}
    }
    strip.classList.remove('spinning');
    strip.classList.remove('wheel-anticipating');
    strip.style.filter = 'blur(0)';
    strip.style.willChange = 'auto';
    var parentCol = strip.parentElement;
    if(parentCol){
      parentCol.classList.remove('wheel-anticipating-col', 'anticipating-col');
    }
    strip.style.transition = 'none';
    strip.classList.add('stopped');
    setTimeout(function(){ strip.classList.remove('stopped'); }, 330);
    SL2.reelSpinning[reelIdx] = false;
    try { slv2PlayTone(140 + Math.random() * 30, 0.03, 'square', 0.06); } catch(e){}
    hapGioco('leggero');
    if(cb){
      try { cb(); } catch(err){ console && console.warn && console.warn('slv2SpinReel cb error', err); }
    }
  };
  var onTrans = function(e){
    if(e && e.propertyName && e.propertyName !== 'transform') return;
    finalize('transition');
  };
  strip.addEventListener('transitionend', onTrans);
  strip._slv2OnTrans = onTrans;
  SL2.reelFinalize = SL2.reelFinalize || [];
  SL2.reelFinalize[reelIdx] = finalize;
  SL2.reelTimers[reelIdx] = setTimeout(function(){ finalize('timer'); }, durationMs + 40);
  SL2.reelWatchdogs[reelIdx] = setTimeout(function(){
    if(!finalized){
      console && console.warn && console.warn('[slv2] reel ' + reelIdx + ' watchdog tripped — recovering');
      finalize('watchdog');
    }
  }, 8000);
}
function slv2ProcessSpinResult(){
  var lineWins = slv2DetectLineWins();
  var scatterWin = slv2DetectScatter();
  var wheelWin   = slv2DetectWheelScatter();
  var totalWinMultiplier = 0;
  var winsToRender = [];
  lineWins.forEach(function(w){
    totalWinMultiplier += w.multi;
    winsToRender.push(w);
  });
  var fsTriggered = 0;
  if(scatterWin.count >= 3){
    totalWinMultiplier += SL2_SCATTER_PAY[scatterWin.count] || 0;
    fsTriggered = SL2_SCATTER_FS[scatterWin.count] || 0;
    winsToRender.push({ type:'scatter', cells: scatterWin.cells, count: scatterWin.count });
  }
  var wheelTriggered = false;
  if(wheelWin.count >= 3){
    wheelTriggered = true;
    var wheelScatPay = (wheelWin.count === 5 ? 25 : wheelWin.count === 4 ? 8 : 2);
    totalWinMultiplier += wheelScatPay;
    winsToRender.push({ type:'wheel-scatter', cells: wheelWin.cells, count: wheelWin.count });
  }
  var mult = (SL2.fsActive ? SL2.fsMultiplier : 1);
  var perLineBet = SL2.bet / SL2_LINES.length;
  var lineMultiSum = 0;
  lineWins.forEach(function(w){ lineMultiSum += w.multi; });
  var scatterMulti = (scatterWin.count >= 3) ? (SL2_SCATTER_PAY[scatterWin.count] || 0) : 0;
  var wheelScatMulti = wheelTriggered ? (wheelWin.count === 5 ? 25 : wheelWin.count === 4 ? 8 : 2) : 0;
  var winAmount = (perLineBet * lineMultiSum * mult) + (SL2.bet * (scatterMulti + wheelScatMulti) * mult);
  if(SL2.fsActive){
    SL2.fsPlayed++;
    SL2.fsRemaining--;
    SL2.fsTotal += winAmount;
    slv2UpdateFsUI();
  }
  if(winAmount > 0){
    SL2.cascadeWinTotal = winAmount;
    SL2.totalWonThisSession += winAmount;
    winBet(winAmount, 'slots');
    var lw = document.getElementById('slv2-last-win');
    if(lw){
      lw.className = 'slv2-stat-val win';
      lw.textContent = '+\u20ac' + winAmount.toFixed(2);
    }
    slv2RenderWins(winsToRender);
    var ratio = winAmount / SL2.bet;
    if(scatterWin.count >= 3 || wheelTriggered) slv2Sound('scatter');
    if(ratio >= 100) slv2Sound('jackpot');
    else if(ratio >= 15) slv2Sound('mega-win');
    else if(ratio >= 5)  slv2Sound('big-win');
    else if(ratio >= 1)  slv2Sound('medium-win');
    else                 slv2Sound('small-win');
    if(ratio >= 5){
      setTimeout(function(){
        slv2ShowCelebration(ratio, winAmount, scatterWin.count >= 3);
      }, 250);
    }
    setTimeout(function(){
      slv2CascadeStep(winsToRender);
    }, ratio >= 5 ? 2200 : 1500);
  } else {
    var lwElse = document.getElementById('slv2-last-win');
    if(lwElse){
      if(SL2.fsActive){
        lwElse.className = 'slv2-stat-val';
        lwElse.textContent = '\u20ac0.00';
      } else {
        lwElse.className = 'slv2-stat-val lose';
        lwElse.textContent = '-\u20ac' + SL2.bet.toFixed(2);
      }
    }
    if(!SL2.fsActive){
      loseBet(SL2.bet, 'slots');
    }
    slv2FinishSpin(fsTriggered);
  }
  if(fsTriggered > 0){
    SL2.pendingFsTrigger = (SL2.pendingFsTrigger || 0) + fsTriggered;
  }
  if(wheelTriggered){
    SL2.pendingWheelTrigger = true;
  }
}
function slv2FinishSpin(fsTriggered){
  SL2.spinning = false;
  var slvRoot = document.querySelector('.slv2');
  if(slvRoot) slvRoot.classList.remove('is-spinning');
  if(SL2.fsActive){
    for(var r = 0; r < 5; r++){
      for(var row = 0; row < 3; row++){
        if(SL2.grid[r] && SL2.grid[r][row] === 'btc'){
          var already = SL2.stickyWilds.some(function(sw){ return sw.reel === r && sw.row === row; });
          if(!already){
            SL2.stickyWilds.push({reel: r, row: row});
            var strip = document.getElementById('slv2-strip-' + r);
            if(strip){
              var idx = SL2.positions[r] + (row - 1);
              var cell = strip.children[idx];
              if(cell) cell.classList.add('sticky-wild');
            }
          }
        }
      }
    }
  }
  if(SL2.fsActive && SL2.pendingFsTrigger > 0){
    var extraFs = SL2.pendingFsTrigger;
    SL2.pendingFsTrigger = 0;
    SL2.fsRemaining = (SL2.fsRemaining || 0) + extraFs;
    SL2.fsCount     = (SL2.fsCount     || 0) + extraFs;
    slv2UpdateFsUI();
    slv2ShowFsRetriggerToast(extraFs);
    slv2Sound('free-spins');
    slv2SendSlotEvent('fs_round', { count: extraFs, retrigger: true });
  }
  if(SL2.fsActive && SL2.pendingWheelTrigger){
    SL2.pendingWheelTrigger = false;
    if(typeof slv2ResetBonusCounter === 'function') slv2ResetBonusCounter();
    setTimeout(slv2BonusWheelTrigger, 500);
    return;
  }
  if(SL2.pendingFsTrigger && !SL2.fsActive){
    var n = SL2.pendingFsTrigger;
    SL2.pendingFsTrigger = 0;
    if(typeof slv2ResetBonusCounter === 'function') slv2ResetBonusCounter();
    slv2TriggerFreeSpinsIntro(n);
    return;
  }
  if(SL2.pendingWheelTrigger && !SL2.fsActive){
    SL2.pendingWheelTrigger = false;
    if(typeof slv2ResetBonusCounter === 'function') slv2ResetBonusCounter();
    setTimeout(slv2BonusWheelTrigger, 500);
    return;
  }
  if(SL2.fsActive && SL2.fsRemaining > 0){
    slv2QueueSpin(800);
    return;
  }
  if(SL2.fsActive && SL2.fsRemaining <= 0){
    slv2ClearStickyWilds();
    slv2EndFreeSpins();
    return;
  }
  var spinHadWin = SL2.cascadeWinTotal > 0;
  if(slv2MaybeTriggerBonus(spinHadWin)){
    return;
  }
  if(SL2.autoActive){
    SL2.autoRemaining--;
    var rem = document.getElementById('slv2-auto-rem');
    if(rem) rem.textContent = SL2.autoRemaining;
    if(SL2.autoRemaining <= 0){
      slv2StopAuto();
    } else {
      if(SL2.cascadeWinTotal >= SL2.bet * 50){
        slv2StopAuto();
        return;
      }
      slv2QueueSpin(600, { requireAuto: true });
    }
  }
  slv2EnableSpinIfIdle();
}
function slv2QuickStopAllReels(){
  if(!SL2.spinning) return;
  try { slv2PlayTone(880, 0.05, 'square', 0.10); } catch(e){}
  try { slv2PlayTone(440, 0.04, 'square', 0.08); } catch(e){}
  for(var r = 0; r < 5; r++){
    if(!SL2.reelSpinning || !SL2.reelSpinning[r]) continue;
    var strip = document.getElementById('slv2-strip-' + r);
    if(!strip) continue;
    var symbols = SL2.stripSyms[r];
    if(!symbols || symbols.length < 3) continue;
    var transformStr = window.getComputedStyle(strip).transform;
    var currentY = 0;
    if(transformStr && transformStr !== 'none'){
      var match = transformStr.match(/matrix.*\((.+)\)/);
      if(match){
        var nums = match[1].split(',').map(function(s){ return parseFloat(s.trim()); });
        currentY = nums.length === 6 ? nums[5] : nums.length === 16 ? nums[13] : 0;
      }
    }
    var nearestIdx = Math.round(-currentY / SL2_SYM_H) + 1;
    nearestIdx = Math.max(1, Math.min(symbols.length - 2, nearestIdx));
    var snapY = -((nearestIdx - 1) * SL2_SYM_H);
    if(SL2._crawlTimers && SL2._crawlTimers[r]){
      SL2._crawlTimers[r].forEach(function(t){ clearTimeout(t); });
      SL2._crawlTimers[r] = [];
    }
    if(SL2.reelTimers && SL2.reelTimers[r]){
      clearTimeout(SL2.reelTimers[r]);
      SL2.reelTimers[r] = null;
    }
    if(SL2.reelWatchdogs && SL2.reelWatchdogs[r]){
      clearTimeout(SL2.reelWatchdogs[r]);
      SL2.reelWatchdogs[r] = null;
    }
    if(strip._slv2OnTrans){
      strip.removeEventListener('transitionend', strip._slv2OnTrans);
    }
    strip.style.transition = 'transform 180ms cubic-bezier(0.22, 0.85, 0.40, 1), filter 120ms ease-out';
    strip.style.transform = 'translateY(' + snapY + 'px)';
    strip.style.filter = 'blur(0px)';
    SL2.positions[r] = nearestIdx;
    if(SL2.reelFinalOffsets) SL2.reelFinalOffsets[r] = snapY;
    (function(reelIdx, stripEl){
      var finalizeT = setTimeout(function(){
        stripEl.classList.remove('spinning');
        stripEl.classList.remove('wheel-anticipating');
        stripEl.style.filter = 'blur(0)';
        stripEl.style.willChange = 'auto';
        var col = stripEl.parentElement;
        if(col) col.classList.remove('wheel-anticipating-col', 'anticipating-col');
        SL2.reelSpinning[reelIdx] = false;
        try { slv2PlayTone(180 + Math.random() * 30, 0.03, 'square', 0.08); } catch(e){}
        try { slv2PlayTone(95, 0.10, 'sine', 0.16); } catch(e){}
        if(SL2.reelFinalize && SL2.reelFinalize[reelIdx]){
          try { SL2.reelFinalize[reelIdx]('quick-stop'); } catch(e){}
        }
      }, 200);
      if(!SL2._crawlTimers) SL2._crawlTimers = {};
      SL2._crawlTimers[reelIdx] = SL2._crawlTimers[reelIdx] || [];
      SL2._crawlTimers[reelIdx].push(finalizeT);
    })(r, strip);
  }
}
function slv2EnableSpinIfIdle(){
  if(SL2.spinning) return;
  if(SL2.pendingFsTrigger) return;
  if(SL2.pendingWheelTrigger) return;
  if(SL2.fsActive) return;
  if(SL2.bonusWheelOpen) return;
  if(SL2.vaultOpen) return;
  if(SL2.fakeRevealActive) return;
  slv2SrvReconcile();
  var spinBtn = document.getElementById('slv2-spin-btn');
  if(spinBtn) spinBtn.disabled = false;
  slv2SetSpinButtonMode('spin');
  var betRow = document.querySelector('.slv2-bet-row');
  if(betRow) betRow.classList.remove('locked');
}
function slv2DisableSpin(){
  var spinBtn = document.getElementById('slv2-spin-btn');
  if(spinBtn) spinBtn.disabled = true;
  var betRow = document.querySelector('.slv2-bet-row');
  if(betRow) betRow.classList.add('locked');
}
function slv2DetectLineWins(){
  var wins = [];
  for(var lineIdx = 0; lineIdx < SL2_LINES.length; lineIdx++){
    var line = SL2_LINES[lineIdx];
    var lineSyms = [];
    for(var r = 0; r < 5; r++){
      lineSyms.push(SL2.grid[r][line[r]]);
    }
    var firstSym = lineSyms[0];
    if(firstSym === 'bot' || firstSym === 'wheel') continue;
    var matchSym = firstSym;
    if(firstSym === 'btc'){
      for(var k = 1; k < 5; k++){
        if(lineSyms[k] !== 'btc' && lineSyms[k] !== 'bot' && lineSyms[k] !== 'wheel'){
          matchSym = lineSyms[k];
          break;
        }
      }
    }
    var count = 0;
    var cells = [];
    for(var c = 0; c < 5; c++){
      var s = lineSyms[c];
      if(s === matchSym || (s === 'btc' && matchSym !== 'bot' && matchSym !== 'wheel')){
        count++;
        cells.push({reel: c, row: line[c]});
      } else {
        break;
      }
    }
    if(count >= 3){
      var pay = (count === 5 ? SL2_PAY_5 : (count === 4 ? SL2_PAY_4 : SL2_PAY_3))[matchSym] || 0;
      if(pay > 0){
        wins.push({
          type: 'line',
          line: lineIdx,
          symbol: matchSym,
          count: count,
          multi: pay,
          cells: cells
        });
      }
    }
  }
  return wins;
}
function slv2DetectScatter(){
  var cells = [];
  for(var r = 0; r < 5; r++){
    for(var row = 0; row < 3; row++){
      if(SL2.grid[r][row] === 'bot'){
        cells.push({reel: r, row: row});
      }
    }
  }
  return { count: cells.length, cells: cells };
}
function slv2DetectWheelScatter(){
  var cells = [];
  for(var r = 0; r < 5; r++){
    for(var row = 0; row < 3; row++){
      if(SL2.grid[r][row] === 'wheel'){
        cells.push({reel: r, row: row});
      }
    }
  }
  return { count: cells.length, cells: cells };
}
function slv2RenderWins(wins){
  var svg = document.getElementById('slv2-payline-svg');
  var ov = document.getElementById('slv2-win-overlay');
  if(!svg || !ov) return;
  svg.innerHTML = '';
  ov.innerHTML = '';
  var palette = ['#39ff14','#ffd700','#a855f7','#22d3ee','#ffaa00','#5fff3a','#4f7df7','#ff8800','#c084fc','#86efac'];
  wins.forEach(function(w, i){
    if(w.type === 'line'){
      var line = SL2_LINES[w.line];
      var pts = [];
      for(var c = 0; c < w.count; c++){
        var x = c * 100 + 50;
        var y = line[c] * 80 + 40;
        pts.push(x + ',' + y);
      }
      var ptsStr = pts.join(' ');
      var color  = palette[i % palette.length];
      var delay  = (i * 0.1) + 's';
      var SVG_NS = 'http://www.w3.org/2000/svg';
      var poly = document.createElementNS(SVG_NS, 'polyline');
      poly.setAttribute('points', ptsStr);
      poly.setAttribute('class', 'slv2-payline-line');
      poly.style.stroke = color;
      poly.style.color  = color;
      poly.style.animationDelay = delay;
      svg.appendChild(poly);
      var flow = document.createElementNS(SVG_NS, 'polyline');
      flow.setAttribute('points', ptsStr);
      flow.setAttribute('class', 'slv2-payline-flow');
      flow.style.color = color;
      flow.style.animationDelay = delay + ', ' + delay;
      svg.appendChild(flow);
      var spark = document.createElementNS(SVG_NS, 'circle');
      spark.setAttribute('r', '4');
      spark.setAttribute('cx', '0');
      spark.setAttribute('cy', '0');
      spark.setAttribute('class', 'slv2-payline-spark');
      spark.style.color = color;
      spark.style.animationDelay = delay;
      var anim = document.createElementNS(SVG_NS, 'animateMotion');
      anim.setAttribute('dur', '1.4s');
      anim.setAttribute('repeatCount', 'indefinite');
      anim.setAttribute('begin', delay);
      anim.setAttribute('path', 'M ' + pts.join(' L '));
      anim.setAttribute('rotate', 'auto');
      spark.appendChild(anim);
      svg.appendChild(spark);
    }
    w.cells.forEach(function(c){
      var strip = document.getElementById('slv2-strip-' + c.reel);
      if(strip){
        var idx = SL2.positions[c.reel] + (c.row - 1);
        var symEl = strip.children[idx];
        if(symEl) symEl.classList.add('winning');
      }
      var cell = document.createElement('div');
      cell.className = 'slv2-win-cell';
      var leftPct = (c.reel / 5) * 100;
      var widthPct = 100 / 5;
      var topPct = (c.row / 3) * 100;
      var heightPct = 100 / 3;
      cell.style.left = leftPct + '%';
      cell.style.top = topPct + '%';
      cell.style.width = widthPct + '%';
      cell.style.height = heightPct + '%';
      cell.style.animationDelay = (i * 0.08) + 's';
      ov.appendChild(cell);
    });
  });
}
function slv2CascadeStep(wins){
  if(!wins || wins.length === 0){ slv2FinishSpin(SL2.pendingFsTrigger || 0); return; }
  if(SL2.srvMode){
    SL2.srvCascCur = (SL2.srvTumbles && SL2.srvTumbleCursor < SL2.srvTumbles.length)
                     ? SL2.srvTumbles[SL2.srvTumbleCursor++] : null;
  }
  SL2.cascadeLevel++;
  var winningCells = {};
  wins.forEach(function(w){
    w.cells.forEach(function(c){
      var key = c.reel + ',' + c.row;
      winningCells[key] = true;
    });
  });
  for(var r = 0; r < 5; r++){
    var strip = document.getElementById('slv2-strip-' + r);
    if(!strip) continue;
    for(var row = 0; row < 3; row++){
      if(winningCells[r + ',' + row]){
        var idx = SL2.positions[r] + (row - 1);
        var sym = strip.children[idx];
        if(sym){
          sym.classList.remove('winning');
          sym.classList.add('exploding');
        }
      }
    }
  }
  setTimeout(function(){
    for(var r = 0; r < 5; r++){
      var strip = document.getElementById('slv2-strip-' + r);
      if(!strip) continue;
      for(var row = 0; row < 3; row++){
        if(winningCells[r + ',' + row]){
          var idx = SL2.positions[r] + (row - 1);
          var sym = strip.children[idx];
          if(sym){
            var newSym;
            if(SL2.srvMode){
              var _rf = (SL2.srvCascCur && SL2.srvCascCur.refill) ? SL2.srvCascCur.refill[r + ',' + row] : null;
              newSym = _rf || SL2_REEL[Math.floor(Math.random() * SL2_REEL.length)];
            } else {
              newSym = SL2_REEL[Math.floor(Math.random() * SL2_REEL.length)];
            }
            SL2.stripSyms[r][idx] = newSym;
            sym.className = 'slv2-sym sym-' + newSym + ' dropping-in';
            if(newSym === 'btc'){
              sym.innerHTML = slv2GbLogoHTML();
            } else if(newSym === 'gblogo'){
              sym.innerHTML = slv2BtcCoinHTML();
            } else if(newSym === 'ton'){
              sym.innerHTML = slv2TonCoinHTML();
            } else if(newSym === 'wheel'){
              sym.innerHTML = slv2WheelSVG();
            } else {
              sym.textContent = SL2_CHAR[newSym];
            }
            (function(s){
              setTimeout(function(){ s.classList.remove('dropping-in'); }, 400);
            })(sym);
          }
        }
      }
      slv2UpdateGridFromStrip(r);
    }
    setTimeout(function(){
      var newLineWins = slv2DetectLineWins();
      var newWins = newLineWins;
      if(newWins.length > 0){
        var addMulti = newWins.reduce(function(a,w){ return a + w.multi; }, 0);
        var mult = (SL2.fsActive ? SL2.fsMultiplier : 1);
        var perLineBetC = SL2.bet / SL2_LINES.length;
        var addAmount = perLineBetC * addMulti * mult;
        SL2.cascadeWinTotal += addAmount;
        SL2.totalWonThisSession += addAmount;
        winBet(addAmount, 'slots');
        var lw = document.getElementById('slv2-last-win');
        if(lw){
          lw.className = 'slv2-stat-val win';
          lw.textContent = '+\u20ac' + SL2.cascadeWinTotal.toFixed(2) + ' x' + (SL2.cascadeLevel + 1);
        }
        slv2RenderWins(newWins);
        slv2Sound(SL2.cascadeLevel >= 2 ? 'big-win' : 'medium-win');
        if(SL2.cascadeLevel >= 2){
          var cab = document.querySelector('.slv2-cabinet');
          if(cab){
            cab.classList.add('shaking');
            setTimeout(function(){ cab.classList.remove('shaking'); }, 400);
          }
        }
        setTimeout(function(){ slv2CascadeStep(newWins); }, 1400);
      } else {
        var svg = document.getElementById('slv2-payline-svg');
        if(svg) svg.innerHTML = '';
        var ov = document.getElementById('slv2-win-overlay');
        if(ov) ov.innerHTML = '';
        slv2FinishSpin(SL2.pendingFsTrigger || 0);
      }
    }, 450);
  }, 500);
}
function slv2TriggerFreeSpinsIntro(count){
  slv2DisableSpin();
  SL2.fsIntroActive = true;
  SL2.fsCount = count;
  SL2.fsRemaining = count;
  SL2.fsTotal = 0;
  SL2.fsPlayed = 0;
  slv2SendSlotEvent('fs_round', { count: count });
  var intro = document.getElementById('slv2-fs-intro');
  var countEl = document.getElementById('slv2-fs-intro-count');
  if(countEl) countEl.textContent = count;
  if(intro) intro.classList.add('visible');
  var fsIntroVid = document.getElementById('slv2-fs-intro-video');
  var fsHasVideo = !!(fsIntroVid && fsIntroVid.getAttribute('src') &&
                      parseInt((fsIntroVid.dataset && fsIntroVid.dataset.failCount) || '0', 10) < 3);
  if(fsHasVideo) slv2RestartVideo('slv2-fs-intro-video');
  slv2Sound('free-spins');
  if(SL2.autoActive){
    SL2.autoPausedForFs = true;
  }
  var startBtn = document.getElementById('slv2-fs-intro-btn');
  if(startBtn){
    startBtn._origText = startBtn._origText || startBtn.textContent || 'START';
    startBtn.disabled = true;
    startBtn.style.opacity = '.5';
    startBtn.style.cursor = 'not-allowed';
    startBtn.textContent = 'GET READY...';
  }
  var fsCountdownSec = fsHasVideo ? 3 : 1;
  slv2RunCountdown('slv2-fs-intro', fsCountdownSec, function(){
    if(startBtn){
      startBtn.disabled = false;
      startBtn.style.opacity = '';
      startBtn.style.cursor = '';
      startBtn.textContent = startBtn._origText || 'START';
    }
  });
}
function slv2StartFreeSpins(){
  var intro = document.getElementById('slv2-fs-intro');
  slv2CancelCountdown('slv2-fs-intro');
  var fsVid = document.getElementById('slv2-fs-intro-video');
  if(fsVid){ try { fsVid.pause(); } catch(e){} }
  if(intro) intro.classList.remove('visible');
  SL2.fsActive = true;
  SL2.fsIntroActive = false;
  SL2.stickyWilds = [];
  var cab = document.querySelector('.slv2-cabinet');
  if(cab) cab.classList.add('fs-active');
  var fsCard = document.getElementById('slv2-fs-card');
  if(fsCard) fsCard.classList.add('active');
  slv2UpdateFsUI();
  slv2QueueSpin(600);
}
function slv2EndFreeSpins(){
  SL2.fsActive = false;
  var cab = document.querySelector('.slv2-cabinet');
  if(cab) cab.classList.remove('fs-active');
  var fsCard = document.getElementById('slv2-fs-card');
  if(fsCard) fsCard.classList.remove('active');
  var summary = document.getElementById('slv2-fs-summary');
  var played = document.getElementById('slv2-fs-played');
  var total = document.getElementById('slv2-fs-total');
  if(played) played.textContent = SL2.fsPlayed;
  if(total) total.textContent = '\u20ac' + SL2.fsTotal.toFixed(2);
  if(summary) summary.classList.add('visible');
  slv2Sound(SL2.fsTotal >= SL2.bet * 30 ? 'big-win' : 'medium-win');
}
function slv2CloseFsSummary(){
  var summary = document.getElementById('slv2-fs-summary');
  if(summary) summary.classList.remove('visible');
  SL2.fsRemaining = 0;
  SL2.fsTotal = 0;
  SL2.fsCount = 0;
  slv2UpdateFsUI();
  if(SL2.autoActive && SL2.autoPausedForFs){
    SL2.autoPausedForFs = false;
    SL2.autoRemaining--;
    if(SL2.autoRemaining > 0){
      var rem = document.getElementById('slv2-auto-rem');
      if(rem) rem.textContent = SL2.autoRemaining;
      slv2QueueSpin(600, { requireAuto: true });
    } else {
      slv2StopAuto();
    }
    return;
  }
  slv2EnableSpinIfIdle();
}
function slv2UpdateFsUI(){
  var fsCount = document.getElementById('slv2-fs-count');
  if(fsCount) fsCount.textContent = SL2.fsRemaining;
}
function slv2AutoMenu(){
  if(SL2.spinning) return;
  slv2Sound('click');
  var modal = document.getElementById('slv2-auto-modal');
  if(modal) modal.classList.add('visible');
}
function slv2CloseAutoMenu(){
  var modal = document.getElementById('slv2-auto-modal');
  if(modal) modal.classList.remove('visible');
}
function slv2StartAuto(n){
  slv2CloseAutoMenu();
  SL2.autoActive = true;
  SL2.autoRemaining = n;
  var banner = document.getElementById('slv2-auto-banner');
  var rem = document.getElementById('slv2-auto-rem');
  if(banner) banner.classList.add('visible');
  if(rem) rem.textContent = n;
  slv2QueueSpin(300, { requireAuto: true });
}
function slv2StopAuto(){
  SL2.autoActive = false;
  SL2.autoRemaining = 0;
  SL2.autoPausedForFs = false;
  var banner = document.getElementById('slv2-auto-banner');
  if(banner) banner.classList.remove('visible');
}
function slv2ShowCelebration(ratio, winAmount, isScatter){
  var celeb = document.getElementById('slv2-celeb');
  var txtEl = document.getElementById('slv2-celeb-text');
  var amtEl = document.getElementById('slv2-celeb-amount');
  var subEl = document.getElementById('slv2-celeb-sub');
  if(!celeb) return;
  celeb.classList.remove('tier-small','tier-medium','tier-big','tier-mega','tier-jackpot');
  var tier, label, sub, duration;
  if(ratio >= 50) slv2SendSlotEvent('big_win', { multi: Math.floor(ratio), source: 'reels' });
  if(ratio >= 100){
    tier = 'jackpot'; label = '\ud83c\udfc6 JACKPOT! \ud83c\udfc6'; sub = 'INCREDIBLE WIN!'; duration = 4000;
  } else if(ratio >= 30){
    tier = 'mega'; label = 'MEGA WIN!'; sub = 'UNBELIEVABLE!'; duration = 3000;
  } else if(ratio >= 15){
    tier = 'big'; label = 'BIG WIN!'; sub = 'AWESOME!'; duration = 2500;
  } else if(ratio >= 8){
    tier = 'medium'; label = 'SUPER WIN!'; sub = 'NICE ONE!'; duration = 2000;
  } else {
    tier = 'small'; label = 'WIN!'; sub = ''; duration = 1500;
  }
  if(isScatter) sub = '\ud83e\udd16 SCATTER BONUS! ' + sub;
  celeb.classList.add('tier-' + tier);
  if(txtEl) txtEl.textContent = label;
  if(amtEl) amtEl.textContent = '+\u20ac' + winAmount.toFixed(2);
  if(subEl) subEl.textContent = sub;
  celeb.classList.add('visible');
  if(ratio >= 5){
    var coinCount;
    if      (ratio >= 100) coinCount = 70;
    else if (ratio >= 30)  coinCount = 50;
    else if (ratio >= 15)  coinCount = 32;
    else if (ratio >= 8)   coinCount = 20;
    else                   coinCount = 14;
    for(var i = 0; i < coinCount; i++){
      (function(idx){
        setTimeout(function(){
          if(!celeb.classList.contains('visible')) return;
          var coin = document.createElement('div');
          var roll = Math.random();
          var sym, klass;
          if(roll < 0.70){ sym = '\u20bf'; klass = ''; }
          else if(roll < 0.85){ sym = '\ud83d\udc8e'; klass = 'tier-purple'; }
          else { sym = '\u2605'; klass = 'tier-green'; }
          coin.className = 'slv2-particle coin' + (klass ? ' ' + klass : '');
          coin.textContent = sym;
          coin.style.fontSize = (22 + Math.random() * 16) + 'px';
          coin.style.left = (Math.random() * 100) + '%';
          coin.style.top  = '-50px';
          coin.style.setProperty('--xShift', (Math.random() - 0.5) * 260 + 'px');
          coin.style.setProperty('--dur',    (1.9 + Math.random() * 1.2) + 's');
          celeb.appendChild(coin);
          setTimeout(function(){ coin.remove(); }, 3200);
        }, idx * (ratio >= 30 ? 35 : 55));
      })(i);
    }
    var sparkCount = ratio >= 30 ? 24 : ratio >= 15 ? 16 : 10;
    for(var s = 0; s < sparkCount; s++){
      (function(idx){
        setTimeout(function(){
          if(!celeb.classList.contains('visible')) return;
          var spark = document.createElement('div');
          spark.className = 'slv2-particle spark';
          var angle = (idx / sparkCount) * Math.PI * 2 + (Math.random() - 0.5) * 0.5;
          var dist  = 90 + Math.random() * 130;
          spark.style.left = '50%';
          spark.style.top  = '50%';
          spark.style.setProperty('--sx', Math.cos(angle) * dist + 'px');
          spark.style.setProperty('--sy', Math.sin(angle) * dist + 'px');
          spark.style.setProperty('--spark-c', (idx % 3 === 0) ? '#39ff14' : '#ffd700');
          celeb.appendChild(spark);
          setTimeout(function(){ spark.remove(); }, 1500);
        }, 80 + idx * 18);
      })(s);
    }
  }
  setTimeout(function(){
    celeb.classList.remove('visible');
    celeb.querySelectorAll('.slv2-particle').forEach(function(p){ p.remove(); });
  }, duration);
}
function slv2BonusWheelBuild(){
  var bet = SL2.bet || 1;
  var tier = slv2WheelTierForBet(bet);
  if(SL2.srvMode && SL2.srv){
    SL2.srvWheel = SL2.fsActive
      ? (SL2.srv.round.fs_wheels[SL2.srvFsWheelCursor++] || SL2.srv.round.wheel)
      : SL2.srv.round.wheel;
    if(SL2.srvWheel && SL2.srvWheel.tier) tier = SL2.srvWheel.tier;
    if(SL2.srv) SL2.srv.wheelShown = true;
  }
  SL2.bwTier = tier;
  var segments = SL2_WHEEL_TIERS[tier].segments.map(function(s){
    return {
      type: s.type, value: s.value, weight: s.weight,
      color: s.color, label: s.label
    };
  });
  if(SL2.srvMode && SL2.srvWheel && SL2.srvWheel.order){
    var _src = segments;
    segments = SL2.srvWheel.order.map(function(oi){ return _src[oi]; });
  } else {
    for(var i = segments.length - 1; i > 0; i--){
      var j = Math.floor(Math.random() * (i + 1));
      var tmp = segments[i]; segments[i] = segments[j]; segments[j] = tmp;
    }
  }
  SL2.bwSegments = segments;
  var subEl = document.getElementById('slv2-bw-subtitle');
  if(subEl){
    var tierMaxes = { LOW: '15×', MID: '24× + JP', HIGH: '120× + JP' };
    var tierColor = { LOW: '#5fc7ff', MID: '#ff8844', HIGH: '#ffd700' };
    subEl.innerHTML = '<span style="opacity:.85;">Bet </span><strong>\u20ac' + (SL2.bet || 1) +
      '</strong><span style="opacity:.85;"> \u00b7 ' + tier + ' tier \u00b7 win up to </span><strong style="color:' +
      tierColor[tier] + ';">' + tierMaxes[tier] + '</strong>';
  }
  var svg = document.getElementById('slv2-bw-svg');
  if(!svg) return;
  svg.innerHTML = '';
  var cx = 150, cy = 150, r = 130;
  var outer = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
  outer.setAttribute('cx', cx); outer.setAttribute('cy', cy); outer.setAttribute('r', r + 6);
  outer.setAttribute('fill', 'none');
  outer.setAttribute('stroke', '#ffd700');
  outer.setAttribute('stroke-width', '4');
  outer.setAttribute('filter', 'drop-shadow(0 0 8px gold)');
  svg.appendChild(outer);
  var rotor = document.createElementNS('http://www.w3.org/2000/svg', 'g');
  rotor.setAttribute('class', 'slv2-bw-rotor');
  rotor.setAttribute('id', 'slv2-bw-rotor');
  svg.appendChild(rotor);
  var segAngle = 360 / SL2.WHEEL_SEGMENTS;
  for(var k = 0; k < SL2.WHEEL_SEGMENTS; k++){
    var seg = SL2.bwSegments[k];
    var startA = (k * segAngle - 90) * Math.PI / 180;
    var endA = ((k + 1) * segAngle - 90) * Math.PI / 180;
    var x1 = cx + r * Math.cos(startA);
    var y1 = cy + r * Math.sin(startA);
    var x2 = cx + r * Math.cos(endA);
    var y2 = cy + r * Math.sin(endA);
    var d = 'M ' + cx + ' ' + cy + ' L ' + x1 + ' ' + y1 + ' A ' + r + ' ' + r + ' 0 0 1 ' + x2 + ' ' + y2 + ' Z';
    var p = document.createElementNS('http://www.w3.org/2000/svg', 'path');
    p.setAttribute('d', d);
    p.setAttribute('fill', seg.color);
    p.setAttribute('stroke', '#1a0500');
    p.setAttribute('stroke-width', '1.5');
    p.setAttribute('class', 'slv2-bw-segment');
    p.setAttribute('data-idx', k);
    rotor.appendChild(p);
    var midA = ((k + 0.5) * segAngle - 90) * Math.PI / 180;
    var tx = cx + (r * 0.62) * Math.cos(midA);
    var ty = cy + (r * 0.62) * Math.sin(midA);
    var txt = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    txt.setAttribute('x', tx);
    txt.setAttribute('y', ty);
    txt.setAttribute('text-anchor', 'middle');
    txt.setAttribute('dominant-baseline', 'middle');
    txt.setAttribute('fill', seg.type === 'chest' || seg.type === 'mystery' ? '#fff' : '#fff');
    txt.setAttribute('font-family', "'Russo One', sans-serif");
    var fontSize = 18;
    if(seg.label.length > 3) fontSize = 13;
    else if(seg.type === 'chest' || seg.type === 'mystery') fontSize = 24;
    else if(seg.type === 'cash' && seg.value >= 100) fontSize = 16;
    txt.setAttribute('font-size', fontSize);
    txt.setAttribute('font-weight', '900');
    txt.setAttribute('transform', 'rotate(' + ((k + 0.5) * segAngle) + ' ' + tx + ' ' + ty + ')');
    txt.style.textShadow = '0 2px 4px rgba(0,0,0,.8)';
    txt.style.pointerEvents = 'none';
    txt.textContent = seg.label;
    rotor.appendChild(txt);
  }
  var hub = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
  hub.setAttribute('cx', cx); hub.setAttribute('cy', cy); hub.setAttribute('r', '20');
  hub.setAttribute('fill', 'url(#plBallGrad)');
  hub.setAttribute('stroke', '#ffd700');
  hub.setAttribute('stroke-width', '2');
  svg.appendChild(hub);
}
function slv2BonusWheelTrigger(){
  if(SL2.bonusActive) return;
  SL2.bonusActive = true;
  SL2.bonusWheelOpen = true;
  slv2DisableSpin();
  slv2SendSlotEvent('wheel_trigger');
  slv2BonusWheelBuild();
  var ov = document.getElementById('slv2-bonus-wheel');
  var bwVid = document.getElementById('slv2-bw-video');
  var hasVideo = !!(bwVid && bwVid.getAttribute('src') &&
                    parseInt((bwVid.dataset && bwVid.dataset.failCount) || '0', 10) < 3);
  if(ov){
    ov.classList.add('visible');
    if(hasVideo){
      ov.classList.add('video-intro-active');
    }
  }
  if(hasVideo) slv2RestartVideo('slv2-bw-video');
  var btn = document.getElementById('slv2-bw-spin');
  var collect = document.getElementById('slv2-bw-collect');
  var result = document.getElementById('slv2-bw-result');
  if(btn){
    btn.style.display = '';
    btn.disabled = true;
    btn._originalText = btn._originalText || btn.textContent || 'SPIN THE WHEEL';
    btn.textContent = 'GET READY...';
    btn.style.opacity = '.55';
    btn.style.cursor = 'not-allowed';
  }
  if(collect) collect.style.display = 'none';
  if(result) result.textContent = '';
  slv2PlayWheelOpenFanfare();
  slv2Sound('scatter');
  var countdownSec = hasVideo ? 5 : 1;
  slv2RunCountdown('slv2-bonus-wheel', countdownSec, function(){
    if(ov){
      ov.classList.remove('video-intro-active');
      var bwVid = document.getElementById('slv2-bw-video');
      if(bwVid){ try { bwVid.pause(); } catch(e){} }
    }
    if(btn){
      btn.disabled = false;
      btn.textContent = btn._originalText || 'SPIN THE WHEEL';
      btn.style.opacity = '';
      btn.style.cursor = '';
      btn.classList.add('slv2-bw-ready');
      slv2PlayTone(880, 0.08, 'sine', 0.10);
      setTimeout(function(){
        slv2PlayTone(1320, 0.12, 'sine', 0.10);
      }, 90);
    }
  });
}
function slv2PlayWheelSpinAudio(durationMs, rotations){
  if(!SL2.soundsEnabled) return;
  var ctx = slv2EnsureAudio();
  if(!ctx) return;
  try {
    var t0 = ctx.currentTime;
    var totalTicks = 60;
    for(var i = 0; i < totalTicks; i++){
      var fraction = i / totalTicks;
      var timeProgress = 1 - Math.pow(1 - fraction, 2.2);
      var delaySec = timeProgress * (durationMs / 1000);
      var when = t0 + delaySec;
      var pitch = 320 + (fraction * 280) + Math.random() * 40;
      var vol = 0.16 - fraction * 0.04;
      var osc = ctx.createOscillator();
      var gain = ctx.createGain();
      osc.type = 'square';
      osc.frequency.value = pitch;
      gain.gain.setValueAtTime(0.0001, when);
      gain.gain.exponentialRampToValueAtTime(vol, when + 0.002);
      gain.gain.exponentialRampToValueAtTime(0.001, when + 0.05);
      osc.connect(gain).connect(slv2AudioDest());
      osc.start(when);
      osc.stop(when + 0.06);
    }
    var bufLen = ctx.sampleRate * (durationMs / 1000 + 0.2);
    var buf = ctx.createBuffer(1, bufLen, ctx.sampleRate);
    var data = buf.getChannelData(0);
    for(var b = 0; b < bufLen; b++){
      data[b] = (Math.random() * 2 - 1) * 0.5;
    }
    var noise = ctx.createBufferSource();
    var noiseGain = ctx.createGain();
    var lp = ctx.createBiquadFilter();
    lp.type = 'lowpass';
    lp.frequency.value = 280;
    lp.Q.value = 1.2;
    noise.buffer = buf;
    noiseGain.gain.setValueAtTime(0.0001, t0);
    noiseGain.gain.exponentialRampToValueAtTime(0.10, t0 + 0.3);
    noiseGain.gain.setValueAtTime(0.10, t0 + (durationMs / 1000) * 0.7);
    noiseGain.gain.exponentialRampToValueAtTime(0.001, t0 + durationMs / 1000);
    noise.connect(lp).connect(noiseGain).connect(slv2AudioDest());
    noise.start(t0);
    noise.stop(t0 + durationMs / 1000 + 0.1);
    var lockTime = t0 + (durationMs / 1000);
    var thud = ctx.createOscillator();
    var thudG = ctx.createGain();
    thud.type = 'sine';
    thud.frequency.setValueAtTime(180, lockTime);
    thud.frequency.exponentialRampToValueAtTime(60, lockTime + 0.25);
    thudG.gain.setValueAtTime(0.0001, lockTime);
    thudG.gain.exponentialRampToValueAtTime(0.32, lockTime + 0.008);
    thudG.gain.exponentialRampToValueAtTime(0.001, lockTime + 0.3);
    thud.connect(thudG).connect(slv2AudioDest());
    thud.start(lockTime);
    thud.stop(lockTime + 0.35);
    var ding = ctx.createOscillator();
    var dingG = ctx.createGain();
    ding.type = 'sine';
    ding.frequency.value = 2349;
    dingG.gain.setValueAtTime(0.0001, lockTime + 0.04);
    dingG.gain.exponentialRampToValueAtTime(0.14, lockTime + 0.06);
    dingG.gain.exponentialRampToValueAtTime(0.001, lockTime + 0.7);
    ding.connect(dingG).connect(slv2AudioDest());
    ding.start(lockTime + 0.04);
    ding.stop(lockTime + 0.75);
  } catch(e){}
}
function slv2PlayWheelOpenFanfare(){
  if(!SL2.soundsEnabled) return;
  var ctx = slv2EnsureAudio();
  if(!ctx) return;
  try {
    var t = ctx.currentTime;
    [440, 554, 659, 880, 1109].forEach(function(freq, i){
      var osc = ctx.createOscillator();
      var gain = ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.value = freq;
      var startT = t + i * 0.12;
      gain.gain.setValueAtTime(0.0001, startT);
      gain.gain.exponentialRampToValueAtTime(0.10, startT + 0.05);
      gain.gain.exponentialRampToValueAtTime(0.001, startT + 0.45);
      osc.connect(gain).connect(slv2AudioDest());
      osc.start(startT);
      osc.stop(startT + 0.5);
    });
    var bufSize = ctx.sampleRate * 0.6;
    var buf = ctx.createBuffer(1, bufSize, ctx.sampleRate);
    var data = buf.getChannelData(0);
    for(var i = 0; i < bufSize; i++){
      data[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / bufSize, 2.5);
    }
    var noise = ctx.createBufferSource();
    var noiseGain = ctx.createGain();
    var filter = ctx.createBiquadFilter();
    filter.type = 'highpass';
    filter.frequency.value = 3500;
    noise.buffer = buf;
    noiseGain.gain.setValueAtTime(0.12, t);
    noiseGain.gain.exponentialRampToValueAtTime(0.001, t + 0.6);
    noise.connect(filter).connect(noiseGain).connect(slv2AudioDest());
    noise.start(t);
    [1760, 2093, 2637, 3136].forEach(function(freq, i){
      var osc = ctx.createOscillator();
      var gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.value = freq;
      var startT = t + 0.55 + i * 0.07;
      gain.gain.setValueAtTime(0.0001, startT);
      gain.gain.exponentialRampToValueAtTime(0.055, startT + 0.025);
      gain.gain.exponentialRampToValueAtTime(0.001, startT + 0.55);
      osc.connect(gain).connect(slv2AudioDest());
      osc.start(startT);
      osc.stop(startT + 0.6);
    });
    var bass = ctx.createOscillator();
    var bassGain = ctx.createGain();
    bass.type = 'sine';
    bass.frequency.setValueAtTime(120, t);
    bass.frequency.exponentialRampToValueAtTime(40, t + 0.5);
    bassGain.gain.setValueAtTime(0.0001, t);
    bassGain.gain.exponentialRampToValueAtTime(0.25, t + 0.02);
    bassGain.gain.exponentialRampToValueAtTime(0.001, t + 0.55);
    bass.connect(bassGain).connect(slv2AudioDest());
    bass.start(t);
    bass.stop(t + 0.6);
  } catch(e){}
}
function slv2BonusWheelSpin(){
  if(SL2.bwSpinning) return;
  SL2.bwSpinning = true;
  var btn = document.getElementById('slv2-bw-spin');
  if(btn){
    btn.disabled = true;
    btn.classList.remove('slv2-bw-ready');
  }
  var winIdx;
  if(SL2.srvMode && SL2.srvWheel && SL2.srvWheel.win_idx != null){
    winIdx = SL2.srvWheel.win_idx;
  } else {
    var weights = SL2.bwSegments.map(function(seg){ return seg.weight || 1; });
    var totalW = weights.reduce(function(a,b){return a+b;}, 0);
    var roll = Math.random() * totalW;
    winIdx = 0;
    var acc = 0;
    for(var i = 0; i < weights.length; i++){
      acc += weights[i];
      if(roll <= acc){ winIdx = i; break; }
    }
  }
  var segAngle = 360 / SL2.WHEEL_SEGMENTS;
  var rotations = 35 + Math.floor(Math.random() * 16);
  var jitter = (Math.random() - 0.5) * (segAngle * 0.7);
  var targetMod = ((-((winIdx + 0.5) * segAngle) + jitter) % 360 + 360) % 360;
  var finalAngle = rotations * 360 + targetMod;
  var spinDurationMs = 2800;
  SL2.bwSelectedIdx = winIdx;
  var rotor = document.getElementById('slv2-bw-rotor');
  if(rotor){
    if(SL2._wheelRafId){ cancelAnimationFrame(SL2._wheelRafId); SL2._wheelRafId = null; }
    rotor.style.transition = 'none';
    rotor.removeAttribute('transform');
    rotor.style.transform = 'rotate(0deg)';
    var startTime = performance.now();
    function cubicBezier(p1x, p1y, p2x, p2y){
      var samples = new Float32Array(11);
      function bezierAt(t, p1, p2){
        return ((1-t)*(1-t)*(1-t)*0) + 3*((1-t)*(1-t))*t*p1 + 3*(1-t)*(t*t)*p2 + t*t*t*1;
      }
      for(var i = 0; i <= 10; i++){
        samples[i] = bezierAt(i / 10, p1x, p2x);
      }
      function solveT(x){
        var start = 0, end = 1;
        for(var k = 0; k < 10; k++){
          if(x < samples[k+1]){
            start = k / 10;
            end = (k + 1) / 10;
            break;
          }
        }
        var t = start + (x - samples[Math.floor(start*10)]) / (samples[Math.ceil(end*10)] - samples[Math.floor(start*10)]) * (end - start);
        for(var n = 0; n < 5; n++){
          var xt = bezierAt(t, p1x, p2x);
          var deriv = 3*(1-t)*(1-t)*p1x + 6*(1-t)*t*(p2x - p1x) + 3*t*t*(1 - p2x);
          if(Math.abs(deriv) < 1e-6) break;
          t -= (xt - x) / deriv;
        }
        return Math.max(0, Math.min(1, t));
      }
      return function(x){
        if(x <= 0) return 0;
        if(x >= 1) return 1;
        var t = solveT(x);
        return bezierAt(t, p1y, p2y);
      };
    }
    var easeFn = cubicBezier(0.08, 0.4, 0.18, 1);
    function step(now){
      var elapsed = now - startTime;
      var t = Math.min(elapsed / spinDurationMs, 1);
      var eased = easeFn(t);
      var angle = eased * finalAngle;
      rotor.style.transform = 'rotate(' + angle + 'deg)';
      if(t < 1){
        SL2._wheelRafId = requestAnimationFrame(step);
      } else {
        SL2._wheelRafId = null;
        rotor.style.transform = 'rotate(' + finalAngle + 'deg)';
      }
    }
    SL2._wheelRafId = requestAnimationFrame(step);
  }
  slv2PlayWheelSpinAudio(spinDurationMs, rotations);
  setTimeout(function(){
    SL2.bwSpinning = false;
    var seg = SL2.bwSegments[winIdx];
    var segs = document.querySelectorAll('.slv2-bw-segment');
    segs.forEach(function(s){
      if(s.getAttribute('data-idx') == winIdx) s.classList.add('winning');
    });
    var result = document.getElementById('slv2-bw-result');
    var collect = document.getElementById('slv2-bw-collect');
    var spinBtn = document.getElementById('slv2-bw-spin');
    if(seg.type === 'cash'){
      var winAmount = SL2.bet * seg.value;
      SL2.totalWonThisSession += winAmount;
      winBet(winAmount, 'slots');
      if(result) result.textContent = seg.value + '\u00d7 \u2192 +\u20ac' + winAmount.toFixed(2);
      if(seg.value >= 50) slv2SendSlotEvent('big_win', { multi: seg.value, source: 'wheel_cash' });
      if(seg.value >= 500)      slv2Sound('jackpot');
      else if(seg.value >= 50)  slv2Sound('mega-win');
      else if(seg.value >= 20)  slv2Sound('big-win');
      else                      slv2Sound('medium-win');
      var lw = document.getElementById('slv2-last-win');
      if(lw){ lw.className = 'slv2-stat-val win'; lw.textContent = '+\u20ac' + winAmount.toFixed(2); }
      if(spinBtn) spinBtn.style.display = 'none';
      if(collect) collect.style.display = 'inline-block';
    }
    else if(seg.type === 'fs'){
      if(result) result.textContent = seg.value + ' FREE SPINS!';
      slv2Sound('big-win');
      if(SL2.fsActive){
        SL2.fsRemaining = (SL2.fsRemaining || 0) + seg.value;
        SL2.fsCount     = (SL2.fsCount     || 0) + seg.value;
        slv2UpdateFsUI();
        slv2SendSlotEvent('fs_round', { count: seg.value, retrigger: true });
        setTimeout(function(){
          slv2ShowFsRetriggerToast(seg.value);
          slv2BonusWheelClose();
        }, 1500);
      } else {
        setTimeout(function(){
          slv2BonusWheelClose();
          setTimeout(function(){ slv2TriggerFreeSpinsIntro(seg.value); }, 350);
        }, 1500);
      }
    }
    else if(seg.type === 'fs_random'){
      var rolledFs = (SL2.srvMode && SL2.srvWheel && SL2.srvWheel.result && SL2.srvWheel.result.fs != null)
        ? SL2.srvWheel.result.fs : slv2RollRandomFsCount();
      if(result) result.textContent = '';
      slv2PlayFsRollAnimation(rolledFs, function(){
        slv2Sound('big-win');
        if(SL2.fsActive){
          SL2.fsRemaining = (SL2.fsRemaining || 0) + rolledFs;
          SL2.fsCount     = (SL2.fsCount     || 0) + rolledFs;
          slv2UpdateFsUI();
          slv2SendSlotEvent('fs_round', { count: rolledFs, retrigger: true });
          setTimeout(function(){
            slv2ShowFsRetriggerToast(rolledFs);
            slv2BonusWheelClose();
          }, 1200);
        } else {
          setTimeout(function(){
            slv2BonusWheelClose();
            setTimeout(function(){ slv2TriggerFreeSpinsIntro(rolledFs); }, 350);
          }, 1200);
        }
      });
    }
    else if(seg.type === 'chest'){
      if(result) result.textContent = 'VAULT UNLOCKED!';
      slv2Sound('big-win');
      setTimeout(function(){
        slv2BonusWheelClose();
        setTimeout(function(){ if(typeof slv2VaultTrigger === 'function') slv2VaultTrigger(); }, 350);
      }, 1500);
    }
    else if(seg.type === 'mystery'){
      var tierCap = (SL2.bwTier === 'HIGH') ? 200 :
                    (SL2.bwTier === 'MID')  ? 40  : 8;
      var mystMulti = (SL2.srvMode && SL2.srvWheel && SL2.srvWheel.result && SL2.srvWheel.result.mystery_mult != null)
        ? SL2.srvWheel.result.mystery_mult
        : Math.max(1, Math.floor(Math.random() * Math.random() * tierCap));
      var mystAmount = SL2.bet * mystMulti;
      SL2.totalWonThisSession += mystAmount;
      winBet(mystAmount, 'slots');
      slv2SendSlotEvent('mystery_hit', { multi: mystMulti });
      var bigThreshold = (SL2.bwTier === 'HIGH') ? 50 : (SL2.bwTier === 'MID') ? 20 : 6;
      if(mystMulti >= bigThreshold) slv2SendSlotEvent('big_win', { multi: mystMulti, source: 'wheel_mystery' });
      if(result) result.textContent = 'MYSTERY: ' + mystMulti + '\u00d7 \u2192 +\u20ac' + mystAmount.toFixed(2);
      if(mystMulti >= bigThreshold)         slv2Sound('mega-win');
      else if(mystMulti >= bigThreshold/2)  slv2Sound('big-win');
      else                                  slv2Sound('medium-win');
      var lw2 = document.getElementById('slv2-last-win');
      if(lw2){ lw2.className = 'slv2-stat-val win'; lw2.textContent = '+\u20ac' + mystAmount.toFixed(2); }
      if(spinBtn) spinBtn.style.display = 'none';
      if(collect) collect.style.display = 'inline-block';
    }
    else if(seg.type === 'jackpot'){
      if(result) result.textContent = 'JACKPOT!!! CLAIMING...';
      slv2Sound('jackpot');
      slv2SendSlotEvent('progressive_win');
      slv2HandleJackpotWin(spinBtn, collect, result);
    }
  }, spinDurationMs + 800);
}
function slv2HandleJackpotWin(spinBtn, collect, result){
  if(spinBtn) spinBtn.style.display = 'none';
  var userId = (window.S && window.S.userId) ? window.S.userId : null;
  if(!userId){
    if(result) result.textContent = 'JACKPOT! +\u20ac100 (offline)';
    winBet(100, 'slots');
    if(collect) collect.style.display = 'inline-block';
    return;
  }
  fetch(BACKEND + '/jackpot/win', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'ngrok-skip-browser-warning': '1'
    },
    body: JSON.stringify({ user_id: userId, source: 'wheel_jackpot_segment' })
  })
  .then(function(r){ return r.json(); })
  .then(function(data){
    if(data && data.ok && data.paid_eur){
      var paidEur = parseFloat(data.paid_eur);
      var paidBtc = parseFloat(data.paid_btc);
      SL2.totalWonThisSession += paidEur;
      if(typeof refreshBalance === 'function') refreshBalance();
      else if(typeof S !== 'undefined' && typeof S.btcBal !== 'undefined'){
        S.btcBal += paidBtc;
        if(typeof updateBalanceDisplay === 'function') updateBalanceDisplay();
      }
      if(result){
        result.innerHTML = '\ud83c\udfc6 JACKPOT! \ud83c\udfc6<br>+\u20ac' + paidEur.toFixed(2);
        result.style.fontSize = '32px';
        result.style.color = '#ffd700';
      }
      var lw = document.getElementById('slv2-last-win');
      if(lw){
        lw.className = 'slv2-stat-val win';
        lw.textContent = '+\u20ac' + paidEur.toFixed(2);
      }
      slv2FetchJackpot();
      slv2PlayJackpotCelebration();
    } else {
      if(result) result.textContent = 'Pool claimed by another player!';
    }
    if(collect) collect.style.display = 'inline-block';
  })
  .catch(function(err){
    console.error('[jackpot] /jackpot/win failed:', err);
    if(result) result.textContent = 'JACKPOT win pending — refresh balance';
    if(collect) collect.style.display = 'inline-block';
  });
}
function slv2PlayJackpotCelebration(){
  if(!SL2.soundsEnabled) return;
  var ctx = slv2EnsureAudio();
  if(!ctx) return;
  try {
    var t = ctx.currentTime;
    [523, 659, 784, 1047, 1319, 1568, 2093].forEach(function(freq, i){
      var osc = ctx.createOscillator();
      var gain = ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.value = freq;
      var startT = t + i * 0.18;
      gain.gain.setValueAtTime(0.0001, startT);
      gain.gain.exponentialRampToValueAtTime(0.18, startT + 0.05);
      gain.gain.exponentialRampToValueAtTime(0.001, startT + 0.7);
      osc.connect(gain).connect(slv2AudioDest());
      osc.start(startT);
      osc.stop(startT + 0.8);
    });
    for(var i = 0; i < 12; i++){
      var osc = ctx.createOscillator();
      var gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.value = 1760 + Math.random() * 1600;
      var startT = t + 1.2 + i * 0.08;
      gain.gain.setValueAtTime(0.0001, startT);
      gain.gain.exponentialRampToValueAtTime(0.10, startT + 0.02);
      gain.gain.exponentialRampToValueAtTime(0.001, startT + 0.5);
      osc.connect(gain).connect(slv2AudioDest());
      osc.start(startT);
      osc.stop(startT + 0.55);
    }
  } catch(e){}
}
function slv2BonusWheelClose(){
  var ov = document.getElementById('slv2-bonus-wheel');
  slv2CancelCountdown('slv2-bonus-wheel');
  var bwVid = document.getElementById('slv2-bw-video');
  if(bwVid){ try { bwVid.pause(); } catch(e){} }
  if(ov){
    ov.classList.remove('visible');
    ov.classList.remove('video-intro-active');
  }
  if(SL2._wheelRafId){ cancelAnimationFrame(SL2._wheelRafId); SL2._wheelRafId = null; }
  SL2.bonusActive = false;
  SL2.bonusWheelOpen = false;
  if(SL2.fsActive){
    if(SL2.fsRemaining > 0){
      slv2QueueSpin(800);
    } else {
      slv2EndFreeSpins();
    }
    return;
  }
  if(SL2.autoActive && SL2.autoRemaining > 0){
    slv2QueueSpin(800, { requireAuto: true });
    return;
  }
  slv2EnableSpinIfIdle();
}
function slv2ShowFsRetriggerToast(extra){
  var fsCard = document.getElementById('slv2-fs-card');
  if(!fsCard) return;
  var toast = document.createElement('div');
  toast.className = 'slv2-fs-retrigger-toast';
  toast.textContent = '+' + extra + ' FREE SPINS!';
  fsCard.appendChild(toast);
  setTimeout(function(){
    if(toast.parentNode) toast.parentNode.removeChild(toast);
  }, 2200);
}
function slv2VaultTrigger(){
  if(SL2.bonusActive) return;
  SL2.bonusActive = true;
  SL2.vaultOpen = true;
  slv2DisableSpin();
  SL2.vaultPickedIdx = null;
  slv2SendSlotEvent('vault_open');
  var prizes = [];
  var bwTier = SL2.bwTier || slv2WheelTierForBet(SL2.bet || 1);
  if(Math.random() < 0.60){
    var hiCashTable = (bwTier === 'HIGH') ? [25, 35, 50, 75] :
                      (bwTier === 'MID')  ? [10, 15, 20, 30] :
                                            [4,  6,  8,  12];
    prizes.push({type:'cash', value: hiCashTable[Math.floor(Math.random() * 4)]});
  } else {
    var hiFsTable = (bwTier === 'HIGH') ? [10, 12, 15, 20] :
                    (bwTier === 'MID')  ? [8,  10, 12, 15] :
                                          [5,  6,  8,  10];
    prizes.push({type:'fs', value: hiFsTable[Math.floor(Math.random() * 4)]});
  }
  if(Math.random() < 0.60){
    var midCashTable = (bwTier === 'HIGH') ? [10, 15, 20, 25] :
                       (bwTier === 'MID')  ? [4,  6,  9,  12] :
                                             [2,  3,  4,  6];
    prizes.push({type:'cash', value: midCashTable[Math.floor(Math.random() * 4)]});
  } else {
    var midFsTable = (bwTier === 'HIGH') ? [7,  9,  11, 13] :
                     (bwTier === 'MID')  ? [5,  6,  7,  8]  :
                                           [3,  4,  5,  6];
    prizes.push({type:'fs', value: midFsTable[Math.floor(Math.random() * 4)]});
  }
  var lowCashTable = (bwTier === 'HIGH') ? [3, 5, 7, 10] :
                     (bwTier === 'MID')  ? [1, 2, 3, 5]  :
                                           [0.5, 1, 1.5, 2];
  prizes.push({type:'cash', value: lowCashTable[Math.floor(Math.random() * 4)]});
  for(var i = prizes.length - 1; i > 0; i--){
    var j = Math.floor(Math.random() * (i + 1));
    var tmp = prizes[i]; prizes[i] = prizes[j]; prizes[j] = tmp;
  }
  if(SL2.srvMode && SL2.srvWheel && SL2.srvWheel.result && SL2.srvWheel.result.vault){
    prizes = SL2.srvWheel.result.vault.prizes.map(function(p){ return {type:p[0], value:p[1]}; });
  }
  SL2.vaultPrizes = prizes;
  for(var k = 0; k < 3; k++){
    var v = document.querySelector('.slv2-vault[data-idx="' + k + '"]');
    if(v){
      v.classList.remove('picked','revealed','disabled');
    }
    var pz = document.getElementById('slv2-vault-prize-' + k);
    if(pz){
      var p = prizes[k];
      var html;
      if(p.type === 'cash'){
        html = '<div class="multi" style="color:#ffd700;">' + p.value + '×</div>' +
               '<div class="label" style="color:#39ff14;">CASH PRIZE</div>';
      } else if(p.type === 'fs'){
        html = '<div class="multi" style="color:#39ff14;font-size:28px;">' + p.value + '</div>' +
               '<div class="label" style="color:#39ff14;">FREE SPINS</div>';
      }
      pz.innerHTML = html;
    }
  }
  var result = document.getElementById('slv2-vg-result');
  if(result) result.textContent = '';
  var collect = document.getElementById('slv2-vg-collect');
  if(collect) collect.style.display = 'none';
  var ov = document.getElementById('slv2-vault-game');
  var vgVid = document.getElementById('slv2-vg-video');
  var vgHasVideo = !!(vgVid && vgVid.getAttribute('src') &&
                      parseInt((vgVid.dataset && vgVid.dataset.failCount) || '0', 10) < 3);
  if(ov){
    ov.classList.add('visible');
    if(vgHasVideo) ov.classList.add('video-intro-active');
  }
  if(vgHasVideo) slv2RestartVideo('slv2-vg-video');
  slv2Sound('free-spins');
  SL2.vaultPickGated = true;
  var vEls = document.querySelectorAll('.slv2-vault');
  vEls.forEach(function(v){
    v.style.opacity = '.55';
    v.style.pointerEvents = 'none';
    v.style.transition = 'opacity .5s ease-out';
  });
  var vgCountdownSec = vgHasVideo ? 3 : 1;
  slv2RunCountdown('slv2-vault-game', vgCountdownSec, function(){
    if(ov){
      ov.classList.remove('video-intro-active');
      var vgVid = document.getElementById('slv2-vg-video');
      if(vgVid){ try { vgVid.pause(); } catch(e){} }
    }
    SL2.vaultPickGated = false;
    vEls.forEach(function(v){
      v.style.opacity = '';
      v.style.pointerEvents = '';
    });
    try { slv2PlayTone(1320, 0.18, 'sine', 0.12); } catch(e){}
  });
}
function slv2VaultPick(idx){
  if(!SL2.bonusActive) return;
  if(SL2.vaultPickGated) return;
  if(SL2.vaultPickedIdx !== undefined && SL2.vaultPickedIdx !== null) return;
  SL2.vaultPickedIdx = idx;
  var vaults = document.querySelectorAll('.slv2-vault');
  vaults.forEach(function(v, i){
    if(i === idx){
      v.classList.add('picked','revealed');
    } else {
      v.classList.add('revealed','disabled');
    }
  });
  var prize = (SL2.srvMode && SL2.srvWheel && SL2.srvWheel.result && SL2.srvWheel.result.vault)
    ? SL2.vaultPrizes[SL2.srvWheel.result.vault.win_idx] : SL2.vaultPrizes[idx];
  var result = document.getElementById('slv2-vg-result');
  var collect = document.getElementById('slv2-vg-collect');
  if(prize.type === 'cash'){
    var winAmount = SL2.bet * prize.value;
    SL2.totalWonThisSession += winAmount;
    winBet(winAmount, 'slots');
    if(result){
      result.textContent = 'YOU WON ' + prize.value + '\u00d7 \u2192 +\u20ac' + winAmount.toFixed(2);
    }
    if(collect) collect.style.display = 'inline-block';
    if(prize.value >= 25) slv2Sound('big-win');
    else if(prize.value >= 10) slv2Sound('medium-win');
    else slv2Sound('small-win');
    var lw = document.getElementById('slv2-last-win');
    if(lw){
      lw.className = 'slv2-stat-val win';
      lw.textContent = '+\u20ac' + winAmount.toFixed(2);
    }
  }
  else if(prize.type === 'fs'){
    if(result){
      result.textContent = 'YOU WON ' + prize.value + ' FREE SPINS!';
    }
    slv2Sound('big-win');
    if(SL2.fsActive){
      SL2.fsRemaining = (SL2.fsRemaining || 0) + prize.value;
      SL2.fsCount     = (SL2.fsCount     || 0) + prize.value;
      slv2UpdateFsUI();
      slv2SendSlotEvent('fs_round', { count: prize.value, retrigger: true });
      setTimeout(function(){
        slv2ShowFsRetriggerToast(prize.value);
        slv2VaultClose();
      }, 1800);
    } else {
      setTimeout(function(){
        slv2VaultClose();
        setTimeout(function(){ slv2TriggerFreeSpinsIntro(prize.value); }, 400);
      }, 1800);
    }
  }
}
function slv2VaultClose(){
  var ov = document.getElementById('slv2-vault-game');
  slv2CancelCountdown('slv2-vault-game');
  var vgVid = document.getElementById('slv2-vg-video');
  if(vgVid){ try { vgVid.pause(); } catch(e){} }
  if(ov){
    ov.classList.remove('visible');
    ov.classList.remove('video-intro-active');
  }
  SL2.bonusActive = false;
  SL2.vaultOpen = false;
  SL2.vaultPickedIdx = null;
  SL2.vaultPickGated = false;
  document.querySelectorAll('.slv2-vault').forEach(function(v){
    v.style.opacity = '';
    v.style.pointerEvents = '';
  });
  if(SL2.fsActive){
    if(SL2.fsRemaining > 0){
      slv2QueueSpin(800);
    } else {
      slv2EndFreeSpins();
    }
    return;
  }
  if(SL2.autoActive && SL2.autoRemaining > 0){
    slv2QueueSpin(800, { requireAuto: true });
    return;
  }
  slv2EnableSpinIfIdle();
}
function slv2MaybeTriggerBonus(spinHadWin){
  if(SL2.fsActive) return false;
  if(SL2.bonusActive) return false;
  if(SL2.srvMode){
    if(SL2.srv && SL2.srv.round && SL2.srv.round.wheel && SL2.srv.round.wheel.forced && !SL2.srv.wheelShown){
      SL2.srv.wheelShown = true;
      slv2FakeWheelScatterReveal();
      return true;
    }
    return false;
  }
  if(!spinHadWin) SL2.losingStreak++;
  else SL2.losingStreak = 0;
  SL2.spinCount++;
  SL2.spinsSinceLastBonus++;
  if(SL2.spinsSinceLastBonus >= SL2.nextBonusAt){
    slv2FakeWheelScatterReveal();
    slv2ResetBonusCounter();
    SL2.losingStreak = 0;
    return true;
  }
  if(SL2.losingStreak >= SL2.VAULT_LOSING_THRESHOLD){
    if(Math.random() < SL2.VAULT_LOSING_CHANCE){
      SL2.losingStreak = 0;
      slv2ResetBonusCounter();
      setTimeout(slv2VaultTrigger, 600);
      return true;
    }
  }
  return false;
}
function slv2PlayFsRollAnimation(finalCount, onDone){
  var box = document.getElementById('slv2-fs-roll');
  var num = document.getElementById('slv2-fs-roll-num');
  var sub = document.getElementById('slv2-fs-roll-sub');
  if(!box || !num){ if(onDone) onDone(); return; }
  box.classList.remove('visible');
  num.classList.remove('locked');
  num.textContent = '5';
  if(sub) sub.textContent = 'rolling\u2026';
  void box.offsetWidth;
  box.classList.add('visible');
  var totalDuration = 1700;
  var ticks = [];
  var t = 0;
  var i = 0;
  while(t < totalDuration){
    var progress = t / totalDuration;
    var gap = 45 + Math.pow(progress, 2.6) * 240;
    ticks.push(t);
    t += gap;
    i++;
    if(i > 200) break;
  }
  var lastTickAt = ticks[ticks.length - 1];
  ticks.push(lastTickAt + 280);
  ticks.forEach(function(delay, idx){
    setTimeout(function(){
      var isFinal = (idx === ticks.length - 1);
      if(isFinal){
        num.textContent = String(finalCount);
        num.classList.add('locked');
        if(sub) sub.textContent = 'FREE SPINS!';
        try {
          var ctx = slv2EnsureAudio();
          if(ctx){
            var osc = ctx.createOscillator();
            var g   = ctx.createGain();
            osc.type = 'triangle';
            osc.frequency.setValueAtTime(1568, ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(3136, ctx.currentTime + 0.18);
            g.gain.setValueAtTime(0, ctx.currentTime);
            g.gain.linearRampToValueAtTime(0.22, ctx.currentTime + 0.02);
            g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.55);
            osc.connect(g).connect(slv2AudioDest());
            osc.start(ctx.currentTime);
            osc.stop(ctx.currentTime + 0.6);
          }
        } catch(e){}
        setTimeout(function(){
          box.classList.remove('visible');
          if(onDone) onDone();
        }, 950);
      } else {
        var roll = 5 + Math.floor(Math.random() * 11);
        num.textContent = String(roll);
        try {
          var ctx2 = slv2EnsureAudio();
          if(ctx2){
            var prog = idx / ticks.length;
            var freq = 800 + prog * 600;
            slv2PlayTone(freq, 0.04, 'triangle', 0.07);
          }
        } catch(e){}
      }
    }, delay);
  });
}
function slv2ResetBonusCounter(){
  SL2.spinsSinceLastBonus = 0;
  SL2.nextBonusAt = 45 + Math.floor(Math.random() * 31);
}
function slv2FakeWheelScatterReveal(){
  SL2.fakeRevealActive = true;
  slv2DisableSpin();
  var allSymbols = SL2_SYMS.slice();
  var fillerPool = allSymbols.filter(function(s){ return s !== 'wheel' && s !== 'bot'; });
  var reelChoices = [0,1,2,3,4].sort(function(){ return Math.random() - 0.5; }).slice(0,3).sort();
  var picks = reelChoices.map(function(r){
    return { reel: r, row: Math.floor(Math.random() * 3) };
  });
  var cab = document.querySelector('.slv2-cabinet');
  if(cab){
    cab.classList.add('wheel-suspense', 'tier-1');
  }
  var slotScreen = document.getElementById('slots');
  if(slotScreen){
    slotScreen.classList.add('suspense-active', 'suspense-tier-1');
  }
  picks.forEach(function(p, idxOuter){
    var strip = document.getElementById('slv2-strip-' + p.reel);
    if(!strip) return;
    var cellIdx = SL2.positions[p.reel] + (p.row - 1);
    var cell = strip.children[cellIdx];
    if(!cell) return;
    p.cell = cell;
    p.origClass = cell.className;
    p.origHTML  = cell.innerHTML;
    var startDelay   = idxOuter * 480;
    var preFlashMs   = 220;
    var scrollMs     = 1100 + idxOuter * 260;
    var slamMs       = 260;
    var totalCellMs  = preFlashMs + scrollMs + slamMs;
    setTimeout(function(){
      cell.classList.add('slv2-fake-preflash');
      try { slv2PlayTone(660 + idxOuter * 80, 0.06, 'sine', 0.10); } catch(e){}
      setTimeout(function(){
        cell.classList.remove('slv2-fake-preflash');
        var nMini = 14;
        var miniH = 66;
        var miniStripHTML = '';
        for(var ms = 0; ms < nMini; ms++){
          var sym = fillerPool[Math.floor(Math.random() * fillerPool.length)];
          var inner = slv2SymHTML(sym);
          miniStripHTML += '<div class="slv2-fake-mini-cell" data-sym="' + sym + '">' + inner + '</div>';
        }
        cell.classList.add('slv2-fake-spin-container');
        cell.innerHTML = '<div class="slv2-fake-mini-strip" id="slv2-fake-mini-' + p.reel + '">' + miniStripHTML + '</div>';
        var miniStrip = cell.querySelector('.slv2-fake-mini-strip');
        if(miniStrip){
          var scrollDistance = (nMini - 1) * miniH;
          miniStrip.style.transform = 'translateY(-' + scrollDistance + 'px)';
          void miniStrip.offsetWidth;
          miniStrip.style.transition = 'transform ' + scrollMs + 'ms linear, filter ' + scrollMs + 'ms ease-out';
          miniStrip.style.filter = 'blur(0.8px)';
          miniStrip.style.transform = 'translateY(0px)';
          setTimeout(function(){
            try { slv2PlayTone(1100 + idxOuter * 80, 0.07, 'triangle', 0.09); } catch(e){}
            if(miniStrip) miniStrip.style.filter = 'blur(0px)';
          }, scrollMs - 80);
        }
        setTimeout(function(){
          cell.classList.remove('slv2-fake-spin-container');
          cell.innerHTML = slv2WheelSVG();
          cell.className = 'slv2-sym sym-wheel wheel-locked slv2-fake-slam';
          cell.classList.add('wheel-strobe');
          (function(c2){ setTimeout(function(){ if(c2) c2.classList.remove('wheel-strobe'); }, 800); })(cell);
          try { slv2PlayTone(540, 0.10, 'square', 0.14); } catch(e){}
          try { slv2PlayTone(90, 0.18, 'sine', 0.26); } catch(e){}
          try { slv2PlayTone(1760, 0.10, 'triangle', 0.08); } catch(e){}
          slv2PlayWheelSuspenseLayer(idxOuter);
          slv2SpawnWheelBurst(cell);
          if(cab){
            cab.classList.remove('tier-1','tier-2','tier-3');
            cab.classList.add('tier-' + (idxOuter + 1));
            if(idxOuter >= 1) cab.classList.add('tier-max');
          }
          if(slotScreen){
            slotScreen.classList.remove('suspense-tier-1','suspense-tier-2','suspense-tier-3');
            slotScreen.classList.add('suspense-tier-' + (idxOuter + 1));
          }
          if(idxOuter === 1 && !SL2._wheelHeartbeatId){
            SL2._wheelHeartbeatId = setInterval(slv2PlayHeartbeatThump, 580);
          }
          setTimeout(function(){
            if(cell) cell.classList.remove('slv2-fake-slam');
          }, 800);
          if(idxOuter === picks.length - 1){
            setTimeout(function(){
              slv2DrawWheelTriggerBeams(picks);
              slv2ShowWheelTriggerBanner();
              if(cab){
                cab.classList.add('slv2-fake-climax-shake');
                setTimeout(function(){
                  if(cab) cab.classList.remove('slv2-fake-climax-shake');
                }, 700);
              }
            }, 80);
          }
        }, scrollMs);
      }, preFlashMs);
    }, startDelay);
  });
  var lastIdx = picks.length - 1;
  var lastEnd = lastIdx * 480 + 220 + (1100 + lastIdx * 260) + 260;
  var lingerMs = 1100;
  setTimeout(function(){
    picks.forEach(function(p){
      if(!p.cell) return;
      p.cell.style.transition = 'transform .35s ease-in, opacity .35s ease-in';
      p.cell.style.transform  = 'scale(.85)';
      p.cell.style.opacity    = '0.45';
    });
    slv2FadeOutWheelTriggerBeams();
    setTimeout(function(){
      picks.forEach(function(p){
        if(!p.cell) return;
        p.cell.className = p.origClass;
        p.cell.innerHTML = p.origHTML;
        p.cell.style.transition = '';
        p.cell.style.transform  = '';
        p.cell.style.opacity    = '';
      });
      slv2RemoveWheelTriggerBeams();
      slv2ClearAnticipation();
      if(SL2._wheelHeartbeatId){
        clearInterval(SL2._wheelHeartbeatId);
        SL2._wheelHeartbeatId = null;
      }
      slv2BonusWheelTrigger();
      SL2.fakeRevealActive = false;
    }, 380);
  }, lastEnd + lingerMs);
}
function slv2DrawWheelTriggerBeams(picks){
  var grid = document.getElementById('slv2-reels');
  if(!grid || picks.length < 2) return;
  slv2RemoveWheelTriggerBeams();
  var svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('id', 'slv2-fake-beams');
  svg.setAttribute('class', 'slv2-fake-beams');
  svg.setAttribute('viewBox', '0 0 500 240');
  svg.setAttribute('preserveAspectRatio', 'none');
  var pts = picks.map(function(p){
    return { x: (p.reel + 0.5) * 100, y: (p.row + 0.5) * 80 };
  });
  pts.sort(function(a, b){ return a.x - b.x; });
  var d = 'M ' + pts[0].x + ' ' + pts[0].y;
  for(var i = 1; i < pts.length; i++){
    var midX = (pts[i-1].x + pts[i].x) / 2;
    var midY = (pts[i-1].y + pts[i].y) / 2 - 12;
    d += ' Q ' + midX + ' ' + midY + ' ' + pts[i].x + ' ' + pts[i].y;
  }
  var glow = document.createElementNS('http://www.w3.org/2000/svg', 'path');
  glow.setAttribute('d', d);
  glow.setAttribute('class', 'slv2-fake-beam-glow');
  svg.appendChild(glow);
  var core = document.createElementNS('http://www.w3.org/2000/svg', 'path');
  core.setAttribute('d', d);
  core.setAttribute('class', 'slv2-fake-beam-core');
  svg.appendChild(core);
  var dot = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
  dot.setAttribute('class', 'slv2-fake-beam-dot');
  dot.setAttribute('r', '4');
  dot.setAttribute('cx', pts[0].x);
  dot.setAttribute('cy', pts[0].y);
  svg.appendChild(dot);
  grid.appendChild(svg);
  void svg.offsetWidth;
  svg.classList.add('visible');
}
function slv2FadeOutWheelTriggerBeams(){
  var svg = document.getElementById('slv2-fake-beams');
  if(svg) svg.classList.remove('visible');
}
function slv2RemoveWheelTriggerBeams(){
  var svg = document.getElementById('slv2-fake-beams');
  if(svg && svg.parentNode) svg.parentNode.removeChild(svg);
  var bnr = document.getElementById('slv2-fake-trigger-banner');
  if(bnr && bnr.parentNode) bnr.parentNode.removeChild(bnr);
}
function slv2ShowWheelTriggerBanner(){
  var cab = document.querySelector('.slv2-cabinet');
  if(!cab) return;
  var old = document.getElementById('slv2-fake-trigger-banner');
  if(old && old.parentNode) old.parentNode.removeChild(old);
  var bnr = document.createElement('div');
  bnr.id = 'slv2-fake-trigger-banner';
  bnr.className = 'slv2-fake-trigger-banner';
  bnr.innerHTML = '<span class="slv2-fake-trigger-pre">\u2728</span>' +
                  '<span class="slv2-fake-trigger-main">WHEEL TRIGGERED</span>' +
                  '<span class="slv2-fake-trigger-pre">\u2728</span>';
  cab.appendChild(bnr);
  void bnr.offsetWidth;
  bnr.classList.add('visible');
}
function slv2SymHTML(sym){
  if(sym === 'wheel')  return slv2WheelSVG();
  if(sym === 'btc')    return slv2GbLogoHTML();
  if(sym === 'gblogo') return slv2BtcCoinHTML();
  if(sym === 'ton')    return slv2TonCoinHTML();
  if(typeof SL2_CHAR !== 'undefined' && SL2_CHAR[sym]) return SL2_CHAR[sym];
  return '?';
}
function slv2CheckAnticipation(){
  var scatterCount = 0;
  for(var r = 0; r < 4; r++){
    for(var row = 0; row < 3; row++){
      if(SL2.grid[r] && SL2.grid[r][row] === 'bot') scatterCount++;
    }
  }
  if(scatterCount >= 2){
    var col = document.querySelectorAll('.slv2-reel-col')[4];
    var strip = document.getElementById('slv2-strip-4');
    if(col) col.classList.add('anticipating-col');
    if(strip) strip.classList.add('anticipating');
    return true;
  }
  return false;
}
function slv2RunCountdown(overlayId, seconds, cb){
  var prefix = ({
    'slv2-fs-intro':    'slv2-fs',
    'slv2-bonus-wheel': 'slv2-bw',
    'slv2-vault-game':  'slv2-vg'
  })[overlayId];
  if(!prefix){ if(cb) cb(); return; }
  var box  = document.getElementById(prefix + '-countdown');
  var ring = document.getElementById(prefix + '-countdown-ring');
  var num  = document.getElementById(prefix + '-countdown-num');
  if(!box || !ring || !num){ if(cb) cb(); return; }
  box.classList.add('show');
  var CIRC = 226;
  ring.style.transition = 'none';
  ring.style.strokeDashoffset = '0';
  void ring.offsetWidth;
  ring.style.transition = 'stroke-dashoffset ' + seconds + 's linear';
  ring.style.strokeDashoffset = CIRC;
  var remaining = seconds;
  num.textContent = remaining;
  try { slv2PlayTone(660, 0.06, 'sine', 0.10); } catch(e){}
  var tickInterval = setInterval(function(){
    remaining--;
    if(remaining <= 0){
      num.textContent = 'GO!';
      try { slv2PlayTone(1320, 0.18, 'square', 0.14); } catch(e){}
      clearInterval(tickInterval);
      return;
    }
    num.textContent = remaining;
    try { slv2PlayTone(660 + (seconds - remaining) * 80, 0.06, 'sine', 0.10); } catch(e){}
  }, 1000);
  var finalTimer = setTimeout(function(){
    box.classList.remove('show');
    if(cb) cb();
  }, seconds * 1000);
  box._countdownTimers = [tickInterval, finalTimer];
}
function slv2CancelCountdown(overlayId){
  var prefix = ({
    'slv2-fs-intro':    'slv2-fs',
    'slv2-bonus-wheel': 'slv2-bw',
    'slv2-vault-game':  'slv2-vg'
  })[overlayId];
  if(!prefix) return;
  var box = document.getElementById(prefix + '-countdown');
  if(!box) return;
  box.classList.remove('show');
  if(box._countdownTimers){
    box._countdownTimers.forEach(function(t){
      clearInterval(t); clearTimeout(t);
    });
    box._countdownTimers = null;
  }
}
var SL2_AUDIO_UNLOCKED = false;
function slv2UnmuteVideo(videoId, pillId){
  var v = document.getElementById(videoId);
  if(!v) return;
  try {
    v.muted = false;
    v.volume = 0.7;
    if(v.paused){
      var p = v.play();
      if(p && p.catch) p.catch(function(){});
    }
    SL2_AUDIO_UNLOCKED = true;
  } catch(e){}
  ['slv2-fs-sound-hint','slv2-bw-sound-hint','slv2-vg-sound-hint'].forEach(function(pid){
    var pill = document.getElementById(pid);
    if(pill) pill.classList.remove('show');
  });
}
function slv2MaybeShowSoundHint(overlayId){
  if(SL2_AUDIO_UNLOCKED) return;
  var prefix = ({
    'slv2-fs-intro':    'slv2-fs',
    'slv2-bonus-wheel': 'slv2-bw',
    'slv2-vault-game':  'slv2-vg'
  })[overlayId];
  if(!prefix) return;
  var videoId = ({
    'slv2-fs-intro':    'slv2-fs-intro-video',
    'slv2-bonus-wheel': 'slv2-bw-video',
    'slv2-vault-game':  'slv2-vg-video'
  })[overlayId];
  var v = document.getElementById(videoId);
  if(!v || !v.getAttribute('src')) return;
  setTimeout(function(){
    var pill = document.getElementById(prefix + '-sound-hint');
    if(pill && v.muted && !SL2_AUDIO_UNLOCKED){
      pill.classList.add('show');
    }
  }, 700);
}
function slv2SetFreeSpinsVideo(url){ slv2SetVideoSrc('slv2-fs-intro-video', url); }
function slv2SetWheelVideo(url){     slv2SetVideoSrc('slv2-bw-video', url); }
function slv2SetVaultVideo(url){     slv2SetVideoSrc('slv2-vg-video', url); }
function slv2SetVideoSrc(elemId, url){
  var v = document.getElementById(elemId);
  if(!v) return;
  var overlay = v.closest && v.closest('.slv2-fs-intro, .slv2-fs-summary, .slv2-bonus-wheel, .slv2-vault-game');
  if(!url){
    v.removeAttribute('src');
    v.style.display = 'none';
    if(overlay) overlay.classList.remove('has-video');
    delete v.dataset.intendedSrc;
    v.load();
    return;
  }
  v.dataset.intendedSrc = url;
  v.dataset.failCount = v.dataset.failCount || '0';
  v.onerror = function(){
    var failCount = parseInt(v.dataset.failCount || '0', 10) + 1;
    v.dataset.failCount = failCount;
    console.warn('[slv2 video] failed to load:', url, '(attempt #' + failCount + ') — will retry on next trigger.');
    if(failCount >= 3){
      console.warn('[slv2 video] giving up on', url, 'after 3 failures — using CSS fallback.');
      v.style.display = 'none';
      v.removeAttribute('src');
    }
    if(overlay) overlay.classList.remove('has-video');
  };
  v.onloadeddata = function(){
    console.info('[slv2 video] loaded:', url);
    v.dataset.failCount = '0';
  };
  if(!v._slv2ListenersAttached){
    v._slv2ListenersAttached = true;
    v.addEventListener('playing', function(){
      var ov2 = v.closest && v.closest('.slv2-fs-intro, .slv2-fs-summary, .slv2-bonus-wheel, .slv2-vault-game');
      if(ov2) ov2.classList.add('has-video');
    });
    v.addEventListener('pause', function(){
      var ov2 = v.closest && v.closest('.slv2-fs-intro, .slv2-fs-summary, .slv2-bonus-wheel, .slv2-vault-game');
      if(ov2 && v.ended) ov2.classList.remove('has-video');
    });
    v.addEventListener('ended', function(){
      var ov2 = v.closest && v.closest('.slv2-fs-intro, .slv2-fs-summary, .slv2-bonus-wheel, .slv2-vault-game');
      if(ov2) ov2.classList.remove('has-video');
    });
  }
  v.setAttribute('src', url);
  v.muted = true;
  v.playsInline = true;
  v.style.display = 'block';
  v.load();
  var p = v.play();
  if(p && typeof p.catch === 'function'){
    p.catch(function(err){
      if(err && err.name !== 'AbortError'){
        console.warn('[slv2 video] autoplay blocked for', url, '—', err && err.name);
      }
    });
  }
}
function slv2RestartVideo(elemId){
  var v = document.getElementById(elemId);
  if(!v) return;
  if(!v.getAttribute('src') && v.dataset && v.dataset.intendedSrc){
    console.info('[slv2 video] retrying with stored URL:', v.dataset.intendedSrc);
    v.setAttribute('src', v.dataset.intendedSrc);
    v.style.display = 'block';
    v.dataset.failCount = '0';
    v.load();
  }
  if(!v.getAttribute('src')) return;
  v.style.display = 'block';
  try { v.pause(); } catch(e){}
  requestAnimationFrame(function(){
    try {
      v.currentTime = 0;
      v.classList.remove('ended');
      v.muted = false;
      v.volume = 0.6;
      var p = v.play();
      v._slv2ActivePlay = p;
      if(p && typeof p.catch === 'function'){
        p.catch(function(err){
          if(err && err.name === 'AbortError') return;
          v.muted = true;
          v.currentTime = 0;
          var p2 = v.play();
          v._slv2ActivePlay = p2;
          if(p2 && p2.catch) p2.catch(function(){});
        });
      }
    } catch(e){}
  });
}
function slv2WireVideoEndHandlers(){
  ['slv2-fs-intro-video','slv2-bw-video','slv2-vg-video'].forEach(function(id){
    var v = document.getElementById(id);
    if(!v) return;
    v.addEventListener('ended', function(){
      v.classList.add('ended');
    });
  });
}
var SLOT_CONFIG = {
  logoUrl: null,
  freeSpins:  'fs-intro.mp4',
  wheelBonus: 'wheel-intro.mp4',
  pickVault:  'vault-intro.mp4'
};
var SLOT_VIDEOS = SLOT_CONFIG;
