  if(DD3.raf){cancelAnimationFrame(DD3.raf);DD3.raf=0;}
  DD3.el=null;DD3.rk='';
  if(DD3.fr){DD3.fr.style.visibility='hidden';DD3.fr.style.left='-4000px';}
