function dd3Suono(k,f){
  try{
    if(typeof SL2!=='undefined'&&SL2&&SL2.soundsEnabled===false)return;
    var c=(typeof slv2EnsureAudio==='function')?slv2EnsureAudio():null;if(!c)return;
    if(c.state==='suspended'){try{c.resume();}catch(e){}}
    var dst=(typeof slv2AudioDest==='function')?slv2AudioDest():c.destination,t=c.currentTime+0.005;
    f=Math.max(0.05,Math.min(1,f||0.5));
    if(!DD3.buf||DD3.buf.sampleRate!==c.sampleRate){var n=Math.floor(c.sampleRate*0.5),b=c.createBuffer(1,n,c.sampleRate),d=b.getChannelData(0);for(var i=0;i<n;i++)d[i]=Math.random()*2-1;DD3.buf=b;}
    var rumore=function(dur,tipo,fr,q,g,fr2){var s=c.createBufferSource();s.buffer=DD3.buf;var bq=c.createBiquadFilter();bq.type=tipo;bq.frequency.setValueAtTime(fr,t);if(fr2)bq.frequency.exponentialRampToValueAtTime(fr2,t+dur);bq.Q.value=q||1;var gg=c.createGain();gg.gain.setValueAtTime(g,t);gg.gain.exponentialRampToValueAtTime(0.0001,t+dur);s.connect(bq);bq.connect(gg);gg.connect(dst);s.start(t,Math.random()*0.3);s.stop(t+dur+0.02);};
    var tono=function(dur,tipo,fr,fr2,g,at){var o=c.createOscillator();o.type=tipo;var t0=t+(at||0);o.frequency.setValueAtTime(fr,t0);if(fr2)o.frequency.exponentialRampToValueAtTime(fr2,t0+dur);var gg=c.createGain();gg.gain.setValueAtTime(0.0001,t0);gg.gain.exponentialRampToValueAtTime(g,t0+0.004);gg.gain.exponentialRampToValueAtTime(0.0001,t0+dur);o.connect(gg);gg.connect(dst);o.start(t0);o.stop(t0+dur+0.02);};
    if(k==='bussolotto'){rumore(0.025,'bandpass',2600+Math.random()*1400,3,0.05*f);rumore(0.05,'bandpass',650,5,0.035*f);}
    else if(k==='versa'){rumore(0.28,'bandpass',700,1.2,0.10,2600);}
    else if(k==='panno'){rumore(0.05,'lowpass',520,0.7,0.30*f);tono(0.07,'sine',150,70,0.22*f);}
    else if(k==='sponda'){tono(0.06,'triangle',540,360,0.16*f);rumore(0.025,'bandpass',1900,2,0.12*f);}
    else if(k==='dado'){tono(0.03,'square',2300,1900,0.05*f);rumore(0.02,'highpass',3200,0.7,0.14*f);}
    else if(k==='fermo'){tono(0.05,'sine',260,180,0.10);}
    else if(k==='lento'){tono(0.45,'sine',96,48,0.28);rumore(0.5,'lowpass',300,0.8,0.07,90);}
    else if(k==='vince'){[880,1175,1568,2093].forEach(function(fq,i){tono(0.22,'triangle',fq,0,0.09,i*0.055);});}
  }catch(e){}
}
