function dcRoll(){
  if(!DC.pick){toast('Pick a bet first','warn');return;}
  var bet=currentBet.dice;
  if(!hasFunds(bet)){toast('Insufficient balance','err');return;}
  if(!S.userId){toast('Open in Telegram to play','err');return;}
  var btn=document.getElementById('dc-roll');
  btn.disabled=true;
  gSound('chip');
  gSound('dice-roll',{duration:1300});
  S.btc=Math.max(0,S.btc-eurToBtc(bet)); refresh();
  var d1=document.getElementById('dc-d1'),d2=document.getElementById('dc-d2');
  var totalEl=document.getElementById('dc-total');
  var statusEl=document.getElementById('dc-status');
  d1.classList.add('rolling');d2.classList.add('rolling');
  var _dd3=(typeof dd3Casino==='function')?dd3Casino():null;
  if(_dd3)setTimeout(function(){minDone=true;tryReveal();},450);
  d1.classList.remove('landed');d2.classList.remove('landed');
  statusEl.textContent=window.CDC?CDC.L('Si tira…','Rolling…'):'Rolling...';if(window.CDC)CDC.via();
  totalEl.className='dc-total-val';
  totalEl.textContent='...';
  var spin=setInterval(function(){
    d1.setAttribute('data-face',Math.floor(Math.random()*6)+1);
    d2.setAttribute('data-face',Math.floor(Math.random()*6)+1);
  },90);
  var resp=null, respErr=null, minDone=false;
  function tryReveal(){
    if(!minDone) return;
    if(resp===null && respErr===null) return;
    clearInterval(spin);
    d1.classList.remove('rolling');d2.classList.remove('rolling');
    if(respErr || !resp || resp.error){
      if(_dd3){try{_dd3.annulla();}catch(_da){}}
      statusEl.textContent='⚠️ '+((resp&&resp.error)||'Network error - retry');
      totalEl.textContent='-';
      btn.disabled=false;
      if(typeof loadBalance==='function') loadBalance();
      return;
    }
    var r1=resp.d1, r2=resp.d2, sum=resp.sum;
    if(_dd3&&!_dd3.finito){
      if(!_dd3.via){_dd3.via=1;if(!_dd3.esito([r1,r2],function(){_dd3.finito=1;tryReveal();},!!resp.won,resp.mult))_dd3.finito=1;}
      if(!_dd3.finito)return;
    }
    d1.setAttribute('data-face',r1); d2.setAttribute('data-face',r2);
    d1.classList.add('landed'); d2.classList.add('landed');
    gSound('dice-stop'); hapGioco('colpo');
    setTimeout(function(){d1.classList.remove('landed');d2.classList.remove('landed');},420);
    totalEl.textContent=sum;
    if(resp.btc!==undefined) S.btc=saldoDa(resp);
    if(resp.wins!==undefined) S.wins=resp.wins;
    if(resp.losses!==undefined) S.losses=resp.losses;
    if(resp.total_bet_eur!==undefined) S.totalBet=resp.total_bet_eur;
    if(resp.biggest_win_eur!==undefined) S.biggestWin=resp.biggest_win_eur;
    refresh();
    if(CUR==='profile') renderProfile();
    if(resp.won){
      var winEur=(resp.payout_btc*S.rate);
      totalEl.classList.add('win');
      statusEl.textContent='🎉 You won €'+winEur.toFixed(2)+'! ('+sum+')';
      setTimeout(function(){ if(resp.mult>=5) gSound('win-big'); else gSound('win-medium'); },200);
    } else {
      totalEl.classList.add('lose');
      statusEl.textContent='😞 Lost '+betLbl(bet)+' ('+sum+')';
      setTimeout(function(){ gSound('lose'); },200);
    }
    if(window.CDC){try{CDC.fine(resp,bet);}catch(_c){}}
    btn.disabled=false;
  }
  setTimeout(function(){ minDone=true; tryReveal(); }, 1100);
  fetch(BACKEND+'/play/dice',{
    method:'POST',
    headers:{'Content-Type':'application/json','ngrok-skip-browser-warning':'1'},
    body:JSON.stringify({user_id:S.userId, ...postaCent(bet), pick:DC.pick})
  }).then(function(r){return r.json();})
    .then(function(d){ resp=d; tryReveal(); })
    .catch(function(e){ respErr=e||true; tryReveal(); });
}
var SC_SYMS=[
  {icon:'💎',mult:3,   w:1},
  {icon:'💰',mult:1.5, w:1},
  {icon:'⭐',mult:0.7, w:2},
  {icon:'🃏',mult:0.3, w:3},
  {icon:'💵',mult:0.1, w:4},
  {icon:'💣',mult:0,   w:5}
];
var SCR={cells:{},revealed:[],bet:2,won:0,active:false,busy:false,exploded:null};
