function scBoomAnim(idx){
  setTimeout(function(){
    var grid=document.getElementById('sc-grid');
    if(!grid)return;
    var cells=grid.querySelectorAll('.sc-cell-v2');
    var exploded=cells[idx];
    if(exploded){
      exploded.classList.add('exploded');
      var emojis=['💥','🔥','✨','⚡','💥','🔥','✨','⚡','💥','🔥','✨','⚡'];
      for(var i=0;i<12;i++){
        var p=document.createElement('div');
        p.className='bomb-particle';
        p.textContent=emojis[i];
        var angle=(i/12)*Math.PI*2 + (Math.random()*.5-.25);
        var dist=70+Math.random()*40;
        p.style.setProperty('--tx',Math.cos(angle)*dist+'px');
        p.style.setProperty('--ty',Math.sin(angle)*dist+'px');
        p.style.animationDelay=(i*0.015)+'s';
        p.style.fontSize=(14+Math.random()*8)+'px';
        exploded.appendChild(p);
        setTimeout((function(_p){return function(){if(_p.parentNode)_p.parentNode.removeChild(_p);};})(p),1100+i*15);
      }
    }
    grid.classList.add('board-shake');
    setTimeout(function(){grid.classList.remove('board-shake');},520);
  },50);
}
function renderScratch(){
  var g=document.getElementById('sc-grid');
  if(!g)return;
  if(!SCR.active && SCR.revealed.length===0){
    g.innerHTML='<div style="grid-column:1/-1;text-align:center;padding:30px;color:var(--txt3);font-size:11px;">Press NEW CARD to start scratching!</div>';
    return;
  }
  g.innerHTML='';
  for(var _idx=0; _idx<16; _idx++){
    (function(idx){
      var has=(idx in SCR.cells);
      var s=has?SC_SYMS[SCR.cells[idx]]:null;
      var bomb=has && s.mult===0;
      var cell=document.createElement('div');
      cell.className='sc-cell-v2'+(has?(bomb?' rev bomb':' rev win'):'');
      cell.innerHTML='<div class="sc-cover">★<span class="sc-cover-mini">TREASURE</span></div>'+
        '<div class="sc-face">'+(has?
          '<div class="sc-face-icon">'+s.icon+'</div><div class="sc-face-mult">'+(bomb?'BOOM':'x'+s.mult)+'</div>'
          :'')+'</div>';
      if(!has){
        cell.onclick=function(){
          if(!SCR.active||SCR.busy||(idx in SCR.cells))return;
          cell.classList.add('flipping');
          setTimeout(function(){scReveal(idx);},220);
        };
      }
      g.appendChild(cell);
    })(_idx);
  }
}
