function scReveal(idx){
  if(!SCR.active||SCR.busy||(idx in SCR.cells))return;
  SCR.busy=true;
  gSound('scratch'); hapGioco('leggero');
  fetch(BACKEND+'/scratch/reveal',{
    method:'POST',headers:{'Content-Type':'application/json','ngrok-skip-browser-warning':'1'},
    body:JSON.stringify({user_id:S.userId,cell:idx})
  }).then(function(r){return r.json();}).then(function(d){
    SCR.busy=false;
    if(!d||d.error){toast('⚠️ '+((d&&d.error)||'error'),'err');return;}
    SCR.revealed.push(idx);
    SCR.cells[idx]=d.sym;
    if(d.bomb){
      SCR.active=false;SCR.exploded=idx;
      if(d.board){for(var i=0;i<d.board.length;i++){SCR.cells[i]=d.board[i];}}
      if(d.btc!==undefined)S.btc=saldoDa(d);
      if(d.losses!==undefined)S.losses=d.losses;
      refresh();if(CUR==='profile')renderProfile();
      renderScratch();
      gSound('explosion');
      scBoomAnim(idx);
      document.getElementById('sc-status').textContent='💣 BOOM! You lost!';
      document.getElementById('sc-cashout').style.display='none';
      document.getElementById('sc-new').style.display='';
      toast('💣 BOOM! Lost '+betLbl(SCR.bet),'err');
      return;
    }
    setTimeout(function(){ gSound('match'); }, 140);
    if(d.won_eur!==undefined)SCR.won=d.won_eur;
    document.getElementById('sc-win').textContent='€'+SCR.won.toFixed(2);
    renderScratch();
    if(d.perfect){
      SCR.active=false;
      if(d.btc!==undefined)S.btc=saldoDa(d);
      if(d.wins!==undefined)S.wins=d.wins;
      if(d.biggest_win_eur!==undefined)S.biggestWin=d.biggest_win_eur;
      refresh();if(CUR==='profile')renderProfile();
      document.getElementById('sc-win').textContent='€'+SCR.won.toFixed(2);
      document.getElementById('sc-status').textContent='🎉 PERFECT CLEAR! 2x bonus!';
      gSound('win-big');
      setTimeout(function(){gSound('cashout');},220);
      toast('💰 Won €'+SCR.won.toFixed(2),'ok');
      document.getElementById('sc-cashout').style.display='none';
      document.getElementById('sc-new').style.display='';
    }
  }).catch(function(e){SCR.busy=false;toast('Network error','err');});
}
