function crAction(){
  if(CR.state==='betting'){
    var bet=currentBet.crash;
    if(!hasFunds(bet)){toast('Insufficient balance','err');return;}
    if(!S.userId){toast('Open in Telegram to play','err');return;}
    if(CR._starting)return; CR._starting=true;
    var _b0=document.getElementById('cr-btn'); if(_b0)_b0.disabled=true;
    fetch(BACKEND+'/crash/start',{method:'POST',headers:{'Content-Type':'application/json','ngrok-skip-browser-warning':'1'},body:JSON.stringify({user_id:S.userId,...postaCent(bet)})})
      .then(function(r){return r.json();}).then(function(d){
        CR._starting=false; if(_b0)_b0.disabled=false;
        if(!d||d.error){toast('⚠️ '+((d&&d.error)||'error'),'err');if(typeof loadBalance==='function')loadBalance();return;}
        CR.bet=bet;CR.hasBet=true;CR.srvActive=true;CR.crashAt=0;CR.srvStartMs=d.start_ms;CR.lastPoll=0;
        if(d.btc!==undefined)S.btc=saldoDa(d); refresh();
        gSound('chip');
        setTimeout(function(){ gSound('rocket-launch'); }, 100);
        CR.startTime=performance.now();
        CR.state='flying';
        CR._lastTonePlayed = 0;
        document.getElementById('cr-status').textContent='✈️ FLYING — cash out!';
        document.getElementById('cr-btn').textContent='💰 CASHOUT @ 1.00x';
        document.getElementById('cr-btn').style.background='linear-gradient(135deg,var(--gold),var(--gold2))';
        document.getElementById('cr-btn').style.color='#000';
        if(CR.raf)cancelAnimationFrame(CR.raf);
        CR.raf=requestAnimationFrame(crAnimate);
      }).catch(function(e){CR._starting=false;if(_b0)_b0.disabled=false;toast('Network error','err');if(typeof loadBalance==='function')loadBalance();});
  }else if(CR.state==='flying'){
    crCashout();
  }
}
function crCashout(){
  if(CR.state!=='flying'||!CR.hasBet||!CR.srvActive)return;
  hapGioco('colpo');
  CR.srvActive=false;
  if(CR.raf){cancelAnimationFrame(CR.raf);CR.raf=null;}
  fetch(BACKEND+'/crash/cashout',{method:'POST',headers:{'Content-Type':'application/json','ngrok-skip-browser-warning':'1'},body:JSON.stringify({user_id:S.userId})})
    .then(function(r){return r.json();}).then(function(d){
      if(!d||d.error){toast('⚠️ '+((d&&d.error)||'error'),'err');if(typeof loadBalance==='function')loadBalance();setTimeout(crStartBetting,2000);return;}
      if(d.crashed){ crDoCrash(d.crashAt, d.btc, d.losses); return; }
      var mult=d.mult, won=(d.won_eur!==undefined)?d.won_eur:(CR.bet*mult);
      CR.mult=mult; CR.crashAt=d.crashAt||mult;
      CR.history.unshift({mult:mult,crashed:false}); CR.history=CR.history.slice(0,10);
      if(d.btc!==undefined)S.btc=saldoDa(d); if(d.wins!==undefined)S.wins=d.wins; if(d.biggest_win_eur!==undefined)S.biggestWin=d.biggest_win_eur;
      refresh(); if(CUR==='profile')renderProfile();
      gSound('cashout');
      setTimeout(function(){ if(mult>=5)gSound('win-big'); else if(mult>=2)gSound('win-medium'); else gSound('win-small'); }, 250);
      toast('💰 Cashed out @ '+mult.toFixed(2)+'x! +€'+won.toFixed(2),'ok');
      CR.state='crashed';
      var btn=document.getElementById('cr-btn');
      if(btn){btn.textContent='Won €'+won.toFixed(2)+' — Next round...';btn.disabled=true;}
      crRenderHist();
      setTimeout(crStartBetting,2500);
    }).catch(function(e){toast('Network error','err');if(typeof loadBalance==='function')loadBalance();setTimeout(crStartBetting,2500);});
}
function crPoll(){
  if(CR.state!=='flying'||!CR.srvActive)return;
  fetch(BACKEND+'/crash/state',{method:'POST',headers:{'Content-Type':'application/json','ngrok-skip-browser-warning':'1'},body:JSON.stringify({user_id:S.userId})})
    .then(function(r){return r.json();}).then(function(d){
      if(!d||d.error)return;
      if(d.crashed && CR.state==='flying'){ crDoCrash(d.crashAt, d.btc, d.losses); }
    }).catch(function(e){});
}
function crDoCrash(crashAt, btc, losses){
  if(CR.state!=='flying')return;
  CR.srvActive=false;
  if(CR.raf){cancelAnimationFrame(CR.raf);CR.raf=null;}
  CR.mult=crashAt||CR.mult; CR.crashAt=crashAt||CR.mult; CR.state='crashed';
  gSound('explosion');
  document.getElementById('cr-mult').innerHTML=CR.mult.toFixed(2)+'x 💥';
  document.getElementById('cr-mult').classList.add('crashed');
  document.getElementById('cr-status').textContent='CRASHED at '+CR.mult.toFixed(2)+'x';
  CR.history.unshift({mult:CR.mult,crashed:true}); CR.history=CR.history.slice(0,10);
  if(CR.hasBet){
    if(btc!==undefined)S.btc=btc; if(losses!==undefined)S.losses=losses; refresh();
    setTimeout(function(){ gSound('lose'); }, 500);
    toast('💥 Crashed! −'+betLbl(CR.bet),'err');
  }
  var btn=document.getElementById('cr-btn');
  if(btn){btn.textContent='💥 Crashed — Next round...';btn.disabled=true;btn.style.background='rgba(239,68,68,.2)';}
  crRenderHist(); crDrawCanvas();
  setTimeout(crStartBetting,2500);
}
function crAnimate(){
  if(CR.state!=='flying')return;
  var elapsed=(performance.now()-CR.startTime)/1000;
  CR.mult=Math.pow(Math.E,0.28*elapsed);
  var nowTs = performance.now();
  if(nowTs - (CR._lastTonePlayed||0) > 180){
    CR._lastTonePlayed = nowTs;
    var pitch = 220 * Math.pow(1.06, Math.min(40, Math.floor(CR.mult * 4)));
    gSound('rocket-rising', {freq: pitch});
  }
  if(CR.auto>0&&CR.hasBet&&CR.mult>=CR.auto){crCashout();return;}
  var _pn=performance.now();
  if(CR.srvActive && _pn-(CR.lastPoll||0)>300){ CR.lastPoll=_pn; crPoll(); }
  if(false){
    if(CR.raf){cancelAnimationFrame(CR.raf);CR.raf=null;}
    CR.mult=CR.crashAt;CR.state='crashed';
    gSound('explosion');
    document.getElementById('cr-mult').innerHTML=CR.mult.toFixed(2)+'x 💥';
    document.getElementById('cr-mult').classList.add('crashed');
    document.getElementById('cr-status').textContent='CRASHED at '+CR.mult.toFixed(2)+'x';
    CR.history.unshift({mult:CR.mult,crashed:true});
    CR.history=CR.history.slice(0,10);
    if(CR.hasBet){
      loseBet(CR.bet,'crash');
      setTimeout(function(){ gSound('lose'); }, 500);
      toast('💥 Crashed! −'+betLbl(CR.bet),'err');
    }
    var btn=document.getElementById('cr-btn');
    if(btn){btn.textContent='💥 Crashed — Next round...';btn.disabled=true;btn.style.background='rgba(239,68,68,.2)';}
    crRenderHist();crDrawCanvas();
    setTimeout(crStartBetting,2500);
    return;
  }
  document.getElementById('cr-mult').innerHTML=CR.mult.toFixed(2)+'<span style="font-size:24px;">x</span>';
  var btn=document.getElementById('cr-btn');
  if(btn&&CR.hasBet)btn.textContent='💰 CASHOUT @ '+CR.mult.toFixed(2)+'x';
  crDrawCanvas();
  CR.raf=requestAnimationFrame(crAnimate);
}
function crSetAuto(v){
  CR.auto=v;
  document.getElementById('cr-auto-lbl').textContent=v?v+'x':'OFF';
}
function crDrawCanvas(){
  var cv=document.getElementById('crash-canvas');
  if(!cv)return;
  var ctx=cv.getContext('2d');
  var W=cv.width,H=cv.height;
  ctx.clearRect(0,0,W,H);
  ctx.strokeStyle='rgba(255,255,255,.04)';ctx.lineWidth=1;
  for(var x=0;x<W;x+=40){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke();}
  for(var y=0;y<H;y+=40){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();}
  if(CR.state==='betting'||CR.state==='idle'){
    ctx.fillStyle='rgba(255,255,255,.15)';ctx.textAlign='center';
    ctx.font='14px Inter,sans-serif';
    ctx.fillText('🚀 Place your bet and fly!',W/2,H/2);
    ctx.font='11px Inter,sans-serif';ctx.fillStyle='rgba(255,255,255,.07)';
    ctx.fillText('Cash out before the crash',W/2,H/2+18);
    return;
  }
  var crashed=CR.state==='crashed';
  var elapsed=crashed?Math.log(CR.crashAt)/0.28:(performance.now()-CR.startTime)/1000;
  var maxT=Math.max(elapsed,1.5);
  var color=crashed?'#ef4444':'#39ff14';
  ctx.beginPath();ctx.moveTo(0,H);
  var steps=50;
  for(var s=0;s<=steps;s++){
    var t=(s/steps)*elapsed;
    var m=Math.pow(Math.E,0.28*t);
    var px=(t/maxT)*W*0.92+W*0.04;
    var py=H-Math.min((m-1)/(Math.pow(Math.E,0.28*elapsed)-1+0.001)*H*0.85,H-10);
    if(s===0)ctx.moveTo(px,py);else ctx.lineTo(px,py);
  }
  ctx.lineTo(W*0.96,H);ctx.closePath();
  var fill=ctx.createLinearGradient(0,0,0,H);
  fill.addColorStop(0,crashed?'rgba(239,68,68,.25)':'rgba(57,255,20,.2)');
  fill.addColorStop(1,'rgba(0,0,0,0)');
  ctx.fillStyle=fill;ctx.fill();
  ctx.strokeStyle=color;ctx.lineWidth=2.5;
  ctx.shadowColor=color;ctx.shadowBlur=10;
  ctx.beginPath();
  for(var s2=0;s2<=steps;s2++){
    var t2=(s2/steps)*elapsed,m2=Math.pow(Math.E,0.28*t2);
    var px2=(t2/maxT)*W*0.92+W*0.04;
    var py2=H-Math.min((m2-1)/(Math.pow(Math.E,0.28*elapsed)-1+0.001)*H*0.85,H-10);
    if(s2===0)ctx.moveTo(px2,py2);else ctx.lineTo(px2,py2);
  }
  ctx.stroke();ctx.shadowBlur=0;
  ctx.font='18px serif';ctx.textAlign='center';
  var tipT=elapsed;var tipM=Math.pow(Math.E,0.28*tipT);
  var tipX=W*0.96,tipY=H-Math.min((tipM-1)/(tipM-1+0.001)*H*0.85,H-10);
  ctx.fillText(crashed?'💥':'🚀',tipX,tipY-6);
}
function crRenderHist(){
  var h=document.getElementById('cr-hist');
  if(!h)return;
  h.innerHTML=CR.history.map(function(e){
    return'<span class="crash-hist-item '+(e.crashed?'loss':'win')+'">'+e.mult.toFixed(2)+'x</span>';
  }).join('')||'<span style="color:var(--txt3);font-size:10px;">No history yet</span>';
}
var LT={picks:[],jackpot:100,nextDraw:0,myTickets:0,cdTimer:null,tab:'play',myTicketList:[],history:[],
        maxNum:99,ticketEur:2};
function ltRicostruisciGriglia(){
  var nums=document.getElementById('lt-nums');
  if(!nums)return;
  var mx=LT.maxNum||49;
  if(nums.getAttribute('data-mx')===String(mx))return;
  nums.innerHTML='';
  for(var n=1;n<=mx;n++){
    var d=document.createElement('div');
    d.className='num';d.textContent=n;
    (function(num){d.onclick=function(){ltToggle(num);};})(n);
    if(LT.picks.indexOf(n)>=0)d.classList.add('sel');
    nums.appendChild(d);
  }
  nums.setAttribute('data-mx',String(mx));
}
function initLotto(){
  ltLoadInfo();
  ltRicostruisciGriglia();
  ltRenderPicks();
  ltUpdateCountdown();
  if(LT.cdTimer)clearInterval(LT.cdTimer);
  LT.cdTimer=setInterval(ltUpdateCountdown,30000);
}
var LT_FALLBACK={pz:{2:10,3:90,4:1200,5:24000},tick:2,jmin:30000,picks:6,maxn:99,
                 days:'Mon & Thu 20:00'};
function ltFillRules(d){
  d=d||{};
  var pz=(d.prizes_eur&&typeof d.prizes_eur==='object')?d.prizes_eur:LT_FALLBACK.pz;
  var tick=(+d.ticket_eur>0)?+d.ticket_eur:LT_FALLBACK.tick;
  var jmin=(+d.jackpot_min_eur>0)?+d.jackpot_min_eur:LT_FALLBACK.jmin;
  var pk=(+d.picks>0)?+d.picks:LT_FALLBACK.picks;
  var mx=(+d.max_num>0)?+d.max_num:LT_FALLBACK.maxn;
  var days=d.draw_days||LT_FALLBACK.days;
  var eur=function(v){return '€'+(+v).toLocaleString(undefined,{maximumFractionDigits:2});};
  [2,3,4,5].forEach(function(k){
    var el=document.getElementById('lt-pz-'+k);
    var v=pz[k]!==undefined?pz[k]:pz[String(k)];
    if(el&&v!==undefined)el.textContent=eur(v);
  });
  var b=document.getElementById('lt-buy-btn');
  if(b)b.textContent=(window.GB_LANG==='en'?'Buy ticket · ':'Compra biglietto · ')+eur(tick);
  var pick=document.getElementById('lt-pick-lbl');
  if(pick)pick.textContent=(window.GB_LANG==='en'?'Pick '+pk+' numbers (1-'+mx+')':'Scegli '+pk+' numeri (1-'+mx+')');
  LT.maxNum=mx; LT.picks=(LT.picks||[]).filter(function(n){return n<=mx;});
  if(typeof ltRicostruisciGriglia==='function')ltRicostruisciGriglia();
  if(typeof ltRenderPicks==='function')ltRenderPicks();
  var comb=1;for(var i=0;i<pk;i++)comb=comb*(mx-i)/(i+1);
  comb=Math.round(comb);
  var body=document.getElementById('lt-rules-body');
  if(body){
    if(window.GB_LANG!=='en'){ body.innerHTML='Scegli <b>'+pk+' numeri</b> da <b>1 a '+mx+'</b> e aspetta l’estrazione.'+'<br>Si estrae <b>'+(typeof d.next_draw==='string'&&d.next_draw?d.next_draw:days)+'</b>: un biglietto costa <b>'+eur(tick)+'</b>.'+'<br>Indovinane <b>2 o più</b> e vinci: anche con 2 riprendi il biglietto.'+'<br>Indovinali tutti e '+pk+' e prendi <b>tutto il jackpot</b>, mai meno di <b>'+eur(jmin)+'</b>: cresce a ogni biglietto venduto finché qualcuno non lo vince.'+'<span class="lt-odds">Probabilità del jackpot: 1 su '+comb.toLocaleString('it-IT')+'. I premi vanno direttamente nel tuo saldo.</span>'; }
    else body.innerHTML=
      'Pick <b>'+pk+' numbers</b> from <b>1 to '+mx+'</b>, then wait for the draw.'
      +'<br>Draws run <b>'+days+'</b> — one ticket costs <b>'+eur(tick)+'</b>.'
      +'<br>Match <b>2 or more</b> and you win: even 2 gives your ticket back.'
      +'<br>Match all '+pk+' and you take the <b>whole jackpot</b>, never less'
      +' than <b>'+eur(jmin)+'</b> — it grows with every ticket sold until'
      +' somebody wins it.'
      +'<span class="lt-odds">Odds of the jackpot: 1 in '
      +comb.toLocaleString()+'. Prizes are paid in BTC at the rate of the'
      +' moment, straight into your balance.</span>';
  }
}
function ltLoadInfo(){
  if(!S.userId)return;
  fetch(BACKEND+'/lotto/info?user_id='+S.userId,{headers:{'ngrok-skip-browser-warning':'1'}})
    .then(function(r){return r.json();})
    .then(function(d){
      ltFillRules(d);
      if(d.jackpot_btc!==undefined){
        var jkpEur=Math.round(d.jackpot_btc*S.rate);
        var jmin=(+d.jackpot_min_eur>0)?Math.round(+d.jackpot_min_eur):LT_FALLBACK.jmin;
        if(jkpEur<jmin)jkpEur=jmin;
        LT.jackpot=jkpEur;
        var jkpEl=document.getElementById('lt-jackpot');
        if(jkpEl)jkpEl.textContent='€'+LT.jackpot.toLocaleString();
        var jkpTab=document.getElementById('lt-jkp-table');
        if(jkpTab)jkpTab.textContent='€'+LT.jackpot.toLocaleString();
        var jkpHome=document.getElementById('home-lotto-jkp');
        if(jkpHome)jkpHome.textContent='€'+LT.jackpot.toLocaleString();
      }
      if(d.user_tickets!==undefined){
        LT.myTickets=d.user_tickets;
        var c=document.getElementById('lt-my-count');
        if(c)c.textContent=LT.myTickets;
        var s=document.getElementById('lt-my-spent');
        var _tk=(+d.ticket_eur>0)?+d.ticket_eur:2;
        if(s)s.textContent='€'+(LT.myTickets*_tk).toLocaleString(undefined,{maximumFractionDigits:2});
      }
      if(d.user_ticket_list){LT.myTicketList=d.user_ticket_list;ltRenderMyTickets();}
      if(d.history){LT.history=d.history;ltRenderHistory();}
      if(d.next_draw_ts){LT.nextDraw=d.next_draw_ts*1000;}
    }).catch(function(){});
}
function ltSwitchTab(t){
  LT.tab=t;
  document.getElementById('lt-tab-play').classList.toggle('on',t==='play');
  document.getElementById('lt-tab-mine').classList.toggle('on',t==='mine');
  document.getElementById('lt-tab-history').classList.toggle('on',t==='history');
  document.getElementById('lt-pane-play').style.display=t==='play'?'':'none';
  document.getElementById('lt-pane-mine').style.display=t==='mine'?'':'none';
  document.getElementById('lt-pane-history').style.display=t==='history'?'':'none';
  if(t==='mine'||t==='history')ltLoadInfo();
}
function ltRenderMyTickets(){
  var c=document.getElementById('lt-my-list');
  if(!c)return;
  if(!LT.myTicketList||!LT.myTicketList.length){
    c.innerHTML='<div class="lt-empty">'+(window.GB_LANG==='en'?'No tickets yet: pick 6 numbers in Play':'Ancora nessun biglietto: scegli 6 numeri in Gioca')+'</div>';
    return;
  }
  c.innerHTML=LT.myTicketList.map(function(t,i){
    var nums=(t.numbers||[]).sort(function(a,b){return a-b;});
    var date=t.ts?new Date(t.ts*1000):null;
    var dateStr=date?(date.getDate()+'/'+(date.getMonth()+1)+' '+
      String(date.getHours()).padStart(2,'0')+':'+String(date.getMinutes()).padStart(2,'0')):'';
    return '<div class="lt-ticket">'+
      '<div class="lt-ticket-hdr"><span class="lt-ticket-id">'+(window.GB_LANG==='en'?'Ticket #':'Biglietto #')+(i+1)+'</span><span class="lt-ticket-ts">'+dateStr+'</span></div>'+
      '<div class="lt-ticket-nums">'+nums.map(function(n){return '<div class="lt-ticket-num">'+n+'</div>';}).join('')+'</div>'+
      '</div>';
  }).join('');
}
function ltRenderHistory(){
  var c=document.getElementById('lt-history-list');
  if(!c)return;
  if(!LT.history||!LT.history.length){
    c.innerHTML='<div class="lt-empty">'+(window.GB_LANG==='en'?'No draws yet':'Ancora nessuna estrazione')+'</div>';
    return;
  }
  c.innerHTML=LT.history.slice().reverse().map(function(d){
    var nums=(d.numbers||[]).sort(function(a,b){return a-b;});
    var date=d.ts?new Date(d.ts*1000):null;
    var dateStr=date?(date.getDate()+'/'+(date.getMonth()+1)+'/'+date.getFullYear()):'Draw';
    var jkpStr=d.jackpot_btc?('€'+Math.round(d.jackpot_btc*S.rate).toLocaleString()):'';
    return '<div class="lt-history-entry">'+
      '<div class="lt-h-date"><span>'+dateStr+'</span><span class="lt-h-jkp">'+(d.winner?(jkpStr):(window.GB_LANG==='en'?'No winner · rolled over':'Nessun vincitore · jackpot rinviato'))+'</span></div>'+
      '<div class="lt-h-nums">'+nums.map(function(n){return '<div class="lt-h-num">'+n+'</div>';}).join('')+'</div>'+
      '</div>';
  }).join('');
}
function ltUpdateCountdown(){
  var next=LT.nextDraw;
  if(!next){
    var d=new Date();
    d.setHours(20,0,0,0);
    while(d.getDay()!==2&&d.getDay()!==5)d.setDate(d.getDate()+1);
    if(d.getTime()<Date.now())d.setDate(d.getDate()+1);
    next=d.getTime();
  }
  var diff=Math.max(0,Math.floor((next-Date.now())/1000));
  var dd=Math.floor(diff/86400),hh=Math.floor((diff%86400)/3600),mm=Math.floor((diff%3600)/60);
  var dEl=document.getElementById('cd-d'),hEl=document.getElementById('cd-h'),mEl=document.getElementById('cd-m');
  if(dEl)dEl.textContent=String(dd).padStart(2,'0');
  if(hEl)hEl.textContent=String(hh).padStart(2,'0');
  if(mEl)mEl.textContent=String(mm).padStart(2,'0');
}
function ltToggle(n){
  var i=LT.picks.indexOf(n);
  if(i>=0)LT.picks.splice(i,1);
  else if(LT.picks.length<6)LT.picks.push(n);
  else{toast('Max 6 numbers','warn');return;}
  gSound('tick');
  document.querySelectorAll('#lt-nums .num').forEach(function(el,idx){
    el.classList.toggle('sel',LT.picks.indexOf(idx+1)>=0);
  });
  ltRenderPicks();
}
function ltRandom(){
  LT.picks=[];
  while(LT.picks.length<6){
    var n=Math.floor(Math.random()*90)+1;
    if(LT.picks.indexOf(n)<0)LT.picks.push(n);
  }
  for(var i = 0; i < 6; i++) (function(idx){
    setTimeout(function(){ gSound('tick'); }, idx * 70);
  })(i);
  document.querySelectorAll('#lt-nums .num').forEach(function(el,idx){
    el.classList.toggle('sel',LT.picks.indexOf(idx+1)>=0);
  });
  ltRenderPicks();
}
function ltClear(){
  LT.picks=[];
  gSound('click');
  document.querySelectorAll('#lt-nums .num').forEach(function(el){el.classList.remove('sel');});
  ltRenderPicks();
}
function ltRenderPicks(){
  var p=document.getElementById('lt-picks');p.innerHTML='';
  var sorted=LT.picks.slice().sort(function(a,b){return a-b;});
  for(var i=0;i<6;i++){
    var d=document.createElement('div');
    if(sorted[i]){d.className='pick-ball';d.textContent=sorted[i];}
    else{d.className='pick-empty';}
    p.appendChild(d);
  }
}
function ltBuy(){
  if(LT.picks.length<6){toast(window.GB_LANG==='en'?'Pick 6 numbers first':'Scegli prima 6 numeri','warn');return;}
  if(!hasFunds(10)){toast('Need €10 to buy ticket','err');return;}
  if(!S.userId){toast('Open in Telegram to buy','err');return;}
  var picks=LT.picks.slice();
  fetch(BACKEND+'/lotto/ticket',{
    method:'POST',
    headers:{'Content-Type':'application/json','ngrok-skip-browser-warning':'1'},
    body:JSON.stringify({user_id:S.userId,numbers:picks})
  }).then(function(r){return r.json();}).then(function(d){
    if(d.ok){
      gSound('ticket');
      try{ if(window.XK&&XK.bigliettoOk)XK.bigliettoOk(picks); }catch(_xk){}
      toast(window.GB_LANG==='en'?'Ticket bought, good luck':'Biglietto comprato, buona fortuna','ok',3000);
      LT.picks=[];
      LT.myTickets=(d.my_tickets!==undefined?d.my_tickets:LT.myTickets+1);
      loadBalance();
      initLotto();
    }else{
      gSound('lose');
      try{ if(window.XK&&XK.bigliettoKo)XK.bigliettoKo(); }catch(_xk){}
      toast('❌ '+(d.error||'Failed'),'err');
    }
  }).catch(function(){toast('Network error','err');});
}
function renderWallet(){
  if(typeof wnRender==='function'){ try{ wnRender(); return; }catch(_wn){ console.error('wnRender', _wn); } }
  var tx=document.getElementById('w-tx');
  if(!S.txs||!S.txs.length){
    tx.innerHTML=gbEmpty('\uD83E\uDDFE','Ancora nessun movimento',
      'Qui compaiono i depositi, i prelievi e le vincite, dal piu recente.',
      '<button class="gb-btn gb-btn--primary" onclick="go(\'deposit\')">Fai un deposito</button>');
    return;
  }
  tx.innerHTML=S.txs.slice(0,20).map(function(t){
    var ts=t.ts||t.timestamp||0;
    var dateStr='';
    if(ts){
      var _dt=new Date(ts*1000), _oggi=new Date();
      var _hm=('0'+_dt.getHours()).slice(-2)+':'+('0'+_dt.getMinutes()).slice(-2);
      var _gg=('0'+_dt.getDate()).slice(-2)+'/'+('0'+(_dt.getMonth()+1)).slice(-2);
      if(_dt.toDateString()===_oggi.toDateString()) dateStr='Oggi \u00b7 '+_hm;
      else if(_dt.toDateString()===new Date(_oggi.getTime()-86400000).toDateString())
        dateStr='Ieri \u00b7 '+_hm;
      else dateStr=_gg+' \u00b7 '+_hm;
    }
    var rawAmt=t.amount||0;
    var amtEur;
    var unita=(t.unita||t.unit||'BTC').toUpperCase();
    if(unita==='EUR'){
      amtEur=rawAmt;
    }else if(unita==='TON'){
      amtEur=(t.eur!==undefined&&t.eur!==null)?(+t.eur):null;
    }else{
      amtEur=rawAmt*S.rate;
    }
    var _sg=TX_SEGNI[t.type]||0;
    var isPositive=(_sg>0), isNegative=(_sg<0);
    var label=TX_ETICHETTE[t.type]||(t.type||'Game');
    if(t.game && t.game!=='Deposito' && t.game!=='Prelievo' && t.game!=='game'){
      label += ' · '+(TX_GIOCHI[t.game]||t.game);
    }
    var testo;
    if(amtEur===null||amtEur===undefined||amtEur!==amtEur){
      testo=fmt(Math.abs(rawAmt),unita==='TON'?2:8)+' '+unita;
    }else{
      testo='€'+Math.abs(amtEur).toFixed(2);
    }
    var sign=isPositive?'+':(isNegative?'−':'');
    var cls=isPositive?'pos':(isNegative?'neg':'');
    if(t.gratis){testo='gratis';sign='';cls='';}
    var _sp=label.indexOf(' ');
    var _ico=_sp>0?label.slice(0,_sp):'\uD83C\uDFB2';
    var _lbl=_sp>0?label.slice(_sp+1):label;
    return '<div class="tx-item">'+
      '<div class="tx-ic">'+_ico+'</div>'+
      '<div class="tx-info"><div class="tx-type">'+_lbl+'</div>'+
      '<div class="tx-time">'+dateStr+'</div></div>'+
      '<div class="tx-amt '+cls+'">'+sign+testo+'</div></div>';
  }).join('');
}
