var SWAP={coins:[],loaded:false,sel:null,estTimer:null,pollTimer:null,curId:null};
function swapToggle(){
  var p=document.getElementById('swap-panel');
  if(!p)return;
  var opening=(p.style.display==='none'||!p.style.display);
  p.style.display=opening?'block':'none';
  if(opening && !SWAP.loaded) swapLoadCoins();
}
function swapApi(path,opts){
  opts=opts||{};
  var url=BACKEND+path;
  return fetch(url,opts).then(function(r){
    return r.text().then(function(t){
      var j={}; try{j=JSON.parse(t);}catch(e){}
      return {status:r.status,ok:r.ok,data:j};
    });
  });
}
function swapLoadCoins(){
  var sel=document.getElementById('swap-coin');
  swapApi('/swap/currencies?user_id='+encodeURIComponent(S.userId||'')).then(function(res){
    if(res.status===503){ swapShowOff(); return; }
    if(!res.ok || !res.data || !res.data.currencies){ sel.innerHTML='<option value="">Errore caricamento</option>'; return; }
    SWAP.coins=res.data.currencies; SWAP.loaded=true;
    sel.innerHTML='<option value="">— scegli una crypto —</option>'+SWAP.coins.map(function(c){
      return '<option value="'+c.id+'">'+(c.emoji||'')+' '+c.label+'</option>';
    }).join('');
  }).catch(function(){ sel.innerHTML='<option value="">Rete non disponibile</option>'; });
}
function swapShowOff(){
  var f=document.getElementById('swap-form'), off=document.getElementById('swap-off');
  if(f)f.style.display='none';
  if(off)off.style.display='block';
}
function swapSelected(){
  var id=document.getElementById('swap-coin').value;
  for(var i=0;i<SWAP.coins.length;i++){ if(SWAP.coins[i].id===id) return SWAP.coins[i]; }
  return null;
}
function swapCoinChanged(){
  SWAP.sel=swapSelected();
  document.getElementById('swap-min').textContent='';
  document.getElementById('swap-estimate').textContent='';
  swapAmountChanged();
}
function swapAmountChanged(){
  if(SWAP.estTimer)clearTimeout(SWAP.estTimer);
  var c=SWAP.sel; if(!c)return;
  var amt=parseFloat((document.getElementById('swap-amount').value||'').replace(',','.'));
  SWAP.estTimer=setTimeout(function(){ swapEstimate(c,isFinite(amt)?amt:0); },450);
}
function swapEstimate(c,amt){
  swapApi('/swap/estimate',{method:'POST',headers:{'Content-Type':'application/json'},
    body:JSON.stringify({user_id:S.userId,fromCurrency:c.ticker,fromNetwork:c.network,amount:amt})
  }).then(function(res){
    if(res.status===503){ swapShowOff(); return; }
    var d=res.data||{};
    var minEl=document.getElementById('swap-min'), estEl=document.getElementById('swap-estimate');
    var chipEl=document.getElementById('swap-chips');
    if(d.minAmount!=null){
      minEl.textContent='min: '+d.minAmount+' '+c.ticker.toUpperCase();
      SWAP.min=+d.minAmount||0;
      if(chipEl&&SWAP.min>0){
        var mk=function(mul,et){
          var v=+(SWAP.min*mul).toPrecision(4);
          return '<button class="twr-opt" style="flex:1;font-size:11px;" onclick="swapChip('+v+')">'+et+'</button>';
        };
        chipEl.innerHTML=mk(1,'minimo')+mk(2,'x2')+mk(5,'x5');
        chipEl.style.display='flex';
      }
    }
    else { minEl.textContent=''; if(chipEl)chipEl.style.display='none'; }
    if(amt>0 && d.estimatedBtc!=null){ estEl.textContent='≈ '+Number(d.estimatedBtc).toFixed(8)+' BTC'; }
    else if(amt>0 && d.warning){ estEl.textContent='⚠️ '+d.warning; }
    else { estEl.textContent=''; }
  }).catch(function(){});
}
function swapChip(v){
  var el=document.getElementById('swap-amount');
  if(!el)return;
  el.value=String(v);
  swapAmountChanged();
  try{TWS.play('pick',0.5);}catch(e){}
}
function swapCreate(){
  var c=SWAP.sel;
  if(!c){ toast('Scegli prima una crypto','warn'); return; }
  var amt=parseFloat((document.getElementById('swap-amount').value||'').replace(',','.'));
  if(!isFinite(amt)||amt<=0){ toast('Inserisci un importo valido','warn'); return; }
  var btn=document.getElementById('swap-go-btn');
  btn.disabled=true; btn.textContent='⏳ Creazione…';
  swapApi('/swap/create',{method:'POST',headers:{'Content-Type':'application/json'},
    body:JSON.stringify({user_id:S.userId,fromCurrency:c.ticker,fromNetwork:c.network,amount:amt})
  }).then(function(res){
    btn.disabled=false; btn.textContent='🔄 CONVERTI IN BTC';
    if(res.status===503){ swapShowOff(); return; }
    var d=res.data||{};
    if(!res.ok || !d.payinAddress){
      var smsg = d.error || 'Could not create the swap. Nothing was charged.';
      toast(smsg,'err'); return;
    }
    swapShowResult(c,d);
  }).catch(function(){
    btn.disabled=false; btn.textContent='🔄 CONVERTI IN BTC';
    toast('Rete non disponibile, riprova','err');
  });
}
function swapShowResult(c,d){
  document.getElementById('swap-form').style.display='none';
  document.getElementById('swap-result').style.display='block';
  document.getElementById('swap-r-amount').textContent=(d.fromAmount||'')+' '+c.ticker.toUpperCase();
  document.getElementById('swap-r-net-lbl').textContent='INDIRIZZO DI INVIO ('+c.label+')';
  document.getElementById('swap-r-payin').textContent=d.payinAddress||'';
  var memoBox=document.getElementById('swap-r-memo-box');
  if(d.payinExtraId){
    document.getElementById('swap-r-memo').textContent=d.payinExtraId;
    memoBox.style.display='block';
  } else { memoBox.style.display='none'; }
  var wBtn=document.getElementById('swap-r-wallet-btn');
  if(wBtn)wBtn.style.display=(c.ticker==='ton')?'block':'none';
  SWAP.curId=d.id;
  swapRenderSteps('waiting');
  if(d.id) swapStartPoll(d.id);
}
var SWAP_STEPS=['waiting','confirming','exchanging','sending','finished'];
var SWAP_STEP_LBL={waiting:'In attesa',confirming:'Conferma',exchanging:'Scambio',sending:'Invio',finished:'Completato'};
function swapRenderSteps(cur){
  var idx=SWAP_STEPS.indexOf(cur); if(idx<0)idx=0;
  document.getElementById('swap-steps').innerHTML=SWAP_STEPS.map(function(s,i){
    var on=(i<=idx);
    return '<span style="color:'+(on?'var(--gold)':'var(--txt3)')+';">'+(on?'●':'○')+' '+SWAP_STEP_LBL[s]+'</span>';
  }).join('');
}
function swapStartPoll(id){
  if(SWAP.pollTimer)clearInterval(SWAP.pollTimer);
  function poll(){
    if(SWAP.curId!==id){ clearInterval(SWAP.pollTimer); return; }
    swapApi('/swap/status?id='+encodeURIComponent(id)).then(function(res){
      var d=res.data||{}; var st=d.status||'waiting';
      var msg=document.getElementById('swap-status-msg');
      if(st==='failed'||st==='refunded'){
        msg.textContent=(st==='refunded'?'↩️ Rimborsato':'❌ Fallito')+' — nessun BTC accreditato';
        clearInterval(SWAP.pollTimer); return;
      }
      swapRenderSteps(st==='verifying'?'confirming':st);
      if(st==='finished'){
        msg.textContent='✅ Fatto! I BTC arriveranno nel tuo saldo dopo le conferme di rete.';
        clearInterval(SWAP.pollTimer);
      } else if(st==='sending'){
        msg.textContent='📤 BTC in invio verso il tuo indirizzo di deposito…';
      } else if(st==='exchanging'){
        msg.textContent='🔄 Conversione in corso…';
      } else if(st==='confirming'){
        msg.textContent='⛓️ Conferma della tua transazione…';
      } else {
        msg.textContent='In attesa del tuo invio…';
      }
    }).catch(function(){});
  }
  poll();
  SWAP.pollTimer=setInterval(poll,7000);
}
function swapReset(){
  if(SWAP.pollTimer)clearInterval(SWAP.pollTimer);
  SWAP.curId=null;
  document.getElementById('swap-result').style.display='none';
  document.getElementById('swap-form').style.display='block';
  document.getElementById('swap-amount').value='';
  document.getElementById('swap-estimate').textContent='';
  document.getElementById('swap-min').textContent='';
}
function swapCopy(elId){
  var el=document.getElementById(elId); if(!el)return;
  var txt=el.textContent||'';
  if(navigator.clipboard && txt){ navigator.clipboard.writeText(txt).then(function(){toast('📋 Copiato!','ok');}); }
}
function openBot(){
  try{
    if(tg.openTelegramLink){
      tg.openTelegramLink('https://t.me/Master_Gambler_bot?start=preleva');
      return;
    }
  }catch(e){}
  if(tg.close)try{tg.close();}catch(e){}
}
function gbEmpty(glifo, titolo, testo, azione){
  return '<div class="gb-empty">'+
    '<div class="gb-empty__ico">'+glifo+'</div>'+
    '<div class="gb-empty__ttl">'+titolo+'</div>'+
    '<div class="gb-empty__txt">'+testo+'</div>'+
    (azione||'')+
  '</div>';
}
function gbSkel(quanti, altezza){
  var h='';
  for(var i=0;i<quanti;i++) h+='<div class="gb-skel" style="height:'+altezza+'px"></div>';
  return '<div class="gb-skel-wrap">'+h+'</div>';
}
var GB_PODIO = '<div class="gb-podio"><div class="p2">\uD83E\uDD48</div>'+
               '<div class="p1">\uD83E\uDD47</div><div class="p3">\uD83E\uDD49</div></div>';
function loadLeaderboard(){
  var lb=document.getElementById('lb-list');
  if(!S.userId){
    lb.innerHTML=gbEmpty(GB_PODIO,'Apri in Telegram',
      'La classifica ha bisogno del tuo profilo Telegram. Apri il mini-app dal bot e il podio si riempie.');
    return;
  }
  fetch(BACKEND+'/leaderboard?user_id='+S.userId+'&limit=20',{headers:{'ngrok-skip-browser-warning':'1'}})
    .then(function(r){return r.json();})
    .then(function(d){
      var list=d.leaderboard||[];
      if(!list.length){lb.innerHTML=gbEmpty(GB_PODIO,'Podio libero',
        'Questa settimana non ha ancora giocato nessuno. La prima mano ti mette in cima.',
        '<button class="gb-btn gb-btn--primary" onclick="go(\'home\')">Gioca una mano</button>');return;}
      lb.innerHTML=list.map(function(p,i){
        var rankCls=i===0?'gold':i===1?'silv':i===2?'bron':'';
        var lvl=getLevel(p.xp||0);
        return'<div class="lb-item'+(p.is_me?' me':'')+'">'+
          '<div class="lb-rank '+rankCls+'">'+(i<3?['🥇','🥈','🥉'][i]:'#'+(i+1))+'</div>'+
          '<div class="lb-name">'+(p.is_me?'⭐ ':'')+dlEsc(p.name||'Player')+'<div class="lb-info">'+lvl.icon+' Lv.'+lvl.level+' '+lvl.title+' • '+(p.wins||0)+'W</div></div>'+
          '<div class="lb-val">'+lbEur(p)+'</div></div>';
      }).join('');
    })
    .catch(function(){lb.innerHTML=gbEmpty('\uD83D\uDCE1','Classifica non raggiungibile',
      'La rete non ha risposto. Nessun dato perso: e solo da ricaricare.',
      '<button class="gb-btn gb-btn--ghost" onclick="loadLeaderboard()">Riprova</button>');});
}
var CHALLENGES_ALL=[];
function fetchChallenges(cb){
  var lst=document.getElementById('ch-list');
  console.log('[QUESTS] fetchChallenges BUILD 20260514-1144 userId=', S.userId);
  if(!S.userId){
    if(lst)lst.innerHTML='<div class="q-err">'+qnT('Apri la mini app da Telegram per vedere le tue quest.','Open the mini app from Telegram to see your quests.')+'</div>';
    if(cb)cb();
    return;
  }
  if(lst && !CHALLENGES_ALL.length){
    lst.innerHTML=gbSkel(4,96);
  }
  function buildUrl(path){
    var sep = path.indexOf('?') >= 0 ? '&' : '?';
    return BACKEND + path + sep + 'ngrok-skip-browser-warning=true&_t=' + Date.now();
  }
  function tryFetchSimple(url){
    console.log('[QUESTS] simple fetch:', url);
    return new Promise(function(resolve){
      var timer=setTimeout(function(){resolve({ok:false, err:'timeout 8s', url:url});},8000);
      fetch(url,{cache:'no-store', mode:'cors', credentials:'omit'}).then(function(r){
        clearTimeout(timer);
        return r.text().then(function(t){
          try{resolve({ok:true, status:r.status, data:JSON.parse(t), url:url, raw:t.substring(0,400)});}
          catch(e){resolve({ok:false, status:r.status, err:'JSON parse fail', raw:t.substring(0,400), url:url});}
        });
      }).catch(function(e){
        clearTimeout(timer);
        resolve({ok:false, err:'fetch:'+(e.message||e), url:url});
      });
    });
  }
  function tryFetchWithHeader(url){
    console.log('[QUESTS] fetch+header:', url);
    return new Promise(function(resolve){
      var timer=setTimeout(function(){resolve({ok:false, err:'timeout 8s', url:url});},8000);
      fetch(url,{
        headers:{'ngrok-skip-browser-warning':'true'},
        cache:'no-store', mode:'cors', credentials:'omit'
      }).then(function(r){
        clearTimeout(timer);
        return r.text().then(function(t){
          try{resolve({ok:true, status:r.status, data:JSON.parse(t), url:url, raw:t.substring(0,400)});}
          catch(e){resolve({ok:false, status:r.status, err:'JSON parse fail', raw:t.substring(0,400), url:url});}
        });
      }).catch(function(e){
        clearTimeout(timer);
        resolve({ok:false, err:'fetch:'+(e.message||e), url:url});
      });
    });
  }
  function tryXHRSimple(url){
    console.log('[QUESTS] simple XHR:', url);
    return new Promise(function(resolve){
      try{
        var xhr=new XMLHttpRequest();
        xhr.open('GET', url, true);
        xhr.timeout=8000;
        xhr.ontimeout=function(){resolve({ok:false, err:'XHR timeout 8s', url:url});};
        xhr.onerror=function(){resolve({ok:false, err:'XHR network error', url:url});};
        xhr.onreadystatechange=function(){
          if(xhr.readyState===4){
            try{
              var d=JSON.parse(xhr.responseText);
              resolve({ok:true, status:xhr.status, data:d, url:url, raw:xhr.responseText.substring(0,400)});
            }catch(e){
              resolve({ok:false, status:xhr.status, err:'XHR JSON parse fail', raw:xhr.responseText.substring(0,400), url:url});
            }
          }
        };
        xhr.send();
      }catch(e){
        resolve({ok:false, err:'XHR setup fail:'+e.message, url:url});
      }
    });
  }
  function useResult(resp){
    var d=resp.data;
    if(d && d.challenges){
      CHALLENGES_ALL = d.challenges;
      console.log('[QUESTS] SUCCESS from', resp.url, '— count=', CHALLENGES_ALL.length);
      if(d.progress)S.weekProgress=d.progress;
      if(d.claimed)S.claimedQuests=d.claimed;
      if(d.week_earned_btc!==undefined)S.weekEarnedBtc=d.week_earned_btc;
      try{qnDati(d);if(_CH_TAB==='nuove')qnRender();}catch(e){}
      if(cb)cb();
      renderChallenges();
      return true;
    }
    return false;
  }
  var attempts = [
    function(){return tryFetchSimple(buildUrl('/quests_data?user_id='+S.userId));},
    function(){return tryFetchSimple(buildUrl('/challenges?user_id='+S.userId));},
    function(){return tryXHRSimple(buildUrl('/quests_data?user_id='+S.userId));},
    function(){return tryFetchWithHeader(buildUrl('/quests_data?user_id='+S.userId));},
  ];
  var errors=[];
  function runNext(i){
    if(i>=attempts.length){
      console.error('[QUESTS] ALL 4 attempts failed:', errors);
      var firstRaw='';
      for(var ei=0;ei<errors.length;ei++){
        if(errors[ei].raw){firstRaw=errors[ei].raw;break;}
      }
      var ngrokWarning = firstRaw && (firstRaw.indexOf('ngrok')>=0 || firstRaw.indexOf('You are about to visit')>=0 || firstRaw.indexOf('Visit Site')>=0);
      var attemptsList = errors.map(function(e,i){
        var label = e.url.replace(BACKEND,'').split('?')[0];
        return '<div style="margin:2px 0;">'+(i+1)+'. <strong>'+label+'</strong>: '+(e.err||'?')+(e.status?' (HTTP '+e.status+')':'')+'</div>';
      }).join('');
      var msg='<b>'+qnT('Non riesco a caricare le quest.','Could not load the quests.')+'</b><br><br>';
      msg+='<div style="text-align:left;font-size:10px;margin:6px 0;">'+attemptsList+'</div>';
      if(ngrokWarning){
        msg+='<br><strong style="color:#ff9900;">ngrok showing browser warning page</strong><br>';
        msg+='<small>Telegram WebView strips our bypass header. Solutions:</small><br>';
        msg+='<div style="text-align:left;font-size:9px;background:rgba(0,0,0,.4);padding:6px;margin:4px 0;border-radius:4px;">';
        msg+='\u2022 Switch backend tunnel to <strong>cloudflared</strong> (no warning page, free)<br>';
        msg+='\u2022 Upgrade ngrok to a paid plan<br>';
        msg+='\u2022 Deploy backend to a real domain';
        msg+='</div>';
      }
      if(firstRaw){
        msg+='<br><strong>Sample response:</strong><div style="text-align:left;font-size:9px;font-family:monospace;background:rgba(0,0,0,.5);padding:6px;border-radius:4px;max-height:140px;overflow:auto;word-break:break-all;color:#fff;">'+
          firstRaw.replace(/</g,'&lt;').replace(/>/g,'&gt;')+
          '</div>';
      }
      showQuestError(lst,msg);
      if(cb)cb();
      return;
    }
    attempts[i]().then(function(resp){
      if(resp.ok && useResult(resp))return;
      errors.push(resp);
      console.warn('[QUESTS] attempt',i+1,'failed:',resp.err||'no data','raw:',(resp.raw||'').substring(0,80));
      runNext(i+1);
    });
  }
  runNext(0);
}
function showQuestError(lst,htmlMsg){
  if(!lst)return;
  lst.innerHTML='<div class="q-err">'+htmlMsg+'<br>'+
    '<button class="q-cta" onclick="fetchChallenges(renderChallenges)">'+qIco('giro','q-ic-s')+qnT('RIPROVA','RETRY')+'</button>'+
    '</div>';
}
