          var f=document.createElement('canvas');f.width=176;f.height=160;
          f.getContext('2d').drawImage(src,src.width*.1,src.height*.13,src.width*.8,src.height*.8,0,0,f.width,f.height);
          var ch=cos3Chiave(mode,it.patch);if(ch)COS3.foto[ch]=f;
