function dlGameDur(m){ return (dlGameMeta[m]||{}).dur||'~6s'; }
function dlModalHTML(html){ var ov=document.getElementById('pvp-overlay'),m=document.getElementById('pvp-modal');
  var ci=m&&m.querySelector('.trn-ch-duel .trn-ch-in'),cv=null,cf=false,cs=0,ce=0;
  if(ci){cv=ci.value;cf=(document.activeElement===ci);try{cs=ci.selectionStart;ce=ci.selectionEnd;}catch(_e){}}
  if(m)m.innerHTML=html;
  if(ci&&m){var ni=m.querySelector('.trn-ch-duel .trn-ch-in');
    if(ni){ni.value=cv||'';if(cf){try{ni.focus({preventScroll:true});ni.setSelectionRange(cs,ce);}catch(_e){}}}}
  if(ov)ov.classList.add('show'); }
function dlCloseOverlay(){ dlStopPoll(); var ov=document.getElementById('pvp-overlay'); if(ov)ov.classList.remove('show'); }
function dlHand(h){ return (h||[]).map(function(c){ var red=(c.s==='♥'||c.s==='♦'); return '<span class="pvp-card'+(red?' red':'')+'">'+c.r+c.s+'</span>'; }).join(''); }
var dlPickSel={mode:'',stake:0};
function dlSetStake(mode,stake){
  dlPickSel.mode=mode; dlPickSel.stake=stake;
  document.querySelectorAll('#pvp-modal .tw-tier[data-t]').forEach(function(b){
    b.classList.toggle('sel', Number(b.getAttribute('data-t'))===stake);
  });
  try{ tg.HapticFeedback&&tg.HapticFeedback.impactOccurred('light'); }catch(e){}
}
function dlPickPlay(){
  if(!dlPickSel.mode||!dlPickSel.stake){ toast('Scegli una posta','warn'); return; }
  dlBetPick(dlPickSel.mode, dlPickSel.stake);
}
function dlPickGame(mode){
  if(!S.userId){ toast('Apri in Telegram per giocare','err'); return; }
  var meta=dlGameMeta[mode]||{};
  if(mode==='dice'||mode==='random'){try{dd3Precarica();}catch(_dd){}}
  var bets=TWR_TIERS.map(function(tk){ return Number(tk[0]); });
  var color=meta.color||'#ffd700';
  dlPickSel={mode:mode,stake:bets[0]};
  var h='<div class="tw-hero"><div class="tw-hero-t" style="color:'+color+';text-shadow:0 0 20px '+color+'66;">'+dlEsc(meta.hero||dlModeName(mode))+'</div>'
    +'<div class="tw-hero-live">⚡ LIVE 1v1</div>'
    +'<div class="tw-hero-s">'+dlEsc(meta.sub||'')+'</div></div>';
  h+='<div class="tw-rules">';
  if(meta.rules&&meta.rules.length){ meta.rules.forEach(function(r){ h+=twrRule(r[0],r[1],r[2]); }); }
  else { h+=twrRule('ℹ️','Come si gioca',meta.how||''); }
  h+='</div>';
  h+='<div class="section-ttl">💰 PUNTATA</div><div class="tw-tiers">';
  TWR_TIERS.forEach(function(tk){ var b=Number(tk[0]); h+='<button class="tw-tier'+(b===dlPickSel.stake?' sel':'')+'" data-t="'+b+'" onclick="dlSetStake(\''+mode+'\','+b+')">'+tk[1]+'</button>'; });
  h+='</div>';
  h+='<button class="action-btn gold" id="dl-play-btn" onclick="dlPickPlay()" style="width:100%;">▶ GIOCA</button>';
  if(typeof TRN_DUEL_PRATICA!=='undefined'&&TRN_DUEL_PRATICA[mode])
    h+='<button class="action-btn train-btn" onclick="dlCloseOverlay();practiceStart(\''+mode+'\')" style="width:100%;">🤖 ALLENATI · GRATIS vs BOT</button>';
  h+='<button class="action-btn" onclick="dlCloseOverlay();lobOpenCreate(\''+mode+'\',\'duel\')" style="width:100%;">📣 CREA LOBBY · INVITA IL GRUPPO</button>';
  h+='<div class="tw-note">1 contro 1 · si gioca sulla posta più bassa tra i due (l\'eccedenza è rimborsata) · rimborso se nessuno accetta</div>';
  h+='<button class="pvp-m-btn" onclick="dlCloseOverlay()" style="margin-top:8px;">ANNULLA</button>';
  dlModalHTML(h);
}
function dlBetPick(mode,eur){ if(mode==='bj'){ dlBjStart(eur); } else if(mode==='rr'){ dlRrStart(eur); } else if(mode==='rps'){ dlRpsStart(eur); } else if(mode==='cards'){ dlPkdStart(eur); } else if(mode==='bs'){ dlBsStart(eur); } else if(mode==='chess'){ dlChStart(eur); } else if(mode==='random'){ dlRndStart(eur); } else { dlStartMatch(mode,eur); } }
function dlSearchView(mode,eur){
  var ico=(mode==='random')?'🎡':((dlModeName(mode).split(' ')[0])||'⚔️');
  var pot=(Number(eur)||0)*2, win=pot*0.95;
  dlModalHTML(
    '<div class="tw-radar"><div class="twr-radar-sweep"></div>'+ico+'</div>'+
    '<div class="tw-search-t">IN CERCA DI SFIDANTI…</div>'+
    '<div class="twr-prize" id="dl-prize">💰 MONTEPREMI: <b>€'+pot.toFixed(2)+'</b><span>· al vincitore €'+win.toFixed(2)+' (95%)</span></div>'+
    '<div class="tw-search-cd">Rimborso automatico se nessuno accetta</div>'+
    '<button class="action-btn red" onclick="dlCancelSearch()" style="width:100%;">✖ ANNULLA (rimborso)</button>');
}
function dlStartMatch(mode,eur){
  if(capEur()<eur){ toast('Insufficient balance','err'); return; }
  dlSearchView(mode,eur);
  fetch(BACKEND+'/duel/app_join',{method:'POST',headers:{'Content-Type':'application/json','ngrok-skip-browser-warning':'1'},body:JSON.stringify({user_id:S.userId,mode:mode,...postaCent(eur),username:(S.username||S.name||'Player'),photo_url:dlMyPhoto()})})
    .then(function(r){return r.json();}).then(function(d){
      if(!d||d.error){ toast('⚠️ '+((d&&d.error)||'error'),'err'); dlCloseOverlay(); if(typeof loadBalance==='function')loadBalance(); return; }
      if(d.balances)S.bal=d.balances;
      if(d.btc!==undefined){ S.btc=saldoDa(d); refresh(); }
      if(d.status==='done'){ dlShowResult(d); return; }
      dlStartPoll(mode);
    }).catch(function(e){ toast('Network error','err'); dlCloseOverlay(); });
}
