var _rtAvv={g:'',ws:null,off:0};
function rtAvvisoSonda(){
  if(_rtAvv.ws||_rtAvv.off||!S.userId)return;
  if(typeof CUR!=='undefined'&&(CUR==='arc'||CUR==='glad'||CUR==='turf'||CUR==='tank'||CUR==='torneo'))return;
  var ws; try{ ws=new WebSocket(twrUrl()); }catch(e){ return; }
  _rtAvv.ws=ws; var fine=false;
  function chiudi(){ if(fine)return; fine=true; try{ws.onmessage=null;ws.onclose=null;ws.close();}catch(e){} _rtAvv.ws=null; }
  var tmo=setTimeout(chiudi,9000);
  ws.onopen=function(){
    var initData='';
    try{initData=(window.gbInitData&&window.gbInitData())||(window.Telegram&&window.Telegram.WebApp&&window.Telegram.WebApp.initData)||'';}catch(e){}
    var prof={}; try{ prof=twrProfile(); }catch(e){}
    try{ ws.send(JSON.stringify({t:'hello',user_id:String(S.userId||''),init_data:initData,profile:prof})); }catch(e){ chiudi(); }
  };
  ws.onmessage=function(ev){
    var m; try{ m=JSON.parse(ev.data); }catch(e){ return; }
    if(!m||!m.t)return;
    if(m.t==='hello_ok'){ try{ ws.send(JSON.stringify({t:'rientra'})); }catch(e){ chiudi(); } return; }
    if(m.t==='start'){
      clearTimeout(tmo);
      if(m.practice&&!m.tour){ try{ ws.send(JSON.stringify({t:'leave'})); }catch(e){} }
      chiudi();
      if(m.game&&!m.tour&&!m.practice) rtAvvisoMostra(String(m.game));
      return;
    }
    if(m.t==='err'){ clearTimeout(tmo); chiudi(); }
  };
  ws.onerror=function(){ clearTimeout(tmo); chiudi(); };
}
