function dlLiveNome(codice,fallback){
  var s='';
  try{ if(typeof dlG==='function' && dlG(codice)
        && typeof dlModeName==='function') s=dlModeName(codice); }catch(_n1){}
  if(!s) s=fallback||String(codice||'').toUpperCase();
  var p=String(s).split(' ');
  if(p.length>1 && !/[a-zA-Z]/.test(p[0]))
    return {ic:'<span class="e" style="background:none;border:0;padding:0;font-size:13px;">'+dlEsc(p[0])+'</span>',
            nome:p.slice(1).join(' ')};
  return {ic:'',nome:s};
}
function dlLiveEco(v){
  var l=document.querySelectorAll('.dm-live-n'),i;
  for(i=0;i<l.length;i++) if(l[i].textContent!==v) l[i].textContent=v;
}
function dlTwDat(d){
  var m={},l,i,el,b,s,n,k;
  ((d&&d.queues)||[]).forEach(function(c){ if(c&&c.game) m[c.game]=(m[c.game]||0)+(c.n||0); });
  ((d&&d.playing)||[]).forEach(function(p){ if(p&&p.game) m[p.game]=(m[p.game]||0)+(p.n||0); });
  l=document.querySelectorAll('.tw-dat');
  for(i=0;i<l.length;i++){
    el=l[i]; b=el.querySelector('b'); s=el.querySelector('span');
    if(!b||!s) continue;
    n=m[el.getAttribute('data-g')||'']||0;
    k=String(n);
    if(el.getAttribute('data-st')===k) continue;
    if(n>0){ b.textContent=k; s.textContent='IN CODA'; el.className='tw-dat vivo'; }
    else   { b.textContent=el.getAttribute('data-d')||''; s.textContent=el.getAttribute('data-l')||''; el.className='tw-dat'; }
    el.setAttribute('data-st',k);
  }
}
