function dlVsSfx(){
  var ctx=(typeof slv2EnsureAudio==='function')?slv2EnsureAudio():null; if(!ctx) return;
  try{
    if(ctx.state==='suspended'){ try{ ctx.resume(); }catch(e){} }
    var dest=(typeof slv2AudioDest==='function')?slv2AudioDest():ctx.destination, t0=ctx.currentTime, tc=t0+0.5;
    var ros=ctx.createOscillator(); ros.type='sawtooth';
    ros.frequency.setValueAtTime(120,t0); ros.frequency.exponentialRampToValueAtTime(900,tc);
    var rf=ctx.createBiquadFilter(); rf.type='bandpass'; rf.frequency.value=700; rf.Q.value=1.1;
    var rg=ctx.createGain(); rg.gain.setValueAtTime(0.0001,t0); rg.gain.exponentialRampToValueAtTime(0.16,tc-0.03); rg.gain.exponentialRampToValueAtTime(0.0001,tc+0.08);
    ros.connect(rf).connect(rg).connect(dest); ros.start(t0); ros.stop(tc+0.1);
    var boom=ctx.createOscillator(); boom.type='sine'; boom.frequency.setValueAtTime(160,tc); boom.frequency.exponentialRampToValueAtTime(46,tc+0.26);
    var bg=ctx.createGain(); bg.gain.setValueAtTime(0.0001,tc); bg.gain.linearRampToValueAtTime(0.9,tc+0.012); bg.gain.exponentialRampToValueAtTime(0.001,tc+0.3);
    boom.connect(bg).connect(dest); boom.start(tc); boom.stop(tc+0.32);
    var len=Math.floor(ctx.sampleRate*0.16), buf=ctx.createBuffer(1,len,ctx.sampleRate), dd=buf.getChannelData(0);
    for(var i=0;i<len;i++){ dd[i]=(Math.random()*2-1)*Math.pow(1-i/len,1.8); }
    var noise=ctx.createBufferSource(); noise.buffer=buf;
    var nf=ctx.createBiquadFilter(); nf.type='highpass'; nf.frequency.value=1400;
    var ng=ctx.createGain(); ng.gain.setValueAtTime(0.55,tc); ng.gain.exponentialRampToValueAtTime(0.001,tc+0.16);
    noise.connect(nf).connect(ng).connect(dest); noise.start(tc); noise.stop(tc+0.18);
    [1318,1760].forEach(function(f){ var o=ctx.createOscillator(); o.type='triangle'; o.frequency.setValueAtTime(f,tc);
      var g=ctx.createGain(); g.gain.setValueAtTime(0.0001,tc); g.gain.linearRampToValueAtTime(0.14,tc+0.01); g.gain.exponentialRampToValueAtTime(0.001,tc+0.55);
      o.connect(g).connect(dest); o.start(tc); o.stop(tc+0.6); });
  }catch(e){}
}
function dlGameWheel(mode, onDone){
  var games=[],_gi,_gr;
  for(_gi=0;_gi<DL_GAMES.length;_gi++){_gr=DL_GAMES[_gi];if(_gr[6].indexOf('w')<0)continue;
    games.push({m:_gr[0],i:dlIcoArena(_gr),n:dlNomeRuota(_gr)});}
  var strip4=Math.ceil(24/games.length);
  var strip=[]; for(var k=0;k<strip4;k++){ for(var gi=0;gi<games.length;gi++) strip.push(games[gi]); }
  var tg=games[0]; for(var t=0;t<games.length;t++){ if(games[t].m===mode) tg=games[t]; }
  strip.push(tg);
  var html='<div class="pvp-m-title" style="color:#ffd700;">RANDOM GAME</div><div class="pvp-wheel"><div class="pvp-wheel-strip" id="pvp-wstrip">';
  for(var s2=0;s2<strip.length;s2++){ html+='<div class="pvp-wcell"><div class="pvp-wico">'+strip[s2].i+'</div><div class="pvp-wnm">'+strip[s2].n+'</div></div>'; }
  html+='</div><div class="pvp-wheel-fade"></div><div class="pvp-wheel-marker"></div></div><div id="pvp-wresult" style="text-align:center;font-weight:800;margin-top:6px;color:#ffd700;opacity:0;transition:opacity .3s;"></div>';
  dlModalHTML(html);
  var el=document.getElementById('pvp-wstrip');
  if(el){
    var cw=88, finalIdx=strip.length-1, off=88 - finalIdx*cw;
    el.style.transition='none'; el.style.transform='translateX(0)'; void el.offsetWidth;
    el.style.transition='transform 2.4s cubic-bezier(.12,.7,.18,1)'; el.style.transform='translateX('+off+'px)';
    try{ gSound('ball-roll',{duration:2400}); }catch(e){}
  }
  setTimeout(function(){
    var rr=document.getElementById('pvp-wresult'); if(rr){ rr.textContent='▶ '+dlModeName(mode)+' !'; rr.style.opacity='1'; }
    try{ gSound('ball-stop'); }catch(e){}
    setTimeout(onDone, 950);
  }, 2500);
}
function dlReveal(d){
  dlStopPoll();
  if(d.balances)S.bal=d.balances;
      if(d.btc!==undefined){ S.btc=saldoDa(d); refresh(); }
  if(typeof loadBalance==='function')loadBalance().then(function(){dlUpdateStatsDom();});
  var youP1=d.you_p1, det=d.detail||{}, mode=det.mode||d.mode, win=d.you_win;
  var oppName = youP1 ? d.p2_name : d.p1_name;
  var amt = win ? ('+€'+((d.prize_eur||0)-(d.actual_bet_eur||0)).toFixed(2)) : ('−€'+(d.actual_bet_eur||0).toFixed(2));
  dlModalHTML(
    '<div class="pvp-m-title" style="color:#ff5b5b;">'+dlModeName(mode)+' DUEL</div>'+
    '<div class="pvp-vs"><div class="pvp-fighter"><div class="pvp-fighter-av">🧑</div><div class="pvp-fighter-name">YOU</div></div>'+
    '<div class="pvp-vs-badge">VS</div>'+
    '<div class="pvp-fighter"><div class="pvp-fighter-av">👤</div><div class="pvp-fighter-name">'+dlEsc(oppName)+'</div></div></div>'+
    '<div class="pvp-reveal" id="dl-play"></div>'+
    '<div id="dl-outcome" class="dl-outcome"></div>');
  function finish(){
    var oc=document.getElementById('dl-outcome'); if(!oc) return;
    oc.innerHTML='<div class="pvp-result '+(win?'win':'lose')+'">'+(win?'🏆 YOU WIN':'💀 YOU LOSE')+'</div>'+
      '<div style="text-align:center;font-weight:800;margin-top:4px;color:'+(win?'#39ff14':'#ff5b5b')+';">'+amt+'</div>'+
      '<button class="pvp-m-btn gold" onclick="dlPickGame(\''+mode+'\')">'+LBL_AGAIN+'</button>'+
      '<button class="pvp-m-btn" onclick="dlCloseOverlay()">CLOSE</button>';
    oc.classList.add('show');
    try{ gSound(win?'win-big':'lose'); }catch(e){}
    if(win){ try{ tg.HapticFeedback && tg.HapticFeedback.notificationOccurred('success'); }catch(e){} }
  }
  var play=document.getElementById('dl-play');
  if(!play){ finish(); return; }
  if(mode==='dice'){
    var yd=youP1?det.d1:det.d2, od=youP1?det.d2:det.d1;
    try{DD3.oppTvl=((youP1?d.p2_info:d.p1_info)||{}).tvl||null;}catch(e){DD3.oppTvl=null;}
    if(typeof dd3Duello==='function'&&dd3Duello(play,yd,od,oppName,win,finish))return;
    var faces=['⚀','⚁','⚂','⚃','⚄','⚅'];
    play.innerHTML='<div class="dl-dice-row"><span class="dl-die" id="dl-die-y">⚄</span><span class="dl-die-vs">VS</span><span class="dl-die" id="dl-die-o">⚄</span></div>'+
      '<div class="dl-dice-lbl"><span>YOU</span><span>'+dlEsc(oppName)+'</span></div>';
    var dy=document.getElementById('dl-die-y'), doo=document.getElementById('dl-die-o'), n=0;
    var iv=setInterval(function(){
      if(dy)dy.textContent=faces[Math.floor(Math.random()*6)];
      if(doo)doo.textContent=faces[Math.floor(Math.random()*6)];
      try{ gSound('chip'); }catch(e){}
      n++;
      if(n>=12){ clearInterval(iv);
        if(dy){ dy.textContent=faces[(yd||1)-1]; dy.classList.add('lock'); }
        if(doo){ doo.textContent=faces[(od||1)-1]; doo.classList.add('lock'); }
        try{ gSound('ball-stop'); }catch(e){}
        setTimeout(finish,750);
      }
    },85);
  } else if(mode==='bj' || mode==='cards'){
    var yh=(youP1?det.h1:det.h2)||[], oh=(youP1?det.h2:det.h1)||[];
    var yv=(mode==='bj')?(youP1?det.s1:det.s2):(youP1?det.n1:det.n2);
    var ov=(mode==='bj')?(youP1?det.s2:det.s1):(youP1?det.n2:det.n1);
    play.innerHTML='<div class="dl-deal-side"><div class="dl-deal-lbl">YOU</div><div class="dl-deal-cards" id="dl-cy"></div><div class="dl-deal-val" id="dl-vy"></div></div>'+
      '<div class="dl-deal-side"><div class="dl-deal-lbl">'+dlEsc(oppName)+'</div><div class="dl-deal-cards" id="dl-co"></div><div class="dl-deal-val" id="dl-vo"></div></div>';
    var cy=document.getElementById('dl-cy'), co=document.getElementById('dl-co');
    var seq=[], maxc=Math.max(yh.length,oh.length);
    for(var i=0;i<maxc;i++){ if(i<yh.length)seq.push(['y',yh[i]]); if(i<oh.length)seq.push(['o',oh[i]]); }
    var si=0;
    function dealNext(){
      if(si>=seq.length){
        var vy=document.getElementById('dl-vy'), vo=document.getElementById('dl-vo');
        if(vy)vy.innerHTML=(mode==='bj')?'= <b>'+yv+'</b>':'<b style="color:#ffd700;">'+dlEsc(yv)+'</b>';
        if(vo)vo.innerHTML=(mode==='bj')?'= <b>'+ov+'</b>':'<b>'+dlEsc(ov)+'</b>';
        if(vy)vy.classList.add('show'); if(vo)vo.classList.add('show');
        try{ gSound('chip'); }catch(e){}
        setTimeout(finish,800);
        return;
      }
      var it=seq[si++], c=it[1], red=(c.s==='♥'||c.s==='♦');
      var sp=document.createElement('span');
      sp.className='pvp-card dl-card-in'+(red?' red':'');
      sp.textContent=c.r+c.s;
      (it[0]==='y'?cy:co).appendChild(sp);
      try{ gSound('chip'); }catch(e){}
      setTimeout(dealNext,300);
    }
    dealNext();
  } else { finish(); }
}
