function dlRrStartPoll(){
  dlRrStopPoll();
  DLRR.poll=setInterval(function(){
    if(CUR!=='duel'){ dlRrStopPoll(); dlRrStopTick(); return; }
    if(DLRR.busy) return;
    fetch(BACKEND+'/duel/rr_state',{method:'POST',headers:dlBjHdr(),body:JSON.stringify({user_id:S.userId})})
      .then(function(r){return r.json();}).then(function(d){
        if(!d||d.error||d.status==='none') return;
        var sig=(d.evseq||0)+'|'+(d.your_turn?1:0)+'|'+d.you_lives+'|'+d.opp_lives+'|'+d.loaded+'|'+(d.status||d.state||'')+dlTourSigP(d);
        if(sig===DLRR.sig) return;
        var prevSeq=DLRR.lastSeq||0; DLRR.sig=sig; DLRR.lastSeq=Math.max(prevSeq,d.evseq||0);
        var ev=d.last, oppActed=ev&&(d.evseq||0)>prevSeq&&ev.shooter!=null&&ev.shooter!==d.seat;
        var done=(d.status==='done'||d.state==='done');
        if(oppActed){
          DLRR.busy=true;
          var anim=ev.spin?dlRrSpinAnim:dlRrAnimate;
          anim(ev,function(){ DLRR.busy=false; DLRR.sig=''; if(ev.shooter!==d.seat) DLRR.aim='opp'; dlRrBoard(d); if(done){ dlRrStopPoll(); dlRrAfterDone(d); } }, d);
        } else {
          dlRrBoard(d);
          if(done){ dlRrStopPoll(); dlRrAfterDone(d); }
        }
      }).catch(function(){});
  },1300);
}
