function dlRrHearts(n,full){ n=Math.max(0,n|0); return n>0?('❤️'.repeat(n)+ (full>n?'🖤'.repeat(full-n):'')):'💀'; }
function dlRrCylHTML(d){
  var fired=(d&&d.cyl_fired)||[], loaded=(d&&d.loaded)||0, total=fired.length+loaded;
  if(total<=0) total=6;
  var cx=50, cy=50, R=31, chR=(total>6?7.4:9);
  var chambers='';
  for(var i=0;i<total;i++){
    var ang=(i*360/total - 90)*Math.PI/180;
    var x=cx+R*Math.cos(ang), y=cy+R*Math.sin(ang);
    var spent=(i<fired.length);
    var cls=spent?(fired[i]?'live':'blank'):'empty';
    if(i===fired.length) cls+=' next';
    chambers+='<circle class="rrcyl-ch '+cls+'" cx="'+x.toFixed(1)+'" cy="'+y.toFixed(1)+'" r="'+chR+'"/>';
    if(!spent){ chambers+='<circle class="rrcyl-cap" cx="'+x.toFixed(1)+'" cy="'+y.toFixed(1)+'" r="'+(chR*0.4).toFixed(1)+'"/>'; }
  }
  var rot=(-(fired.length)*(360/total)).toFixed(1);
  return '<div class="dlrr2-cylwrap"><svg class="rrcyl" viewBox="0 0 100 100" id="dlrr-cylsvg" aria-hidden="true">'+
    '<polygon class="rrcyl-hammer" points="50,3 44.5,12 55.5,12"/>'+
    '<circle class="rrcyl-body" cx="50" cy="50" r="45"/>'+
    '<circle class="rrcyl-rim" cx="50" cy="50" r="45"/>'+
    '<circle class="rrcyl-rim" cx="50" cy="50" r="39"/>'+
    '<g class="rrcyl-rot" id="dlrr-cylrot" style="transform:rotate('+rot+'deg);">'+chambers+
      '<circle class="rrcyl-hub" cx="50" cy="50" r="9"/><circle class="rrcyl-pin" cx="50" cy="50" r="3.2"/>'+
    '</g>'+
    '<polygon class="rrcyl-firepin" points="50,1.5 43.5,13 56.5,13"/></svg></div>';
}
function dlRrSpinDrum(d){
  var g=document.getElementById('dlrr-cylrot'); if(!g||!d) return;
  var fired=((d.cyl_fired)||[]).length, loaded=d.loaded||0, total=fired+loaded; if(total<=0) return;
  var rot=-(fired)*(360/total);
  g.style.transition='transform .5s cubic-bezier(.2,.85,.2,1)';
  g.style.transform='rotate('+rot.toFixed(1)+'deg)';
}
function dlRrShells(d){
  var loaded=d.loaded||0, live=d.live_left||0, blank=d.blank_left||0;
  var dots=''; for(var i=0;i<loaded;i++){ dots+='<span class="dlrr-shell"></span>'; }
  if(!loaded) dots='<span class="dlrr-shell empty"></span>';
  return '<div class="dlrr-chamber">'+
    '<div class="dlrr-cyl">'+dots+'</div>'+
    '<div class="dlrr-tally"><span class="dlrr-live">🔴 '+live+' LIVE</span><span class="dlrr-blank">⚪ '+blank+' BLANK</span></div>'+
    '</div>';
}
function dlRrEventText(ev,reloaded){
  if(reloaded&&(!ev)) return '<span style="color:#ffd700;">⟳ Chamber reloaded</span>';
  if(!ev) return 'Make your move…';
  var who=ev.self?'shot themselves':'fired at the other';
  var shooterTxt=(ev.shooter===ev._meSeat)?'You':'Opponent';
  if(ev.live){ return '<span class="dlrr-bang">💥 BANG! '+(ev.self?'self-shot LIVE':'a LIVE round hit')+'</span>'; }
  return '<span class="dlrr-click">🔘 click… blank</span>'+(reloaded?' <span style="color:#ffd700;">⟳ reloaded</span>':'');
}
