function dlPkdSig(d){ return (d.state||'')+'|'+(d.you_drawn?1:0)+'|'+(d.opp_drawn?1:0)+'|'+((d.you_hand||[]).map(function(c){return c.r+c.s;}).join(''))
  +'|T'+(d.tour_gara||0)+(d.tour_rigioca?'R':'')+dlTourSigP(d); }
var DLRND={poll:null,bet:0};
function dlRndStopPoll(){ if(DLRND.poll){ clearInterval(DLRND.poll); DLRND.poll=null; } }
function practiceStart(game, daTorneo){
  if(game==='turf'&&typeof twr3dPrecarica==='function'){try{twr3dPrecarica();}catch(_p3){}}
  if(typeof TRN!=='undefined')TRN.trainFrom=daTorneo?String(daTorneo):'';
  if(!S.userId){ toast('Apri da Telegram per allenarti','err'); return; }
  fetch(BACKEND+'/duel/practice_start',{method:'POST',headers:dlBjHdr(),body:JSON.stringify({user_id:S.userId,game:game,username:(S.username||S.name||'Player'),photo_url:dlMyPhoto()})})
    .then(function(r){return r.json();}).then(function(d){
      if(!d||d.error||!(d.ticket||d.duel)){ toast('⚠️ '+((d&&d.error)||'allenamento non disponibile'),'err',2400); return; }
      if(game==='turf'){ window.TWR_TICKET=d.ticket; window.TWR_PRACTICE=true; go('turf'); }
      else if(game==='glad'){ window.GLD_TICKET=d.ticket; window.GLD_PRACTICE=true; go('glad'); }
      else if(game==='tank'){ window.TKD_TICKET=d.ticket; window.TKD_PRACTICE=true; go('tank'); }
      else if(d.duel){
        var _cl=(typeof TRN_DUEL_CLIENT!=='undefined')&&TRN_DUEL_CLIENT[(typeof duelKey==='function')?duelKey(game):game];
        if(!_cl){ toast('Gioco non ancora supportato — aggiorna l\'app','err',2600); return; }
        var _st=_cl.store();
        if(_st)_st.bet=0;
        go('duel');
        _cl.enter(d.vista||{});
      }
      else if(RTD_G&&RTD_G[game]){ window.RTD_TICKET=d.ticket; window.RTD_TICKET_GAME=game; window.RTD_GAME=game; window.RTD_PRACTICE=true; go('arc'); }
      else { toast('Allenamento non disponibile per questo gioco','err',2200); }
    }).catch(function(){ toast('Errore di rete','err'); });
}
function twrPractice(){ practiceStart('turf'); }
function gldPractice(){ practiceStart('glad'); }
function practiceOverHTML(won, againFn, toRealFn){
  var h=won
    ? '<div style="font-size:46px;">🏆</div><div class="tw-win-t">ALLENAMENTO VINTO</div><div class="tw-ov-sub">Hai battuto i bot — è pratica, nessun premio.</div>'
    : '<div style="font-size:44px;">🤖</div><div class="tw-lose-t">ALLENAMENTO FINITO</div><div class="tw-ov-sub">I bot ti hanno steso. Riprova — è tutto gratis.</div>';
  var _tt=(typeof TRN!=='undefined'&&TRN.trainFrom)?String(TRN.trainFrom):'';
  h+='<div class="tw-ov-btns"><button class="action-btn train-btn" onclick="'+againFn+'()">🔁 ANCORA · GRATIS</button>'
   +(_tt?'<button class="action-btn gold" onclick="trnTrainBack()">🏆 TORNA AL TORNEO</button>'
        :'<button class="action-btn gold" onclick="'+toRealFn+'()">💰 GIOCA VERA</button>')
   +'</div>';
  return h;
}
function trnTrainBack(){
  var tid=(typeof TRN!=='undefined'&&TRN.trainFrom)?String(TRN.trainFrom):'';
  TRN.trainFrom='';
  if(typeof twrOvClose==='function')twrOvClose();
  if(typeof gldOvClose==='function')gldOvClose();
  if(typeof rtdOvClose==='function')rtdOvClose();
  if(typeof RTD!=='undefined')RTD.ui='';
  if(typeof TWR!=='undefined')TWR.practice=false;
  if(typeof GLD!=='undefined')GLD.practice=false;
  if(typeof RTD!=='undefined')RTD.practice=false;
  if(tid){TRN.want=tid;TRN.wantN=0;}
  go('torneo');
}
