  var sc=document.createElement('script');sc.src='dpk_arte.js?v='+DPK_ARTE_VER;
  var fine=function(ok){var l=window.__dpkArteCb||[];window.__dpkArteCb=[];window.__dpkArteVolo=0;l.forEach(function(f){try{if(f)f(ok&&!!(window.DPM&&DPM.COSMETICI));}catch(e){}});};
