    TWR.snaps=[];TWR.over=null;TWR.pred.ok=false;TWR.cam.ok=false;TWR.lastHp=null;
    TWR.elimShown=false;TWR.feedRows=[];TWR.banner=null;TWR.shake=0;TWR.flash=0;
    TWR.anim={};TWR.fxq=[];TWR.wasCar=false;TWR.lastLv=1;TWR._fireGradCell=0;
    twrShowMatch();
