function twrThrowStart(ev,code){
  ev.preventDefault();
  var t=(ev.touches&&ev.touches[0])||ev;
  TWR.throwAim={on:true,item:code,sx:t.clientX,sy:t.clientY,ax:0,ay:0,d:0,drag:false};
  function mv(e2){
    if(!TWR.throwAim||!TWR.throwAim.on)return;
    var t2=(e2.touches&&e2.touches[0])||e2;
    var dx=t2.clientX-TWR.throwAim.sx,dy=t2.clientY-TWR.throwAim.sy;
    var m=Math.hypot(dx,dy);
    if(m>14){
      TWR.throwAim.drag=true;
      TWR.throwAim.ax=dx/m;TWR.throwAim.ay=dy/m;
      TWR.throwAim.d=Math.min(1,Math.max(0.25,m/70));
    }else{TWR.throwAim.drag=false;}
    if(e2.cancelable)e2.preventDefault();
  }
  function end(){
    window.removeEventListener('touchmove',mv);window.removeEventListener('mousemove',mv);
    window.removeEventListener('touchend',end);window.removeEventListener('mouseup',end);
    var ta=TWR.throwAim;
    TWR.throwAim=null;
    if(!ta)return;
    if(ta.drag){
      var _tax=ta.ax,_tay=ta.ay;
      if(TWR3D.ok){var _w3t=twr3dStick(_tax,_tay,'muovi');_tax=_w3t[0];_tay=_w3t[1];}
      twrSend({t:'act',a:ta.item.toLowerCase(),ax:_tax,ay:_tay,power:ta.d});
      TWS.play('whoosh');
      try{tg.HapticFeedback&&tg.HapticFeedback.impactOccurred('medium');}catch(e){}
    }else{
      twrAct(ta.item.toLowerCase());
    }
  }
  window.addEventListener('touchmove',mv,{passive:false});
  window.addEventListener('mousemove',mv);
  window.addEventListener('touchend',end);
  window.addEventListener('mouseup',end);
}
var TWR_SCALA_DOVE={tetto:['TETTO','ROOF'],terra:['GIÙ','DOWN'],p1:['PIANO 1','FLOOR 1'],p2:['PIANO 2','FLOOR 2']};
function twrScalaTasto(cb,cbi,cbt,you){
  var s=you.scala,su=s[2]==='su',en=window.GB_LANG==='en',d=TWR_SCALA_DOVE[s[3]]||[s[3],s[3]];
  TWR.ctxAct='special';cb.style.display='flex';
  if(cbi&&cbi.textContent!==(su?'▲':'▼'))cbi.textContent=su?'▲':'▼';
  var t=d[en?1:0];if(cbt&&cbt.textContent!==t)cbt.textContent=t;
  var k=(you.on_stairs&&you.climb>0)?Math.round(you.climb*100):0;
  if(cb._scK!==k){cb._scK=k;cb.style.setProperty('--sc',k+'%');}
  var va=!!(you.scala_auto||k>0);if(cb._scV!==va){cb._scV=va;cb.classList.toggle('va',va);}
}
function twrScala2d(ctx,you,W2X,W2Y,cell,now){
  var s=you.scala;if(!s)return;
  var x=W2X(s[0]+0.5),y=W2Y(s[1]+0.5),su=s[2]==='su',a=0.55+0.35*Math.sin(now/160);
  ctx.save();
  ctx.strokeStyle=su?'rgba(250,204,21,'+a+')':'rgba(34,211,238,'+a+')';ctx.lineWidth=2.5;
  ctx.beginPath();ctx.arc(x,y,cell*(0.55+0.08*Math.sin(now/160)),0,6.283);ctx.stroke();
  ctx.fillStyle=su?'#facc15':'#22d3ee';ctx.font='bold '+Math.round(cell*0.62)+'px sans-serif';
  ctx.fillText(su?'▲':'▼',x,y-cell*(0.95+0.1*Math.sin(now/200)));
  ctx.restore();
}
