function twrScalaLascia(){
  try{var L=window.OZ_STICKS||[],j=document.getElementById('twr-joy');
    for(var i=0;i<L.length;i++){if(L[i].el===j){L[i]();break;}}}catch(e){}
  if(TWR.joy.on){TWR.joy.on=false;TWR.joy.mx=0;TWR.joy.my=0;if(typeof TWR3D!=='undefined')TWR3D.sj=null;}
}
function twrAct(a){
  if(a==='special'){var _f01=performance.now();if(TWR._scTap&&_f01-TWR._scTap<120)return;TWR._scTap=_f01;twrScalaLascia();}
  if(a==='medikit'&&TWR.you&&TWR.you.hp>=5){toast('Sei già al massimo ❤️','warn',1400);return;}
  twrSend({t:'act',a:a});
  if(a==='molotov'||a==='grenade')TWS.play('whoosh');
  if(a==='smoke')TWS.play('whoosh',0.7);
  try{tg.HapticFeedback&&tg.HapticFeedback.impactOccurred(a==='attack'?'medium':'light');}catch(e){}
}
function twrPump(){
  if(TWR.ui!=='match')return;
  if(TWR.spec)return;
  twrAutoSchema();
  var n=performance.now(),k,att=false;
  if(TWR.joy.on){
    k=Math.round(TWR.joy.mx*40)+','+Math.round(TWR.joy.my*40);
    if(TWR.sentZero||(k!==TWR._inK&&n-(TWR._inT||0)>=33)||n-(TWR._inT||0)>=250){
      twrSend({t:'in',mx:TWR.joy.mx,my:TWR.joy.my});TWR._inK=k;TWR._inT=n;TWR.sentZero=false;
      twrAutoStoria(n,TWR.joy.mx,TWR.joy.my,null);
    }else if(k!==TWR._inK)att=true;
  }else if(!TWR.sentZero){
    twrSend({t:'in',mx:0,my:0});twrAutoStoria(n,0,0,null);
    TWR.sentZero=true;TWR._inK='';TWR._inT=n;
  }
  if(TWR.aim.on){
    k=Math.round(TWR.aim.ax*40)+','+Math.round(TWR.aim.ay*40);
    if(TWR.sentAimZero||(k!==TWR._amK&&n-(TWR._amT||0)>=33)||n-(TWR._amT||0)>=250){
      if(TWR.sentAimZero)TWR._aimOnT=n;
      twrSend({t:'aim',ax:TWR.aim.ax,ay:TWR.aim.ay,on:1});TWR._amK=k;TWR._amT=n;TWR.sentAimZero=false;
      twrAutoStoria(n,null,null,Math.hypot(TWR.aim.ax,TWR.aim.ay)>0.25);
    }else if(k!==TWR._amK)att=true;
  }else if(!TWR.sentAimZero){
    twrSend({t:'aim',on:0});twrAutoStoria(n,null,null,false);
    TWR.sentAimZero=true;TWR._amK='';TWR._amT=n;
  }
  if(att&&!TWR._pumpTo)TWR._pumpTo=setTimeout(function(){TWR._pumpTo=null;twrPump();},34);
}
function twrOnSnap(m){
  m.rx=performance.now();
  var idx={};
  (m.p||[]).forEach(function(r){idx[r[0]]=r;});
  m.idx=idx;
  TWR.snaps.push(m);
  if(TWR.snaps.length>7)TWR.snaps.shift();
  twrAnticStima(m);
  TWR.lastRaw=m;
  TWR.you=m.you||TWR.you;
  if(TWR.map&&TWR.map.casino&&TWR.map.casino.piani)twrPianiSnap();
  if(m.you){
    if(TWR.lastHp!=null&&m.you.hp<TWR.lastHp){
      TWR.shake=Math.min(14,TWR.shake+9);TWR.flash=1;
      TWS.play('hurt');
      try{tg.HapticFeedback&&tg.HapticFeedback.notificationOccurred('error');}catch(e){}
      var _hk=null;(m.feed||[]).forEach(function(e){if((e.k==='hit'||e.k==='kill')&&e.victim===TWR.myId&&e.who)_hk=e;});
      var _sp=_hk?twrPosOf(_hk.who):null;
      if(_hk&&_hk.da&&_hk.da.length===2&&TWR.pred.ok)_sp=[TWR.pred.x+_hk.da[0]*4,TWR.pred.y+_hk.da[1]*4];
      if(!_sp&&_hk&&TWR.snaps.length>1){
        var _qa=TWR.snaps[TWR.snaps.length-2].idx[TWR.myId],_qb=m.idx[TWR.myId];
        if(_qa&&_qb){var _kx=_qb[1]-_qa[1],_ky=_qb[2]-_qa[2],_kn=Math.hypot(_kx,_ky);if(_kn>0.3)_sp=[_qb[1]-_kx/_kn*4,_qb[2]-_ky/_kn*4];}
      }
      if(_sp)TWR._snipeFrom={t:performance.now(),x:_sp[0],y:_sp[1]};
    }
    if(TWR._gunPrev&&!m.you.gun&&m.you.alive){
      TWS.play('clank',0.7);
      if(TWR.pred.ok)twrFxAdd('txt',TWR.pred.x,TWR.pred.y-0.6,900,'ARMA SCARICA','#facc15');
      try{navigator.vibrate&&navigator.vibrate([20,40,20]);}catch(x){}
    }
    TWR._gunPrev=m.you.gun||null;
    TWR.lastHp=m.you.hp;
    TWS.heart(m.you.alive&&m.you.hp===1);
    var _a3=twr3dSuoniAuto();
    if(m.you.in_car!==TWR.wasCar){
      if(!_a3)TWS.play('door');TWR.wasCar=m.you.in_car;
      if(!m.you.in_car)TWS.engine(false);
    }
    if(m.you.in_car&&!_a3)TWS.engine(true,Math.hypot(TWR.joy.mx,TWR.joy.my));
    else if(_a3&&TWS.engO)TWS.engine(false);
    var scN=(m.you.gun==='SNIPER'&&m.you.alive)?(m.you.scope||0):0,scP=TWR._scopePrev||0;
    if(scN>0.05&&scP<=0.05){try{navigator.vibrate&&navigator.vibrate(12);}catch(x){}}
    if((scP<0.33&&scN>=0.33)||(scP<0.66&&scN>=0.66))TWS.play('scope',0.4+scN*0.4);
    if(scP<1&&scN>=1){TWS.play('scopelock');try{navigator.vibrate&&navigator.vibrate(18);}catch(x){}}
    TWR._scopePrev=scN;
    if(!m.you.alive&&!TWR.elimShown&&!m.over)twrElim();
  }
  (m.feed||[]).forEach(twrFeedEvent);
  if(m.st)twrStrutture(m.st);
  twrHud(m);
  if(TWR3D.ok){try{TWR3D.g.snap(m);}catch(e){twr3dCade(e);}}
}
function twrFxAdd(tp,x,y,dur,txt,col){
  TWR.fxq.push({tp:tp,x:x,y:y,t0:performance.now(),dur:dur||700,txt:txt,col:col});
  if(TWR.fxq.length>40)TWR.fxq.shift();
}
function twrPosOf(id){
  var r=TWR.lastRaw&&TWR.lastRaw.idx[id];
  return r?[r[1],r[2]]:null;
}
