function tkBack(){
  if(typeof gxIntercetta==='function'&&gxIntercetta('tkd'))return;
  if(TKD.spec){tkSpecExit();return;}
  if(TKD.tour){
    if(TKD.ui==='match'){
      if(!confirm('Sei in un match del torneo: se esci ora sei eliminato. Uscire?'))return;
      tkStopRaf();TKD.ui='';tkOvClose();TKD.tour=false;
      wsNetBanner('tank',0);go('torneo');return;
    }
    tkTourLeave();return;
  }
  if(TKD.practice){
    tkLeave();
    tkStopRaf();TKD.ui='';tkOvClose();
    TKD.practice=false;TKD.pendingTicket=null;
    wsNetBanner('tank',0);
    if(typeof TRN!=='undefined'&&TRN.trainFrom){trnTrainBack();return;}
    go('duel');return;
  }
  if(TKD.ui==='search'){tkLeave();}
  else if(TKD.ui==='match'){
    if(!confirm('Sei in partita: se esci ora perdi la puntata. Uscire?'))return;
    tkLeave();TKD.ui='';tkOvClose();
  }
  wsNetBanner('tank',0);
  go('duel');
}
function tkPump(){
  if(TKD.ui!=='match')return;
  if(TKD.spec)return;
  if(TKD.joy.on){tkSend({t:'in',mx:TKD.joy.mx,my:TKD.joy.my});TKD.sentZero=false;}
  else if(!TKD.sentZero){tkSend({t:'in',mx:0,my:0});TKD.sentZero=true;}
  if(TKD.aim.on){tkSend({t:'aim',ax:TKD.aim.ax,ay:TKD.aim.ay,on:1});TKD.sentAimZero=false;}
  else if(!TKD.sentAimZero){tkSend({t:'aim',on:0});TKD.sentAimZero=true;}
}
function tkOnSnap(m){
  m.rx=performance.now();
  var idx={};(m.p||[]).forEach(function(r){idx[r[0]]=r;});
  m.idx=idx;
  TKD.snaps.push(m);
  if(TKD.snaps.length>7)TKD.snaps.shift();
  TKD.lastRaw=m;
  TKD.you=m.you||TKD.you;
  if(m.you){
    if(TKD.lastHp!=null&&m.you.hp<TKD.lastHp){
      TKD.shake=Math.min(15,TKD.shake+10);TKD.flash=1;
      TWS.play('hurt');
      try{tg.HapticFeedback&&tg.HapticFeedback.notificationOccurred('error');}catch(e){}
    }
    TKD.lastHp=m.you.hp;
  }
  (m.feed||[]).forEach(tkFeedEvent);
  tkHud(m);
}
function tkFxAdd(tp,x,y,dur,big,txt,col){
  TKD.fxq.push({tp:tp,x:x,y:y,t0:performance.now(),dur:dur||700,big:big,txt:txt,col:col});
  if(TKD.fxq.length>36)TKD.fxq.shift();
}
function tkFeedEvent(e){
  var me=TKD.spec?null:TKD.myId;
  hapDaFeed('tank',e,me);
  if(e.k==='spareggio'){
    try{tkFeed('⚡ Pari! Il primo che colpisce VINCE ('+e.n+'/'+e.max+')');tkBanner('SPAREGGIO','Il primo che colpisce vince',2200);TWS.play('alarm',0.7);}catch(_tks){}
    return;
  }
  if(e.k==='shot'){
    TWS.play('cannon',e.who===me?1:0.75);
  }else if(e.k==='bounce'){
    TWS.play('ping',0.7);
    if(e.x!=null)tkFxAdd('spark',e.x,e.y,420,false,null,'#facc15');
  }else if(e.k==='boom'){
    tkFxAdd('boom',e.x,e.y,e.big?900:650,e.big);
    TKD.scorch.push({x:e.x,y:e.y,r:e.big?1.0:0.55,t0:performance.now()});
    if(TKD.scorch.length>26)TKD.scorch.shift();
    TWS.play('boom',e.big?1:0.6);
    if(e.big)TKD.shake=Math.min(15,TKD.shake+6);
  }else if(e.k==='crate'){
    TWS.play('clank',0.8);
    if(e.cell)tkFxAdd('spark',e.cell[0]+0.5,e.cell[1]+0.5,600,false,null,'#22d3ee');
  }else if(e.k==='hit'){
    tkFeed(e.victim===me?'💥 Sei stato colpito!':'🎯 Colpito!');
  }else if(e.k==='shield'){
    tkFeed(e.who===me?'🛡️ Scudo assorbito!':'🛡️ Il suo scudo ha retto');
    TWS.play('clank');
  }else if(e.k==='kill'){
    TWS.play('boom');
    tkFxAdd('boom',e.x,e.y,1000,true);
  }else if(e.k==='pickup'){
    var d=TKD_PICK[e.code]||['📦',e.code];
    tkFeed((e.who===me?'Hai preso: ':'Lui ha preso: ')+d[0]+' '+d[1]);
    TWS.play(e.who===me?'gold':'pick',e.who===me?1:0.5);
    var posP=TKD.lastRaw&&TKD.lastRaw.idx&&TKD.lastRaw.idx[e.who];
    if(posP)tkFxAdd('txt',posP[1],posP[2]-0.55,1200,false,'+'+d[0]+' '+d[1],e.who===me?'#a3e635':'#fca5a5');
  }else if(e.k==='drop'){
    var d2=TKD_PICK[e.code]||['📦',e.code];
    tkFeed('📦 In campo: '+d2[0]+' '+d2[1]);
  }else if(e.k==='sd'){
    if(!TKD._sdSeen){TKD._sdSeen=true;tkBanner('🔥 SUDDEN DEATH','I bordi dell\'arena bruciano — al centro!',2800);}
    TWS.play('alarm',0.8);
  }
}
