    +'<div class="dpt-tabs">'
    +'<button class="dpt-tab'+(t==='c'?' sel':'')+'" onclick="gltTab(\'c\')">⚔️ COMBATTERE</button>'
    +'<button class="dpt-tab'+(t==='w'?' sel':'')+'" onclick="gltTab(\'w\')">🗡️ LE ARMI</button>'
    +'<button class="dpt-tab'+(t==='a'?' sel':'')+'" onclick="gltTab(\'a\')">🏟️ L\'ARENA</button>'
    +'</div>'
    +(t==='w'?gltArms():(t==='a'?gltArena():gltCombat()))
