   +'.trn-av{position:relative;flex:0 0 auto;width:34px;height:34px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-family:\'Russo One\',sans-serif;font-size:14px;color:#fff;overflow:hidden;border:1px solid rgba(255,200,60,.35);}'
