   +'.trn-champ-n{font-family:\'Russo One\',sans-serif;font-size:19px;color:#ffd76b;text-shadow:0 0 16px rgba(255,200,60,.45);margin:2px 0 3px;}'
   +'.trn-champ-s{font-size:11.5px;color:var(--txt2);line-height:1.6;}'
