(function(){
  var old=TWS.play;
  TWS.play=function(n,v){
    if(ARC_SOUNDS[n]){if(TWS.on&&TWS.ctx)ARC_SOUNDS[n](v==null?1:v);return;}
    old(n,v);
  };
})();
var RCE={o1:null,o2:null,nz:null,g:null,g2:null,ng:null,gear:-1,shiftT:0,lastVv:0,vvT:0,acc:false,
         skS:null,skBp:null,skG:null,boS:null,boF:null,boG:null,boOn:false,buf:null};
function rcNoiseBuf(){
  if(RCE.buf||!TWS.ctx)return RCE.buf;
  try{
    var c=TWS.ctx,len=c.sampleRate,b=c.createBuffer(1,len,c.sampleRate),d=b.getChannelData(0);
    for(var i=0;i<len;i++)d[i]=Math.random()*2-1;
    RCE.buf=b;
  }catch(e){}
  return RCE.buf;
}
function rcSfx(n,v){
  var t=performance.now();
  if(t-(RTD._sc.sfxT||0)>120){RTD._sc.sfxT=t;RTD._sc.sfxN=0;}
  if((RTD._sc.sfxN||0)>=3)return;
  RTD._sc.sfxN=(RTD._sc.sfxN||0)+1;
  TWS.play(n,v);
}
function rcDvol(who){
  try{
    if(who==null||String(who)===RTD.myId)return 1;
    var a=RTD.anim&&RTD.anim[who],m=RTD.anim&&RTD.anim[RTD.myId];
    if(!a||!m||a.x==null||m.x==null)return 0.35;
    var d=Math.hypot(a.x-m.x,a.y-m.y);
    return 0.35*Math.max(0.15,Math.min(1,1-d/18));
  }catch(e){return 0.35;}
}
function rcEng(on,speed,vv,gear){
  if(!TWS.ctx||!TWS.on)on=false;
  try{
    if(on&&!RCE.o1){
      var c=TWS.ctx;
      RCE.g=c.createGain();RCE.g.gain.value=0.030;RCE.g.connect(TWS.mg);
      var lp=c.createBiquadFilter();lp.type='lowpass';lp.frequency.value=520;lp.connect(RCE.g);
      RCE.o1=c.createOscillator();RCE.o1.type='sawtooth';RCE.o1.connect(lp);
      RCE.g2=c.createGain();RCE.g2.gain.value=0.5;RCE.g2.connect(lp);
      RCE.o2=c.createOscillator();RCE.o2.type='square';RCE.o2.connect(RCE.g2);
      var nb=rcNoiseBuf();
      if(nb){
        RCE.nz=c.createBufferSource();RCE.nz.buffer=nb;RCE.nz.loop=true;
        var bp=c.createBiquadFilter();bp.type='bandpass';bp.frequency.value=750;bp.Q.value=1;
        RCE.ng=c.createGain();RCE.ng.gain.value=0.010;
        RCE.nz.connect(bp);bp.connect(RCE.ng);RCE.ng.connect(TWS.mg);
        RCE.nz.start();
      }
      RCE.o1.start();RCE.o2.start();
      RCE.gear=(gear==null?-1:gear);RCE.shiftT=0;RCE.lastVv=vv||0;RCE.vvT=0;
    }
    if(!RCE.o1)return;
    if(!on){rcSndKill();return;}
    var t=TWS.ctx.currentTime,pn=performance.now();
    if(gear!=null&&gear!==RCE.gear){
      if(RCE.gear>=0){RCE.shiftT=pn;rcSfx('gshift',1);}
      RCE.gear=gear;
    }
    var f=55+(speed||0)*50;
    if(pn-RCE.shiftT<90)f*=0.82;
    RCE.o1.frequency.value=f;
    RCE.o2.frequency.value=f*0.5+4;
    if(pn-(RCE.vvT||0)>150){
      RCE.acc=(vv||0)>(RCE.lastVv||0)+0.05;
      RCE.lastVv=vv||0;RCE.vvT=pn;
      RCE.g.gain.setTargetAtTime(RCE.acc?0.055:0.030,t,0.08);
    }
  }catch(e){}
}
function rcSkid(active,di,mt1,mt2){
  if(!TWS.ctx||!TWS.on)active=false;
  try{
    if(active&&!RCE.skS){
      var nb=rcNoiseBuf();if(!nb)return;
      var c=TWS.ctx;
      RCE.skS=c.createBufferSource();RCE.skS.buffer=nb;RCE.skS.loop=true;
      RCE.skBp=c.createBiquadFilter();RCE.skBp.type='bandpass';RCE.skBp.Q.value=1.2;
      RCE.skBp.frequency.value=900;
      RCE.skG=c.createGain();RCE.skG.gain.value=0.0001;
      RCE.skS.connect(RCE.skBp);RCE.skBp.connect(RCE.skG);RCE.skG.connect(TWS.mg);
      RCE.skS.start();
    }
    if(!RCE.skS)return;
    var t=TWS.ctx.currentTime;
    if(active){
      RCE.skBp.frequency.setTargetAtTime(900+(di||0)*900+(mt2?1100:mt1?500:0),t,0.05);
      RCE.skG.gain.setTargetAtTime(0.05+(di||0)*0.09,t,0.06);
    }else RCE.skG.gain.setTargetAtTime(0.0001,t,0.12);
  }catch(e){}
}
function rcBoost(active){
  if(!TWS.ctx||!TWS.on)active=false;
  try{
    if(active&&!RCE.boS){
      var nb=rcNoiseBuf();if(!nb)return;
      var c=TWS.ctx;
      RCE.boS=c.createBufferSource();RCE.boS.buffer=nb;RCE.boS.loop=true;
      RCE.boF=c.createBiquadFilter();RCE.boF.type='lowpass';RCE.boF.frequency.value=800;
      RCE.boG=c.createGain();RCE.boG.gain.value=0.0001;
      RCE.boS.connect(RCE.boF);RCE.boF.connect(RCE.boG);RCE.boG.connect(TWS.mg);
      RCE.boS.start();
    }
    if(!RCE.boS)return;
    var t=TWS.ctx.currentTime;
    if(active&&!RCE.boOn){
      RCE.boF.frequency.setValueAtTime(800,t);
      RCE.boF.frequency.exponentialRampToValueAtTime(3200,t+0.25);
      RCE.boG.gain.setTargetAtTime(0.07,t,0.06);
    }else if(!active&&RCE.boOn)RCE.boG.gain.setTargetAtTime(0.0001,t,0.2);
    RCE.boOn=active;
  }catch(e){}
}
function rcSndKill(){
  try{if(RCE.o1)RCE.o1.stop();}catch(e){}
  try{if(RCE.o2)RCE.o2.stop();}catch(e){}
  try{if(RCE.nz)RCE.nz.stop();}catch(e){}
  try{if(RCE.skS)RCE.skS.stop();}catch(e){}
  try{if(RCE.boS)RCE.boS.stop();}catch(e){}
  try{if(RCE.g)RCE.g.disconnect();}catch(e){}
  try{if(RCE.ng)RCE.ng.disconnect();}catch(e){}
  try{if(RCE.skG)RCE.skG.disconnect();}catch(e){}
  try{if(RCE.boG)RCE.boG.disconnect();}catch(e){}
  RCE.o1=RCE.o2=RCE.nz=RCE.g=RCE.g2=RCE.ng=null;
  RCE.skS=RCE.skBp=RCE.skG=null;RCE.boS=RCE.boF=RCE.boG=null;
  RCE.gear=-1;RCE.shiftT=0;RCE.boOn=false;
}
