function rtdConnect(){
  if(RTD.ws&&(RTD.ws.readyState===0||RTD.ws.readyState===1)){
    if(!RTD.pendingTicket&&!RTD.pendingJoin&&!RTD.pendingWatch)return;
    try{RTD.closedByUs=true;RTD.ws.onclose=null;RTD.ws.onerror=null;RTD.ws.onmessage=null;RTD.ws.close();}catch(e){}
    RTD.ws=null;RTD.wsOk=false;
  }
  RTD.closedByUs=false;
  var ws;
  try{ws=new WebSocket(rtdUrl());}catch(e){toast('Connessione fallita','err',2000);return;}
  RTD.ws=ws;
  ws.onopen=function(){
    RTD.wsOk=true;wsNetBanner('arc',0);
    RTD._lastPong=performance.now();RTD._lastPingT=0;
    if(RTD.kaT){clearInterval(RTD.kaT);}
    RTD.kaT=setInterval(function(){
      try{if(RTD.ws&&RTD.ws.readyState===1){RTD._lastPingT=performance.now();RTD.ws.send(JSON.stringify({t:'ping',ts:Date.now()}));}}catch(e){}
    },20000);
    setTimeout(function(){if(RTD.ws===ws&&RTD.wsOk)RTD.retries=0;},10000);
    var initData='';
    try{initData=(window.gbInitData&&window.gbInitData())||(window.Telegram&&window.Telegram.WebApp&&window.Telegram.WebApp.initData)||'';}catch(e){}
    ws.send(JSON.stringify({t:'hello',user_id:String(S.userId||''),init_data:initData,profile:twrProfile(),rebind:(RTD.ui==='match'&&!RTD.over&&!RTD.spec)?1:0}));
  };
  ws.onmessage=function(evm){
    RTD._wsN=(RTD._wsN||0)+1;RTD._wsT=performance.now();
    var msg;try{msg=JSON.parse(evm.data);}catch(e){RTD._wsPE=(RTD._wsPE||0)+1;RTD._rerr='parse:'+e;return;}
    if(msg.t==='s')RTD._wsS=(RTD._wsS||0)+1;
    try{rtdOnMsg(msg);}catch(e){
      RTD._rerr=(msg.t||'?')+':'+(''+(e&&e.message||e)).slice(0,60);
      try{ws.send(JSON.stringify({t:'clog',at:msg.t,msg:String(e&&e.stack||e).slice(0,300)}));}catch(_){}
    }
  };
  ws.onclose=function(ev){
    RTD.wsOk=false;
    if(ev&&ev.code===4001){RTD.closedByUs=true;wsNetBanner('arc',3);return;}
    if(RTD.closedByUs)return;
    var act=(RTD.ui==='match'||RTD.ui==='search')&&!RTD.over;
    if(RTD.retries<10){
      RTD.retries++;
      if(act)wsNetBanner('arc',1);
      setTimeout(function(){if(CUR==='arc'||CUR==='torneo')rtdConnect();},1200*Math.pow(1.6,Math.min(RTD.retries,6))+Math.random()*400);
    }else if(act)wsNetBanner('arc',2);
  };
  ws.onerror=function(){if(RTD.ui==='match'||RTD.ui==='search')wsNetBanner('arc',1);};
}
