  var meBase=RTD.profiles[RTD.myId]||{}, opBase=RTD.profiles[opId]||{};
  var meP={name:meBase.name||'TU',photo_url:meBase.photo_url,xp:meBase.xp,dw:meBase.dw,dl:meBase.dl,wins:(meBase.wins!=null?meBase.wins:null)};
  var opP={name:opBase.name||RTD.names[opId]||'Rivale',photo_url:opBase.photo_url,xp:opBase.xp,dw:opBase.dw,dl:opBase.dl,wins:(opBase.wins!=null?opBase.wins:null)};
  var g=rtdMeta();
