  for(var i=s.length-1;i>0;i--){
    if(t>=s[i-1].rx){
      var a=s[i-1],b=s[i];
      return {a:a,b:b,k:Math.min(1,(t-a.rx)/Math.max(1,b.rx-a.rx))};
    }
  }
