function rtdBack(){
  if(RTD.spec){rtdSpecExit();return;}
  if(typeof gxIntercetta==='function'&&gxIntercetta('rtd'))return;
  if(RTD.tour){
    if(RTD.ui==='match'){
      if(!confirm('Sei in un match del torneo: se esci ora sei eliminato. Uscire?'))return;
      rtdStopRaf();RTD.ui='';rtdOvClose();RTD.tour=false;
      wsNetBanner('arc',0);go('torneo');return;
    }
    rtdTourLeave();return;
  }
  if(RTD.practice){
    rtdLeave();
    rtdStopRaf();RTD.ui='';rtdOvClose();
    RTD.practice=false;RTD.pendingTicket=null;
    wsNetBanner('arc',0);
    if(typeof TRN!=='undefined'&&TRN.trainFrom){trnTrainBack();return;}
    go('duel');return;
  }
  if(RTD.ui==='search'){rtdLeave();}
  else if(RTD.ui==='match'){
    if(!confirm('Sei in partita: se esci ora perdi la puntata. Uscire?'))return;
    rtdLeave();rtdStopRaf();RTD.ui='';rtdOvClose();
  }
  wsNetBanner('arc',0);
  go('duel');
}
