function rcGridFill(){
  var el=document.getElementById('rc-grid');if(!el)return;
  var cap=Math.max(RTD.searchCap||10,2),n=RTD.searchN||1;
  var hh='';
  for(var i=0;i<cap;i++){
    var full=i<n;
    hh+='<div class="rc-slot'+(full?' full':'')+'">'+(full?'<span class="rc-slot-car">🏎️</span>':'<span class="rc-slot-idx">P'+(i+1)+'</span>')+'</div>';
  }
  el.innerHTML=hh;
}
