function luprtInt(x,d){
  if(typeof x==="number"&&isFinite(x)&&Math.floor(x)===x&&x>=-2147483648&&x<2147483648)return x;
  return d;
}
function luprtAltezza(){
  try{
    if(!LUPRT.wrap)return;
    var tg2=window.Telegram&&Telegram.WebApp;
    var h=tg2?Number(tg2.viewportStableHeight||tg2.viewportHeight||0):0;
    if(h>0){LUPRT.wrap.style.height=Math.round(h)+"px";LUPRT.wrap.style.bottom="auto";}
    else{LUPRT.wrap.style.height="100%";LUPRT.wrap.style.bottom="0px";}
  }catch(e){}
}
function luprtEnv(lato){
  try{
    var d=document.createElement("div");
    d.style.cssText="position:fixed;left:-9999px;visibility:hidden;height:env(safe-area-inset-"+lato+",0px);width:env(safe-area-inset-"+lato+",0px);";
    document.body.appendChild(d);
    var v=(lato==="left"||lato==="right")?d.getBoundingClientRect().width:d.getBoundingClientRect().height;
    d.parentNode.removeChild(d);
    return (isFinite(v)&&v>0)?v:0;
  }catch(e){return 0;}
}
function luprtBordi(){
  try{
    if(!LUPRT.fr||!LUPRT.pronto)return;
    var tg2=window.Telegram&&Telegram.WebApp;
    var sa=(tg2&&tg2.safeAreaInset)||{}, ca=(tg2&&tg2.contentSafeAreaInset)||{};
    function q(lato,a,b){
      var t=(Number(a)||0)+(Number(b)||0), e=luprtEnv(lato);
      var v=Math.max(t,e);
      if(!isFinite(v)||v<0)v=0; if(v>200)v=200;
      return Math.round(v);
    }
    luprtPosta({t:"bordi",top:q("top",sa.top,ca.top),bottom:q("bottom",sa.bottom,ca.bottom),
                left:q("left",sa.left,ca.left),right:q("right",sa.right,ca.right)});
  }catch(e){}
}
function luprtTelegram(){
  if(LUPRT.tgEv)return;LUPRT.tgEv=true;
  try{
    var tg2=window.Telegram&&Telegram.WebApp;
    if(tg2&&typeof tg2.onEvent==="function"){
      tg2.onEvent("viewportChanged",function(){luprtAltezza();luprtBordi();});
      tg2.onEvent("safeAreaChanged",luprtBordi);
      tg2.onEvent("contentSafeAreaChanged",luprtBordi);
      tg2.onEvent("fullscreenChanged",luprtBordi);
    }
  }catch(e){}
  try{window.addEventListener("orientationchange",function(){setTimeout(luprtBordi,250);});}catch(e2){}
}
function luprtMonta(){
  if(!LUPRT.wrap){
    var w=document.createElement("div");
    w.id="luprt-wrap";
    w.style.cssText="position:fixed;inset:0;z-index:9100;display:none;background:#0d0a1c;touch-action:none;overscroll-behavior:none;";
    w.innerHTML="<iframe id='luprt-fr' title='LUPUS' allow='autoplay; microphone' style='position:absolute;inset:0;width:100%;height:100%;border:0;display:block;'></iframe>";
    document.body.appendChild(w);
    LUPRT.wrap=w;LUPRT.fr=w.querySelector("#luprt-fr");
    LUPRT.fr.addEventListener("load",function(){ if(LUPRT.fr.getAttribute("src")===LUPRT_URL)LUPRT.loads++; });
    luprtTelegram();
  }
  if(LUPRT.fr.getAttribute("src")!==LUPRT_URL){
    LUPRT.pronto=false;LUPRT.coda=[];LUPRT.codaPiena=false;
    LUPRT.fr.setAttribute("src",LUPRT_URL);
  }
}
