function luprtPosta(m){
  try{ LUPRT.fr.contentWindow.postMessage({lup:"giu",m:m},LUPRT_ORIGIN); }catch(e){}
}
function luprtGiu(m){
  if(!LUPRT.aperto||!LUPRT.fr)return;
  if(!LUPRT.pronto){
    if(LUPRT.coda.length<LUPRT_CODA_MAX){LUPRT.coda.push(m);return;}
    if(!LUPRT.codaPiena){
      LUPRT.codaPiena=true;
      RTD._rerr="lup:pronto mai arrivato";
      try{toast("La scena del villaggio non si è caricata: controlla la rete e riapri la partita","err",3200);}catch(e){}
      try{if(RTD.ws&&RTD.ws.readyState===1)RTD.ws.send(JSON.stringify({t:"clog",at:"lupus",msg:"pronto mai arrivato: coda piena"}));}catch(e){}
    }
    return;
  }
  luprtPosta(m);
}
function luprtRicevi(m){
  var t=m.t;
  if(t==="s"){ if(m.g!=="lupus")return false; luprtGiu(m); return true; }
  if(RTD.game!=="lupus"||!LUPRT.aperto)return false;
  if(t==="chat"||t==="chat_log"){
    if(LUPRT.spec){
      if(LUPRT.specMid&&m.tid==="r:"+LUPRT.specMid){luprtGiu(m);return true;}
      if(LUPRT.specLid&&m.tid==="r:"+LUPRT.specLid){luprtGiu(luprtTifo(m));return true;}
      return false;
    }
    if(RTD.lupMid&&m.tid==="r:"+RTD.lupMid){luprtGiu(m);return true;}
    return false;
  }
  if(t==="chat_slow"){luprtGiu(m);return true;}
  if(t==="chat_no"||t==="vc_no"){luprtGiu(m);return true;}
  if(t==="vc"){
    if(LUPRT.pronto){m.rx=Date.now();luprtPosta(m);}
    return true;
  }
  if(t==="err"&&/^lup_/.test(String(m.code||""))){luprtGiu(m);return true;}
  return false;
}
window.addEventListener("message",function(ev){
  if(ev.origin!==LUPRT_ORIGIN)return;
  var d=ev.data;if(!d||d.lup===undefined)return;
  if(!LUPRT.fr||ev.source!==LUPRT.fr.contentWindow)return;
  if(d.lup==="pronto"){
    LUPRT.pronto=true;
    RTD._wsT=performance.now();
    luprtBordi();
    if(!LUPRT.aperto){luprtPosta({t:"pausa"});return;}
    var c=LUPRT.coda;LUPRT.coda=[];
    for(var i=0;i<c.length;i++)luprtGiu(c[i]);
    return;
  }
  if(d.lup==="su"){
    var o=d.m;if(!o||!LUPRT_SU[o.t]||!LUPRT.aperto)return;
    if(LUPRT.spec){
      if(o.t==="chat"&&LUPRT.specLid){rtdSend({t:"chat",x:String(o.x||"").slice(0,300),tid:"r:"+LUPRT.specLid});return;}
      if(o.t==="chat_sub"&&LUPRT.specLid){rtdSend({t:"chat_sub",tid:"r:"+LUPRT.specLid});return;}
      return;
    }
    var mid="r:"+String(RTD.lupMid||"");
    if(o.t==="act"){
      rtdSend({t:"act",a:String(o.a||"").slice(0,24),ax:luprtInt(o.ax,-1),ay:luprtInt(o.ay,-1),power:luprtInt(o.power,-1)});
      return;
    }
    if(o.t==="chat"){rtdSend({t:"chat",x:String(o.x||"").slice(0,300),tid:mid});return;}
    if(o.t==="chat_sub"){rtdSend({t:"chat_sub",tid:mid});return;}
    if(o.t==="chat_unsub"){rtdSend({t:"chat_unsub"});return;}
    if(o.t==="voce"){
      var k=luprtInt(o.k,-1),ii=luprtInt(o.i,-1);
      if(k<0||ii<0)return;
      var mm=(o.m==="m4")?"m4":((o.m==="wo")?"wo":"");
      if(!mm)return;
      var b=(typeof o.b==="string")?o.b:"";
      if(!b||b.length>12288)return;
      rtdSend({t:"voce",k:k,i:ii,m:mm,b:b,f:o.f?1:0});
      return;
    }
    return;
  }
  if(d.lup==="epilogo_fine"){
    if(LUPRT.spec){
      LUPRT.epilogoFinito=true;
      if(RTD.overTmr){clearTimeout(RTD.overTmr);RTD.overTmr=null;}
      if(typeof LUPRT.specOverFn==="function")LUPRT.specOverFn();
      return;
    }
    LUPRT.epilogoFinito=true;
    if(RTD.over&&RTD.over.game==="lupus"&&RTD.ui==="match"&&RTD.overTmr){
      clearTimeout(RTD.overTmr);RTD.overTmr=null;rtdShowOver(RTD.over);
    }
    return;
  }
  if(d.lup==="esci"){rtdBack();return;}
  if(d.lup==="err"){
    RTD._rerr="lup:"+String(d.msg||"").slice(0,60);
    try{if(RTD.ws&&RTD.ws.readyState===1)RTD.ws.send(JSON.stringify({t:"clog",at:"lupus",msg:String(d.msg||"").slice(0,300)}));}catch(e){}
    return;
  }
});
function luprtTifo(m){
  var o={},k,i,a,r,q;
  for(k in m)if(m.hasOwnProperty(k))o[k]=m[k];
  if(o.t==="chat_log"&&o.msgs instanceof Array){
    a=[];
    for(i=0;i<o.msgs.length;i++){q=o.msgs[i]||{};r={};for(k in q)if(q.hasOwnProperty(k))r[k]=q[k];r.canale="tifo";delete r.bot;delete r.tipo;a.push(r);}
    o.msgs=a;
  }else{o.canale="tifo";delete o.bot;delete o.tipo;}
  return o;
}
function luprtSpecOver(m){
  RTD.over=m;RTD.specRid=null;
  luprtGiu(m);
  var fatto=false;
  function banner(){if(fatto)return;fatto=true;LUPRT.specOverFn=null;if(RTD.over===m)rtdSpecOverLupus(m);}
  LUPRT.specOverFn=banner;
  if(LUPRT.epilogoFinito||!LUPRT.pronto){banner();return;}
  if(RTD.overTmr)clearTimeout(RTD.overTmr);
  RTD.overTmr=setTimeout(function(){RTD.overTmr=null;banner();},20000);
}
