function lcrtPosta(m){
  try{ LCRT.fr.contentWindow.postMessage({lc:"giu",m:m},LCRT_ORIGIN); }catch(e){}
}
function lcrtSenzaEventi(m){ return !!(m&&m.t==="s"&&!(m.feed&&m.feed.length)); }
function lcrtGiu(m){
  if(!LCRT.aperto||!LCRT.fr)return;
  if(LCRT.pronto){lcrtPosta(m);return;}
  var c=LCRT.coda,i;
  if(lcrtSenzaEventi(m)){
    for(i=c.length-1;i>=0;i--){ if(lcrtSenzaEventi(c[i])){c.splice(i,1);break;} }
  }
  c.push(m);
  if(c.length>LCRT_CODA_MAX){
    var k=0;
    for(i=0;i<c.length;i++){ if(c[i]&&c[i].t==="s"){k=i;break;} }
    c.splice(k,1);
    if(!LCRT.codaPiena){
      LCRT.codaPiena=true;
      RTD._rerr="lc:coda piena prima del pronto";
      try{if(RTD.ws&&RTD.ws.readyState===1)RTD.ws.send(JSON.stringify({t:"clog",at:"lastcall",msg:"coda piena prima del pronto"}));}catch(e){}
    }
  }
}
function lcrtRicevi(m){
  var t=m&&m.t;
  if(t==="s"){ if(m.g!=="lastcall")return false; lcrtGiu(m); return true; }
  if(t==="err"&&/^lc_/.test(String(m.code||""))){lcrtGiu(m);return true;}
  return false;
}
window.addEventListener("message",function(ev){
  if(ev.origin!==LCRT_ORIGIN)return;
  var d=ev.data;if(!d||typeof d!=="object"||d.lc===undefined)return;
  if(!LCRT.fr||ev.source!==LCRT.fr.contentWindow)return;
  if(d.lc==="pronto"){
    LCRT.pronto=true;
    RTD._wsT=performance.now();
    lcrtBordi();
    if(!LCRT.aperto){lcrtPosta({t:"pausa"});return;}
    var c=LCRT.coda;LCRT.coda=[];
    for(var i=0;i<c.length;i++)lcrtPosta(c[i]);
    if(LCRT.codaPiena){LCRT.codaPiena=false;if(!LCRT.spec)rtdSend({t:"rientra"});}
    return;
  }
  if(d.lc==="su"){
    var o=d.m;
    if(!o||typeof o!=="object"||o.t!=="act"||!LCRT.aperto||LCRT.spec||RTD.spec)return;
    var a=(typeof o.a==="string")?o.a:"";
    if(!Object.prototype.hasOwnProperty.call(LCRT_MOSSE,a))return;
    var ax=lcrtAx(o.ax);
    if(!ax.ok)return;
    rtdSend({t:"act",a:a,ax:ax.v,ay:lcrtInt(o.ay,null),power:lcrtInt(o.power,null)});
    return;
  }
  if(d.lc==="fine_scena"){
    LCRT.fineScena=true;
    if(LCRT.spec&&RTD.spec&&RTD.over&&RTD.over.game==="lastcall"&&RTD.ui==="match"){
      if(RTD.overTmr){clearTimeout(RTD.overTmr);RTD.overTmr=null;}
      rtdSpecOver(RTD.over);return;
    }
    if(RTD.over&&RTD.over.game==="lastcall"&&RTD.ui==="match"&&RTD.overTmr){
      clearTimeout(RTD.overTmr);RTD.overTmr=null;rtdShowOver(RTD.over);
    }
    return;
  }
  if(d.lc==="esci"){
    if(LCRT.spec||RTD.spec){rtdSpecExit();return;}
    if(RTD.over&&RTD.over.game==="lastcall"&&RTD.ui==="match"){
      if(RTD.overTmr){clearTimeout(RTD.overTmr);RTD.overTmr=null;}
      rtdShowOver(RTD.over);return;
    }
    rtdBack();return;
  }
  if(d.lc==="err"){
    RTD._rerr="lc:"+String(d.msg||"").slice(0,60);
    try{if(RTD.ws&&RTD.ws.readyState===1)RTD.ws.send(JSON.stringify({t:"clog",at:"lastcall",msg:String(d.msg||"").slice(0,300)}));}catch(e){}
    return;
  }
});
function rtdShowOverLastcall(m){
  var pratica=!!(m.practice||RTD.practice);
  var gratis=!!m.gratis||!(Number(m.pot_eur)>0);
  var chi=(m.winner!=null)?String(m.winner_name||rtdName(m.winner)||""):String(m.winner_name||"");
  var h;
  if(m.annullata){
    TWS.play("lose");
    h='<div style="font-size:44px;">🧯</div><div class="tw-lose-t">TAVOLO ANNULLATO</div>'
     +'<div class="tw-ov-sub">'+((pratica||gratis)?"La partita non è arrivata in fondo.":"La partita non è arrivata in fondo: posta rimborsata.")+'</div>';
    h+='<div class="tw-ov-btns"><button class="action-btn gold" onclick="rtdAgain()">'+LBL_AGAIN+'</button>'
     +'<button class="action-btn" onclick="rtdAgain();go(&quot;duel&quot;)">⚔️ PvP ARENA</button></div>';
    rtdOv(h,true);
    rtdShowLobby(true);
    if(typeof loadBalance==="function")loadBalance();
    return;
  }
  var riga=m.you_won?'<div class="tw-ov-sub">SEI L’ULTIMO IN PIEDI</div>'
    :(chi?'<div class="tw-ov-sub"><b>'+trnEsc(chi)+'</b> resta in piedi</div>':'<div class="tw-ov-sub">PARTITA FINITA</div>');
  if(pratica){
    TWS.play(m.you_won?"win":"lose");
    h=riga.replace('class="tw-ov-sub"','class="tw-ov-sub" style="margin-bottom:6px;color:#f3d28a;"')
     +practiceOverHTML(!!m.you_won,"rtdPracAgain","rtdPracToReal");
    rtdOv(h,true);
    RTD.ui="";
    rtdShowLobby(true);
    return;
  }
  var premio=Number((m.your_cut_eur!=null)?m.your_cut_eur:m.prize_eur)||0;
  if(m.you_won){
    TWS.play("win");
    try{tg.HapticFeedback&&tg.HapticFeedback.notificationOccurred("success");}catch(e){}
    var coins="";for(var i=0;i<12;i++){coins+='<span class="twr-coin" style="left:'+(4+Math.random()*92)+'%;animation-delay:'+(Math.random()*1.6)+'s;">🪙</span>';}
    h='<div class="twr-rain">'+coins+'</div>'
     +'<div style="font-size:46px;" class="twr-trophy">🏆</div>'
     +'<div class="tw-win-t">HAI VINTO</div>'
     +riga
     +(gratis?"":'<div class="tw-win-prize">+€ '+lupEuro(premio)+'</div>')
     +(gratis?"":'<div class="tw-ov-sub">Piatto € '+lupEuro(m.pot_eur)+'</div>');
  }else{
    TWS.play("lose");
    h='<div style="font-size:44px;">💀</div><div class="tw-lose-t">SCONFITTA</div>'
     +riga
     +(gratis?"":'<div class="tw-ov-sub">Piatto € '+lupEuro(m.pot_eur)+'</div>');
  }
  h+='<div class="tw-ov-btns"><button class="action-btn gold" onclick="rtdAgain()">'+LBL_AGAIN+'</button>'
   +'<button class="action-btn" onclick="rtdAgain();go(&quot;duel&quot;)">⚔️ PvP ARENA</button></div>';
  rtdOv(h,true);
  rtdShowLobby(true);
  if(typeof loadBalance==="function")loadBalance();
}
