      var qi=hard?inn:lin;
      c.beginPath();
      c.moveTo(ed[si][0],ed[si][1]);c.lineTo(ed[sn][0],ed[sn][1]);
      c.lineTo(qi[sn][0],qi[sn][1]);c.lineTo(qi[si][0],qi[si][1]);
      c.closePath();
