function burHostCerim(g, s, now, w, hh){
  var C=BUR.cerim, el, k, vv;
  if(!C||!s.cerim)return 0;
  el=now-(s.cerim.t0||now);
  if(el<0)el=0;
  if(C.attesa(s.cerim.e, el)<=0){ s.cerim=null; return 0; }
  k=C.faseOra(C.tempoOra(s.cerim.e, el)).k;
  vv=C.aggVoceCambio(s.cerim.fase, k);
  s.cerim.fase=k;
  if(vv&&typeof burSnd==='function') burSnd(vv.n, vv.o);
  C.disegna(g, s.cerim.e, el, w, hh);
  return 1;
}
