function burSnapCheck(m){
  var s=burPonteSt(), ev, i, e, v;
  if(!m)return;
  v=burHostVista(m);
  burPonteProtetto(s.pt,'snap',function(){
    return burPonteSnap(s.pt, v, burHostOra());
  });
  burPonteProtetto(s.pt,'voli-fatti',function(){
    burHostVoli(s.prec, v);
    s.prec=v;
    return 1;
  });
  ev=s.pt.eventi;
  if(ev&&ev.length){
    for(i=0;i<ev.length;i++){
      e=ev[i];
      if(e.tipo==='rifiutata'){
        burHostSuono('errore');
        burHostVibra('medium');
        burHostDillo((e.dalMotore&&e.perche)?e.perche
                     :("il server non ha accettato: "+(e.a||'la mossa')));
      }
    }
    s.pt.eventi=[];
  }
}
