var PG_LAG  = 0.080;
var PG_SPD0 = 5.2;
var PG_SPD1 = 22.0;
var PG_NOTE = [220, 261.63, 293.66, 329.63, 392, 440,
               523.25, 587.33, 659.25, 783.99, 880];
var PGX = {at: 0};
var PG_COST = {hit:2, hitcan:3, wall:1, goal:4, save:4, pip:2, mod:3, tick:2, go:3};
var PG_GAP  = {hit:50, hitcan:120, wall:45, goal:350, save:350,
               pip:300, mod:200, tick:300, go:500};
var PG_PRIO = {goal:0, save:0, hitcan:1, mod:1, go:1, tick:1, hit:2, pip:3, wall:3};
var PG_CLSCAP = {hit:2, wall:2};
var PG_LITE_LV = 2;
function pgLite(){ try{ return !!(RTD && RTD.lite); }catch(e){ return false; } }
function pgT(o){ o.at=(o.at||0)+PGX.at; TWS.tone(o); }
function pgN(o){ if(pgLite())return; o.at=(o.at||0)+PGX.at; TWS.noise(o); }
