    S.part.push({x:x,y:y,vx:Math.cos(a)*v,vy:Math.sin(a)*v-(gr>0?vel*0.5:0),t:0,max:vita*(0.6+Math.random()*0.7),
      col:cols[i%cols.length],g:gr,sz:sz*(0.6+Math.random()*0.8)});
