    ctx.globalAlpha=al;ctx.lineWidth=fs*0.1;ctx.strokeStyle='rgba(0,0,0,.6)';ctx.strokeText(b.txt,0,0,w*0.95);
    ctx.fillStyle=b.col;ctx.fillText(b.txt,0,0,w*0.95);
    ctx.globalCompositeOperation='lighter';ctx.globalAlpha=al*0.35;ctx.fillText(b.txt,0,0,w*0.95);ctx.globalCompositeOperation='source-over';
    if(b.sub){ctx.globalAlpha=al*0.9;ctx.font='800 '+(fs*0.34)+'px Inter, system-ui, sans-serif';ctx.fillStyle='#e8ecf5';ctx.fillText(b.sub,0,fs*0.72,w*0.9);}
