function dmFlip(i,seat){return seat===1?63-i:i;}
function dmGioco(g){return g==='dama'||g==='damaru';}
function dmTap(pxy){
  var raw=RTD.lastRaw;if(!raw||!dmGioco(raw.g))return;
  if(raw.turn!==RTD.myId){TWS.play('lose',0.2);return;}
  var seat=raw.seat||0;
  var c=Math.floor(pxy.x*8),r=Math.floor(pxy.y*8);
  if(c<0||c>7||r<0||r>7)return;
  var vis=r*8+c;
  var cell=dmFlip(vis,seat);
  var mv=raw.mv||[];
  var sel=RTD._sc.dmSel;
  if(sel!=null){
    for(var i=0;i<mv.length;i++){
      if(mv[i][0]===sel&&mv[i][1]===cell){
        rtdSend({t:'act',a:'shot',ax:sel,ay:cell});
        RTD._sc.dmSel=null;TWS.play('pock',0.6);
        return;
      }
    }
  }
  var can=false;
  mv.forEach(function(m){if(m[0]===cell)can=true;});
  if(can){RTD._sc.dmSel=cell;TWS.play('pick',0.5);}
  else{RTD._sc.dmSel=null;}
}
