  if(b.sel!=null&&b.sel!==-2&&b.cand&&b.cand.length){
    var hit=null;
    if(p.punta!=null)for(i=0;i<b.cand.length;i++){if(b.cand[i].kind==='point'&&b.cand[i].dst===p.punta){hit=b.cand[i];break;}}
    if(!hit&&p.fuori){var bo=[];for(i=0;i<b.cand.length;i++)if(b.cand[i].kind==='bearoff')bo.push(b.cand[i]);
      if(bo.length){hit=bo[0];if(p.dado!=null)for(i=0;i<bo.length;i++)if(bo[i].die===p.dado)hit=bo[i];}}
    if(hit){rtdSend({t:'act',a:'shot',ax:b.sel,ay:hit.die});TWS.play('pick');bgSent();b.sel=-2;b.cand=[];return;}
  }
  if(p.niente||p.fuori){b.sel=-2;b.cand=[];return;}
  if(mv.length===1){rtdSend({t:'act',a:'shot',ax:mv[0][0],ay:mv[0][1]});TWS.play('pick');bgSent();b.sel=-2;b.cand=[];return;}
  var src=p.barra?-1:(p.punta!=null?p.punta:null),bar=raw.bar||[0,0];
  if(src==null){b.sel=-2;b.cand=[];return;}
  if((bar[seat]||0)>0)src=-1;
  var cand=bgCands(raw,src,seat);
  if(!cand.length){TWS.play('bgno',0.8);b.sel=-2;b.cand=[];return;}
  if(cand.length===1){rtdSend({t:'act',a:'shot',ax:src,ay:cand[0].die});TWS.play('pick');bgSent();b.sel=-2;b.cand=[];return;}
  b.sel=src;b.cand=cand;TWS.play('pick');grHaptic('sel');
