        ctx.beginPath();
        ctx.moveTo(p.x-G.R*0.8,p.y-G.R*0.8);ctx.lineTo(p.x+G.R*0.8,p.y+G.R*0.8);
        ctx.moveTo(p.x+G.R*0.8,p.y-G.R*0.8);ctx.lineTo(p.x-G.R*0.8,p.y+G.R*0.8);
