  var cp={x:mx+(G.cx-mx)*0.20,
          y:my+(G.cy-my)*0.20};
  return {ax:ax,ay:ay,bx:tipx,by:tipy,cp:cp,lw:lw,aw:aw,pl:pl,
          an:Math.atan2(tipy-cp.y,tipx-cp.x)};
