    s=i/n;m=1-s;
    x=m*m*C.ax+2*m*s*C.cp.x+s*s*C.bx;
    y=m*m*C.ay+2*m*s*C.cp.y+s*s*C.by;
    if(i>0)out.push({x:Math.min(px,x)-r,y:Math.min(py,y)-r,
                     w:Math.abs(x-px)+r*2,h:Math.abs(y-py)+r*2});
