  for(j=0;j<3;j++){
    vx=C.bx+VT[j][0]*ca-VT[j][1]*sa;
    vy=C.by+VT[j][0]*sa+VT[j][1]*ca;
    if(vx<tx0)tx0=vx;if(vy<ty0)ty0=vy;if(vx>tx1)tx1=vx;if(vy>ty1)ty1=vy;
  }
