    if(prev&&T<prev.time-500){S.h=[];prev=null;S.off=null;S.fine=null;SNW.pend=[];}
    S.off=(S.off==null||o<S.off)?o:(S.off+(o-S.off)*0.01);
    var passo=false;
    if(prev){for(var id in m.b){var a=m.b[id][0],b=prev.b[id]&&prev.b[id][0];if(!b||a[0]!==b[0]||a[1]!==b[1]){passo=true;break;}}}
