      x.shadowColor='rgba(255,77,109,.9)';x.strokeStyle='rgba(255,120,150,.95)';x.lineWidth=Math.max(2,c*0.16);
      var L=c*2.2,a0=ox-2,b0=oy-2,a1=ox+GW*c+2,b1=oy+GH*c+2;x.beginPath();
