      x.font='bold '+Math.round(c*2.1)+'px "Russo One",sans-serif';x.fillText('SNAKE',ox+GW*c/2,oy+GH*c*0.47);
      x.fillText('ARENA',ox+GW*c/2,oy+GH*c*0.47+c*2.3);x.restore();
