function golfEmit(x,y,vx,vy,life,col,r,grav){var p=golfPool();for(var i=0;i<p.length;i++){var q=p[i];if(!q.a){q.a=true;q.x=x;q.y=y;q.vx=vx;q.vy=vy;q.life=life;q.max=life;q.col=col;q.r=r;q.g=grav||0;return;}}}
