function mgDrawBoxer(ctx,px,py,S,flip,col,act,actT,hp,now){
  ctx.save();
  ctx.translate(px,py);
  if(flip)ctx.scale(-1,1);
  var sway=Math.sin(now/260)*S*0.03;
  var lunge=0,guard=0,duck=0;
  if(act==='jab')lunge=S*0.5*(1-Math.min(1,actT/0.18));
  else if(act==='hook')lunge=-S*0.16+S*0.05*Math.sin(now/50);
  else if(act==='dodge')duck=S*0.42;
  else if(act==='block')guard=1;
  var koLean=hp<=25?0.12:0;
  ctx.rotate(koLean);
  ctx.fillStyle='rgba(0,0,0,.4)';
  ctx.beginPath();ctx.ellipse(0,2,S*0.55,S*0.14,0,0,6.283);ctx.fill();
  ctx.strokeStyle='#20242e';ctx.lineWidth=S*0.15;ctx.lineCap='round';
  ctx.beginPath();ctx.moveTo(-S*0.05,-S*0.5+duck*0.4);ctx.lineTo(-S*0.28,0);ctx.stroke();
  ctx.beginPath();ctx.moveTo(S*0.1,-S*0.5+duck*0.4);ctx.lineTo(S*0.3,0);ctx.stroke();
  ctx.fillStyle='#e8b88a';
  ctx.beginPath();
  if(ctx.roundRect)ctx.roundRect(-S*0.24+sway,-S*1.02+duck,S*0.5,S*0.42,S*0.1);else ctx.rect(-S*0.24+sway,-S*1.02+duck,S*0.5,S*0.42);
  ctx.fill();
  ctx.fillStyle=col;
  ctx.beginPath();
  if(ctx.roundRect)ctx.roundRect(-S*0.24+sway,-S*0.64+duck,S*0.5,S*0.24,S*0.06);else ctx.rect(-S*0.24+sway,-S*0.64+duck,S*0.5,S*0.24);
  ctx.fill();
  var backX=act==='hook'?-S*0.5:S*0.05;
  ctx.strokeStyle='#d9a066';ctx.lineWidth=S*0.13;
  ctx.beginPath();ctx.moveTo(-S*0.1+sway,-S*0.9+duck);
  ctx.lineTo(backX+sway,-S*(0.95+(act==='hook'?0.2:0))+duck);ctx.stroke();
  ctx.fillStyle='#c0392b';
  ctx.beginPath();ctx.arc(backX+sway,-S*(0.95+(act==='hook'?0.2:0))+duck,S*0.15,0,6.283);ctx.fill();
  var frontX=S*0.36+lunge,frontY=-S*(guard?1.12:0.98)+duck;
  ctx.strokeStyle='#e8b88a';ctx.lineWidth=S*0.13;
  ctx.beginPath();ctx.moveTo(S*0.16+sway,-S*0.92+duck);ctx.lineTo(frontX+sway,frontY);ctx.stroke();
  ctx.fillStyle='#c0392b';
  ctx.beginPath();ctx.arc(frontX+sway,frontY,S*0.16,0,6.283);ctx.fill();
  ctx.fillStyle='#e8b88a';
  ctx.beginPath();ctx.arc(S*0.06+sway,-S*(1.22-koLean*0.3)+duck,S*0.2,0,6.283);ctx.fill();
  ctx.fillStyle=col;
  ctx.beginPath();ctx.arc(S*0.04+sway,-S*1.28+duck,S*0.21,Math.PI*0.85,Math.PI*1.95);ctx.fill();
  ctx.fillStyle='#241a12';
  ctx.beginPath();ctx.arc(S*0.15+sway,-S*1.23+duck,S*0.03,0,6.283);ctx.fill();
  ctx.restore();
}
