  if(ctx.setLineDash)ctx.setLineDash(BLG_ND);
  if(!chg&&!armed)return;
  var a=blgAimDir(afx,afy),adx=a[0],ady=a[1];
  var chu=(armed&&!chg)?(BLG.armPw||0):ch;
  var pw=Math.min(1,BLG_CHGMIN+0.75*Math.max(0,Math.min(1,chu)));
