  if(ady>1e-6)L=Math.min(L,(H-by)/ady);else if(ady<-1e-6)L=Math.min(L,(0-by)/ady);
  if(!(L>0.15))return;
  var ex=bx+adx*L,ey=by+ady*L;
  var gxT=(BLG.team===1)?0:W,gy0=H/2-gw/2,gy1=H/2+gw/2;
  var onGoal=(Math.abs(ex-gxT)<0.02&&ey>gy0+0.13&&ey<gy1-0.13);
  var q0=blgW2S(bx,by),sx0=q0.x,sy0=q0.y;
