function dbEd3dApri(){
  if(DB3.mai||DB3.fr)return;
  try{if(!blg3dBase())return;}catch(e){return;}
  var cv=document.getElementById('db-ed-cv');if(!cv||!cv.parentNode)return;
  var st=cv.parentNode;
  try{
    if(getComputedStyle(st).position==='static')st.style.position='relative';
    var h=document.createElement('div');h.id='db3d-host';
    h.style.cssText='position:absolute;left:0;top:0;right:0;bottom:0;display:none;overflow:hidden;border-radius:inherit;touch-action:none;';
    var fr=document.createElement('iframe');fr.setAttribute('scrolling','no');fr.setAttribute('title','calciatore 3d');
    fr.style.cssText='width:100%;height:100%;border:0;display:block;background:transparent;';
    fr.src=blg3dSrc();
    h.appendChild(fr);st.appendChild(h);
    DB3.fr=fr;DB3.host=h;DB3.t0=Date.now();DB3.ok=false;DB3.g=null;
    DB3.tim=setTimeout(dbEd3dProva,80);
  }catch(e){dbEd3dGiu('apri: '+((e&&e.message)||e));}
}
function dbEd3dProva(){
  DB3.tim=null;if(!DB3.fr)return;
  var g=null;try{g=DB3.fr.contentWindow&&DB3.fr.contentWindow.BLG3D;}catch(e){g=null;}
  if(g&&g.errore)return dbEd3dGiu('ponte: '+g.errore);
  if(g&&g.pronto&&!g.vetrina)return dbEd3dGiu('pagina 3D senza vetrina');
  if(g&&g.pronto&&g.vetrina){
    DB3.g=g;var ok=false;
    try{ok=g.vetrina.avvia({look:dbEd3dLookObj(),sfondo:'#0a1220'});}catch(e){return dbEd3dGiu('avvia: '+((e&&e.message)||e));}
    if(!ok)return dbEd3dGiu('avvia: '+(g.vetrina.errore||'rifiutato'));
    return dbEd3dAspetta();
  }
  if(Date.now()-DB3.t0>BLG3D_MAX_ATTESA)return dbEd3dGiu('3D non pronto');
  DB3.tim=setTimeout(dbEd3dProva,80);
}
function dbEd3dAspetta(){
  DB3.tim=null;if(!DB3.g)return;
  var v=DB3.g.vetrina;
  if(v.errore)return dbEd3dGiu(v.errore);
  if(v.fotogrammi>0)return dbEd3dMostra();
  if(Date.now()-DB3.t0>BLG3D_MAX_ATTESA+BLG3D_MAX_CARICA)return dbEd3dGiu('nessun fotogramma');
  DB3.tim=setTimeout(dbEd3dAspetta,60);
}
function dbEd3dMostra(){
  DB3.ok=true;
  if(DB3.host)DB3.host.style.display='block';
  var cv=document.getElementById('db-ed-cv');if(cv)cv.style.visibility='hidden';
  try{blgBeaconStep('dbed3d',{ms:Date.now()-DB3.t0});}catch(e){}
  DB3.vig=setInterval(function(){
    if(!DB3.ok)return;
    if(!DB3.host||!document.body.contains(DB3.host)){dbEd3dChiudi();return;}
    var v=DB3.g&&DB3.g.vetrina;
    if(!v)return dbEd3dGiu('vetrina sparita');
    if(v.errore)return dbEd3dGiu(v.errore);
    if(DB3.g.perso)return dbEd3dGiu('contesto WebGL perso');
  },700);
}
function dbEd3dGiu(p){
  DB3.err=String(p);DB3.mai=true;
  try{console.warn('[personalizzatore 3D] torno al 2D: '+DB3.err);}catch(e){}
  try{blgBeaconStep('dbed3dgiu',{d:DB3.err.slice(0,120)});}catch(e){}
  dbEd3dChiudi();
  var cv=document.getElementById('db-ed-cv');if(cv)cv.style.visibility='visible';
}
function dbEd3dChiudi(){
  if(DB3.tim){clearTimeout(DB3.tim);DB3.tim=null;}
  if(DB3.vig){clearInterval(DB3.vig);DB3.vig=null;}
  try{if(DB3.g&&DB3.g.vetrina)DB3.g.vetrina.ferma();}catch(e){}
  try{if(DB3.host&&DB3.host.parentNode)DB3.host.parentNode.removeChild(DB3.host);}catch(e){}
  DB3.fr=null;DB3.g=null;DB3.host=null;DB3.ok=false;
}
function dbEd3dLook(){
  if(!DB3.ok||!DB3.g||!DB3.g.vetrina)return;
  try{DB3.g.vetrina.look(dbEd3dLookObj());}catch(e){dbEd3dGiu('look: '+((e&&e.message)||e));}
}
var DB_ED={look:null,tm:0,raf:null,t0:0,bgCv:null,conf:null,kickCyc:-1,roarCyc:-1,bIdx:-1};
