function dbEdGrid(){
  var host=document.getElementById('db-skins');
  if(!host)return;
  if(typeof COS==='undefined'||!COS.data||!COS.data.catalog||!COS.data.catalog.calcio){
    host.innerHTML='<div style="grid-column:1/-1;text-align:center;color:var(--txt3);font-size:10px;padding:14px;">⏳ Caricamento skin…</div>';
    return;
  }
  var cat=COS.data.catalog.calcio,prog=COS.data.progress||{};
  var unl=(COS.data.unlocked&&COS.data.unlocked.calcio)||[];
  var eq=(COS.data.equipped&&COS.data.equipped.calcio)||null;
  var seen=dbSeen(),html='';
  cat.forEach(function(cd){
    var goal=cd.challenge.goal,p=prog[cd.challenge.stat]||0,pct=Math.min(100,Math.round(p/goal*100));
    var isU=unl.indexOf(cd.id)>=0,isE=(eq===cd.id),claim=(!isU&&p>=goal);
    var isNew=claim||(isU&&!isE&&seen.indexOf(cd.id)<0);
    var btn;
    if(isE)btn='<button class="db-sk-btn" disabled style="background:linear-gradient(145deg,#39ff14,#10b981);color:#000;">EQUIPAGGIATA ✓</button>';
    else if(isU)btn='<button class="db-sk-btn" onclick="dbCosEquip(\''+cd.id+'\')" style="background:linear-gradient(145deg,#ffd700,#ff9500);color:#000;">EQUIPAGGIA</button>';
    else if(claim)btn='<button class="db-sk-btn" onclick="dbCosClaim(\''+cd.id+'\')" style="background:linear-gradient(145deg,#22d3ee,#a855f7);color:#000;">RISCUOTI 🎉</button>';
    else btn='<button class="db-sk-btn" disabled style="background:rgba(255,255,255,.06);color:#71717a;">🔒 BLOCCATA</button>';
    html+='<div class="db-sk-card rar-'+cd.rarity+'">'
      +(isNew?'<span class="db-sk-new">NEW</span>':'')
      +(!isU&&!claim?'<span class="db-sk-lock">🔒</span>':'')
      +'<canvas id="dbsk_'+cd.id+'" width="64" height="58" style="width:64px;height:58px;"></canvas>'
      +'<div class="db-sk-name">'+cd.name+'</div>'
      +'<div class="db-sk-req">'+(isU?cd.desc:dbReqLabel(cd))+'</div>'
      +'<div class="db-sk-bar"><div class="db-sk-fill" style="width:'+(isU?100:pct)+'%;"></div></div>'
      +'<div class="db-sk-req" style="margin-top:2px;">'+(isU?'SBLOCCATA':Math.min(p,goal)+' / '+goal)+'</div>'
      +'<div>'+btn+'</div></div>';
  });
  host.innerHTML=html;
  cat.forEach(function(cd){
    var cv=document.getElementById('dbsk_'+cd.id);
    if(cv)dbSkinPrev(cv,cd.look_patch,unl.indexOf(cd.id)<0);
  });
}
function dbSkinPrev(cv,patch,silhouette){
  var ctx=cv.getContext('2d');
  ctx.clearRect(0,0,cv.width,cv.height);
  var b=DB_ED.look||derbyLook(),lk={},k;
  for(k in b)lk[k]=b[k];
  if(patch)for(k in patch)lk[k]=patch[k];
  lk=blgNormLook(lk);
  var spr=blgSprite(DB_ED.tm,false,lk),sz=spr.width;
  if(silhouette){
    var tc2=document.createElement('canvas');tc2.width=sz;tc2.height=sz;
    var t2=tc2.getContext('2d');
    t2.drawImage(spr,0,0);
    t2.globalCompositeOperation='source-in';
    t2.fillStyle='#181f2c';t2.fillRect(0,0,sz,sz);
    ctx.globalAlpha=0.9;ctx.drawImage(tc2,0,0,sz,sz,0,-4,64,64);ctx.globalAlpha=1;
  }else ctx.drawImage(spr,0,0,sz,sz,0,-4,64,64);
}
function dbCosClaim(id){cosClaim('calcio',id);}
function dbCosEquip(id){dbSeenAdd(id);cosEquip('calcio',id);}
function dbEdOnCos(mode){
  if(mode!=='calcio')return;
  if(!document.getElementById('db-ed-cv'))return;
  DB_ED.look=derbyLook();
  var secs=document.getElementById('db-secs');
  if(secs)secs.innerHTML=dbEdSections();
  dbEdGrid();
  dbEdMark();
}
