function sclEsc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function sclIcat(){
  var c=null;
  try{if(typeof SC!=='undefined'&&SC&&SC.icat)c=SC.icat;}catch(e){}
  if(!c){try{var s=localStorage.getItem('gb_dp_icat');if(s)c=JSON.parse(s);}catch(e2){c=null;}}
  if(!c||!c.f||!c.f.length||!c.it||!c.it.length)c=SCL_ICAT_FB;
  return c;
}
function sclIcatSave(c){
  try{if(c&&c.f&&c.it)localStorage.setItem('gb_dp_icat',JSON.stringify(c));}catch(e){}
}
function sclIcatIx(cat){var ix={},i;for(i=0;i<cat.f.length;i++)ix[cat.f[i]]=i;return ix;}
function sclNfmt(v){var n=Number(v)||0;return (n===Math.round(n))?String(Math.round(n)):String(n);}
function sclIcatTxt(row,ix,fld){
  var s=String(row[fld==='w'?ix.what:ix.how]||'');
  if(window.GB_LANG!=='en')return s;
  var en=SCL_ICAT_EN[row[ix.id]|0];en=en?en[fld]:null;
  if(!en)return s;
  var nums=s.match(/\d+(?:\.\d+)?/g)||[];
  var out=en.replace(/\$([0-9])/g,function(m,d){var i=(+d)-1;return (i>=0&&i<nums.length)?nums[i]:m;});
  return (out.indexOf('$')>=0)?s:out;
}
