  if(ge===1)return '<div class="dpt-pv g1"><i class="me"></i><i class="gr"></i><i class="blk"></i></div>';
  if(ge===2)return '<div class="dpt-pv g2"><i class="me"></i><i class="tg"></i><i class="sw"></i></div>';
  if(ge===3)return '<div class="dpt-pv g3"><i class="rg"></i><i class="rg b"></i><i class="me"></i></div>';
  return '<div class="dpt-pv g0"><i class="me"></i><i class="ln"></i><i class="tg"></i><i class="dart"></i></div>';
