  var col=(typeof sclFamCol==='function')?sclFamCol(id):'#94a3b8';
  var nm=it?(it.ico+' '+it.nm):((row[ix.em]||'')+' '+(row[ix.nm]||''));
  var rng=Number(row[ix.rng])||0,ocd=Number(row[ix.ocd])||0,cd=Number(row[ix.cd])||0,ttl=Number(row[ix.ttl])||0;
  var ry=row[ix.ry]||[];
