  var h='<div class="dpt-it" style="--ic:'+col+';">'
    +'<div class="dpt-ith"><b>'+sclEsc(nm)+'</b>'+dual+'</div>'
    +'<div class="dpt-mid">'+sclTutPrev(row[ix.ge]|0,id)+'<div class="dpt-st">'
    +sclTutChip('USI',sclNfmt(row[ix.us]))
    +(rng>0?sclTutChip('PORTATA (celle)',sclNfmt(rng)):'')
    +sclTutChip('RICARICA (s)',sclNfmt(ocd>0?ocd:cd))
    +(ttl>0?sclTutChip('DURA (s)',sclNfmt(ttl)):'')
