function dpaPat(c,n){
  var im=dpaImg(n);if(!im)return null;
  var k=c.__dpa||(c.__dpa={});
  if(k[n]===undefined)k[n]=c.createPattern(im,'repeat');
  return k[n];
}
function dpaBody(c,xx,yy,w,h,CB,sec,oneway){
  var p=dpaPat(c,oneway?'mat':'mat2');
  if(p){c.save();c.fillStyle=p;c.fillRect(xx,yy,w,h);
        c.globalCompositeOperation='multiply';
        c.fillStyle='rgba(26,18,14,.62)';c.fillRect(xx,yy,w,h);
        c.restore();}
  else{c.fillStyle=DPA.corpo;c.fillRect(xx,yy,w,h);}
  if(oneway){
    c.fillStyle='rgba(0,0,0,.40)';
    c.fillRect(xx+w*0.30,yy,Math.max(1.5,CB*0.045),h);
    c.fillRect(xx+w*0.66,yy,Math.max(1.5,CB*0.045),h);
    var hr=Math.max(2.5,CB*0.10);
    c.fillStyle=DPA.rim+'0.85)';c.fillRect(xx,yy+h-hr,w,hr);
    c.fillStyle=DPA.rim+'0.30)';c.fillRect(xx,yy+h-hr*2.1,w,hr*1.1);
    c.fillStyle='rgba(255,240,210,.55)';c.fillRect(xx,yy+h-Math.max(1.5,CB*0.03),w,Math.max(1.5,CB*0.03));
  }else{
    c.fillStyle=DPA.rim+'0.22)';
    c.fillRect(xx+w*0.18,yy+h*0.30,Math.max(1.5,CB*0.03),h*0.52);
    c.fillRect(xx+w*0.62,yy+h*0.16,Math.max(1.5,CB*0.03),h*0.40);
  }
}
