  SC.aimOn=1;SC.aimT0=now;SC.aimSentT=now;SC.aimRingQ=-1;
  SC.aimSx=t?(t.clientX||0):0;SC.aimSy=t?(t.clientY||0):0;
  SC.aimVx=0;SC.aimVy=0;SC.aimMaxDp=0;
  SC.aimCancel=(SCL_RANGE[SC.myItem]||0)>0?1:0;
