  SC.aimCancel=(rng>0&&dp<=24)?1:0;
  var capPx=Math.min(90,rng*14),upx=Math.min(dp,capPx);
  if(dp>0.001){SC.aimVx=(dxp/dp)*upx/14;SC.aimVy=-(dyp/dp)*upx/14;}
  else{SC.aimVx=0;SC.aimVy=0;}
