  var rgx0=document.getElementById('arc-aimx');
  if(rgx0)rgx0.style.display='none';
  SC.aimRingQ=-1;
  if(RTD.game!=='scalata'||RTD.ui!=='match'||RTD.spec)return;
  if(wasAim&&cancel){rtdSend({t:'act',a:'unshield'});
    var _hold=performance.now()-_dn0;
    if(_hold<260&&(SC.aimMaxDp||0)<12)rtdStamp('TIENI PREMUTO E TRASCINA','#38bdf8',true);
    else rtdStamp('ANNULLATO','#94a3b8',true);
    return;}
  var ax,ay;
  if(wasAim&&(SC.aimVx||SC.aimVy)){ax=SC.aimVx;ay=SC.aimVy;}
  else{ax=RTD.joy.on?RTD.joy.mx:0;ay=RTD.joy.on?-RTD.joy.my:0;}
  if(SC.myItem>=8&&SC.myItem<=12&&wasAim&&SC.snapDrag&&performance.now()-(SC.snapT||0)<250){
    var _sg=(ax>=0)?1:-1,_gx=SC.snapGx-SC.myX+0.25*_sg,_gy=SC.snapGy-SC.myY;
    if(((_gx>=0)?1:-1)===_sg&&Math.hypot(_gx,_gy)<=(SCL_RANGE[SC.myItem]||0)-0.05){ax=_gx;ay=_gy;}
  }
