  if(nw-(SC.hsW||0)>1000){if((SC.hsN|0)>(SC.hsPk|0))SC.hsPk=SC.hsN|0;SC.hsN=0;SC.hsW=nw;}
  SC.hsN=(SC.hsN|0)+1;
