window.sclVoStat=function(){
  if(!window.SC||!SC.voH)return 'nessuna misura';
  var n=SC.voN||1,acc=0,p99=200,i,over=0;
  for(i=0;i<20;i++){acc+=SC.voH[i];if(acc/n>=0.99){p99=i*10+10;break;}}
  for(i=15;i<20;i++)over+=SC.voH[i];
  return 'vo p99='+p99+'ms  max='+Math.round(SC.voMax||0)+'ms  oltre150='
        +((over/n)*100).toFixed(2)+'%  hitstop-picco='+(SC.hsPk|0)+'/s  fotogrammi='+n;
};
var SCL_SHK_CAP=11;
var SCL_SHK={
  press: {dur:230,amp:9.0,f:34,dx:0,dy:1,rum:0},
  cannon:{dur:280,amp:7.0,f:26,dx:1,dy:0,rum:0},
  crush: {dur:900,amp:4.5,f:11,dx:0,dy:0,rum:1},
  spike: {dur:150,amp:4.0,f:44,dx:0,dy:1,rum:0},
  laser: {dur:120,amp:2.6,f:52,dx:1,dy:0,rum:0},
  wall:  {dur:260,amp:5.5,f:24,dx:1,dy:0,rum:0},
  graze: {dur:110,amp:2.4,f:58,dx:0,dy:0,rum:1},
  rumble:{dur:300,amp:3.0,f:9,dx:0,dy:0,rum:1}
};
function sclShake(kind,vol,dx,dy){
  var d=SCL_SHK[kind];if(!d)return;
  var amp=Math.min(SCL_SHK_CAP,d.amp*(vol==null?1:vol));
  var s=SC.shk,now=performance.now();
  if(s.dur>0&&now-s.t0<s.dur){
    var res=s.amp*(1-(now-s.t0)/s.dur);
    if(res>=amp)return;
  }
  s.t0=now;s.dur=d.dur;s.amp=amp;s.f=d.f;s.rum=d.rum;
  s.dx=(dx!=null?dx:d.dx);s.dy=(dy!=null?dy:d.dy);
  var m=Math.hypot(s.dx,s.dy);
  if(m>0.001){s.dx/=m;s.dy/=m;}
  if(typeof sclDuck==='function')
    sclDuck(Math.min(0.55,0.18+0.045*amp),Math.max(220,Math.min(520,d.dur)));
}
function sclDrawLadder(ctx,cell,hpx,hard){
  var rw=cell*0.30;
  ctx.strokeStyle=hard?'#fca5a5':'#facc15';ctx.lineWidth=Math.max(2.5,cell*0.1);
  ctx.beginPath();ctx.moveTo(-rw,0);ctx.lineTo(-rw,-hpx);ctx.moveTo(rw,0);ctx.lineTo(rw,-hpx);ctx.stroke();
  ctx.strokeStyle=hard?'#f87171':'#eab308';ctx.lineWidth=Math.max(2,cell*0.075);
  var rungs=Math.max(2,Math.round(hpx/cell));
  for(var rr2=0;rr2<rungs;rr2++){var ry=-(rr2+0.5)*(hpx/rungs);ctx.beginPath();ctx.moveTo(-rw,ry);ctx.lineTo(rw,ry);ctx.stroke();}
  ctx.strokeStyle='rgba(255,255,255,.8)';ctx.setLineDash(SCL_DSH);ctx.lineWidth=Math.max(1.4,cell*0.045);
  ctx.strokeRect(-rw-cell*0.06,-hpx,(rw+cell*0.06)*2,hpx);
  ctx.setLineDash(SCL_DSH0);
}
function sclFoot(wx,wy,dir){
  var p=SC.FP[SC.fpi];SC.fpi=(SC.fpi+1)%16;
  p.on=1;p.x=wx;p.y=wy;p.t0=performance.now();p.dur=900;p.d=dir<0?-1:1;
}
function sclDust(px,py,n,sx,up,col){
  for(var i=0;i<n;i++){
    sclP(px+(Math.random()-0.5)*6*RTD.dpr,py,
         (sx*(0.4+Math.random()*0.9)+(Math.random()-0.5)*0.5)*46*RTD.dpr,
         -(up*(0.3+Math.random()*0.8))*46*RTD.dpr,
         320+Math.random()*260,col||'rgba(203,213,225,.55)',
         (1.4+Math.random()*1.9)*RTD.dpr,90*RTD.dpr,0,0.94);
  }
}
function sclGrazeEv(e){
  var raw=RTD.lastRaw;if(!raw||!raw.p)return;
  var seat=e.seat|0,row=raw.p[seat];
  if(!row)return;
  var mine=String(row[0])===String(RTD.myId);
  var cell=SC.cell||40;
  var px=SC.ox+row[1]*cell,py=SC.hh2+(SC.cam.y-row[2])*cell;
  var gan=SC.anim&&SC.anim[String(row[0])];
  if(gan){gan.grazeT=performance.now();gan.grazeD=(row[1]<SC.W/2?1:-1);}
  for(var i=0;i<(mine?9:5);i++){
    var a=Math.random()*6.283,sp=(70+Math.random()*180)*RTD.dpr;
    sclP(px,py,Math.cos(a)*sp,Math.sin(a)*sp,200+Math.random()*190,
         (i&1)?'#fef3c7':'#fdba74',(1.1+Math.random()*1.3)*RTD.dpr,60*RTD.dpr,1,0.93);
  }
  var dv=Math.max(0.2,1-Math.abs(row[2]-SC.myY)/9);
  TWS.play('sclGraze',mine?0.95:0.4*dv);
  if(mine){
    sclShake('graze',1);
    try{sclHitstop(2);}catch(_ghs){}
    var _gn=performance.now();
    SC.slowT=Math.max(SC.slowT,_gn+80);
    if(!SC.flash)SC.flash={t0:_gn,dur:300,a:0.20,col:'#d81b3c',vig:1};
    TWS.play('sclHeart',0.9);
    try{tg.HapticFeedback&&tg.HapticFeedback.impactOccurred('light');}catch(_g){}
  }
}
function sclHitEv(e){
  var raw=RTD.lastRaw;if(!raw||!raw.p||!window.SC)return;
  var seat=e.seat|0,row=raw.p[seat];
  if(!row)return;
  var mine=String(row[0])===String(RTD.myId);
  var dy=Math.abs(row[2]-(SC.myY||0));
  if(!mine&&dy>5)return;
  var iv=Math.max(0,Math.min(9,e.i|0))/9;
  var dv=mine?1:Math.max(0.22,1-dy/9);
  var cell=SC.cell||40,now=performance.now();
  var px=SC.ox+row[1]*cell,py=SC.hh2+(SC.cam.y-row[2])*cell;
  var kx=(e.kdx|0)/10,ky=(e.kdy|0)/10,kl=Math.sqrt(kx*kx+ky*ky);
  if(kl<0.001){kx=0;ky=-1;kl=1;}
  kx/=kl;ky/=kl;
  if(mine||now-(SC.hitST||0)>90){
    SC.hitST=now;
    TWS.play('punch',(mine?0.7:0.42)*dv*(0.55+0.45*iv));
  }
  if(e.w){
    for(var i2=0;i2<(mine?7:4);i2++){
      var a2=Math.random()*6.283,sp2=(50+Math.random()*130)*RTD.dpr;
      sclP(px,py-SC.PR*cell*0.9,Math.cos(a2)*sp2,Math.sin(a2)*sp2,
           170+Math.random()*150,(i2&1)?'#fde68a':'#cbd5e1',
           (1+Math.random()*1.2)*RTD.dpr,80*RTD.dpr,0,0.93);
    }
  }else{
    sclDust(px,py+SC.PR*cell*0.25,mine?6:4,kx>=0?1:-1,0.5+0.6*iv,'rgba(203,213,225,.55)');
  }
  if(mine){
    sclShake('spike',0.35+0.45*iv);
    sclHitstop(iv>0.55?2:1);
    if((row[3]|0)&1){
      var _hk=e.hk;
      if(_hk==='chain'||(_hk==='bomb'&&now-(SC.bombT||0)<500)){}
      else rtdStamp(_hk==='rock'?'MASSO!':(_hk==='axe'?'PICCOZZATA!':(_hk==='bomb'?'PETARDO!':'COLPITO!')),'#f87171');
      if(e.bs!=null&&(_hk==='rock'||_hk==='axe')){
        var _hbr=raw.p[e.bs|0];
        if(_hbr)rtdFeed((_hk==='rock'?'🪨 ':'⛏ ')+rtdName(_hbr[0])+(_hk==='rock'?' ti ha preso col masso':' ti ha dato una piccozzata'));
      }
    }
    try{if(HAP&&HAP.on)hapGioco(iv>0.55?'colpito':'colpo');}catch(_hh){}
  }
}
function sclP(x,y,vx,vy,dur,col,r,g,add,drg){
  var p=SC.P[SC.pi];SC.pi=(SC.pi+1)%96;
  p.on=1;p.x=x;p.y=y;p.vx=vx;p.vy=vy;p.t0=performance.now();p.dur=dur;p.col=col;p.r=r;p.g=g;p.add=add;p.drg=drg||0.98;
}
function sclG(x,y,vx,vy,dur,col){
  var p=SC.GIB[SC.gi];SC.gi=(SC.gi+1)%24;
  p.on=1;p.x=x;p.y=y;p.vx=vx;p.vy=vy;p.rot=Math.random()*6.283;p.vr=(Math.random()-0.5)*14;
  p.t0=performance.now();p.dur=dur;p.col=col;p.r=(2.4+Math.random()*2.4)*RTD.dpr;
  p.bnc=2+((Math.random()*2)|0);
}
