  var a=Math.random()*6.283,sp=2.5+Math.random()*4;
  if(kux!=null){
    p.vx=kux*sp*1.4+Math.cos(a)*sp*0.45;
    p.vy=kuy*sp*1.4+Math.abs(Math.sin(a))*sp*0.45+1.5*(0.5+0.5*kuy);
  }
  else{p.vx=Math.cos(a)*sp;p.vy=Math.abs(Math.sin(a))*sp+4;}
  p.rot=Math.random()*6.283;p.vr=(Math.random()-0.5)*12;
  p.part=part;p.seat=seat|0;p.look=look||SCL_LOOK_DEF;
