    c.strokeStyle='rgba(0,0,0,.55)';c.lineWidth=w+1.5;
    c.beginPath();c.moveTo(-len/2,0);c.lineTo(len/2,0);c.stroke();
    c.strokeStyle=col;c.lineWidth=w;
