function dpEdSections(){
  var field=function(ic,lbl,f,names){
    var out='<div class="dp-field"><div class="dp-field-h">'
      +'<span class="dp-field-ic">'+ic+'</span>'
      +'<span class="dp-field-nm">'+lbl+'</span>'
      +'<span class="dp-field-cur" id="dp-cur-'+f+'"></span></div>'
      +'<div class="twr-optrow" data-f="'+f+'">';
    names.forEach(function(nm2,i){
      if(!nm2)return;
      var st=dpIdxState(f,i);
      if(st===2)return;
      if(st===1)out+='<button class="twr-opt locked" onclick="dpLockedTap(\''+f+'\','+i+')">🔒 '+nm2+'</button>';
      else out+='<button class="twr-opt" data-i="'+i+'" onclick="dpEdSet(\''+f+'\','+i+')">'+nm2+'</button>';
    });
    return out+'</div></div>';
  };
  var grp=function(t){return '<div class="dp-grp">'+t+'</div>';};
  return grp('Testa')
    +field('⛑️','Casco','hm',SCL_HMN)
    +field('💇','Capelli','hr',SCL_HRN)
    +field('🥽','Occhialoni','gg',SCL_GGN)
    +field('🧣','Collo','bd',SCL_BDN)
    +grp('Corpo')
    +field('🧥','Tuta','st',SCL_STN)
    +field('🎗️','Imbrago','hb',SCL_HBN)
    +field('🎒','Zaino','bp',SCL_BPN)
    +grp('Mani &amp; Piedi')
    +field('🧤','Guanti','gl',SCL_GLN)
    +field('🥾','Scarpe','bo',SCL_BON)
    +grp('Stile')
    +field('⛏️','Piccozza','ax',SCL_AXN)
    +field('✨','Rim-light','rim',SCL_RIMN);
}
function dpIdxState(f,i){
  if((DP_FREE[f]||[]).indexOf(i)>=0)return 0;
  var gate=DP_GATE[f]&&DP_GATE[f][i];
  if(!gate)return 2;
  var unl=(typeof S!=='undefined'&&S.cosmetics&&S.cosmetics.unlocked&&S.cosmetics.unlocked.scalata)||[];
  for(var g=0;g<gate.length;g++)if(unl.indexOf(gate[g])>=0)return 0;
  return 1;
}
function dpLockedTap(f,i){
  try{TWS.play('err',0.4);}catch(e){}
  try{grHaptic('lose');}catch(e){}
  var gate=DP_GATE[f]&&DP_GATE[f][i];
  toast('🔒 Sblocca "'+(DP_COSNAME[gate&&gate[0]]||'?')+'" giocando DEAD PEAK','warn',2600);
}
function dpEdSet(f,v){
  if(dpIdxState(f,v|0)!==0)return;
  DP_ED.look[f]=v|0;
  dpEdMark();
  TWS.play('pick',0.5);
}
function dpEdSeat(i){
  DP_ED.ci=Math.max(0,Math.min(9,i|0));
  DP_ED.look.bodyCol=SCL_COLS[DP_ED.ci];
  dpEdMark();
  dpEdGrid();
  TWS.play('pick',0.5);
}
function dpEdMark(){
  document.querySelectorAll('#arc-modal [data-f]').forEach(function(row){
    var f=row.getAttribute('data-f');
    var cur=(f==='ci')?DP_ED.ci:(DP_ED.look[f]|0);
    row.querySelectorAll('button,span.twr-sw').forEach(function(b){
      var da=b.getAttribute('data-i');
      if(da==null)return;
      b.classList.toggle('sel',parseInt(da,10)===cur&&!b.classList.contains('locked'));
    });
  });
  var nm={st:SCL_STN,hm:SCL_HMN,hb:SCL_HBN,bp:SCL_BPN,ax:SCL_AXN,rim:SCL_RIMN,gg:SCL_GGN,hr:SCL_HRN,gl:SCL_GLN,bo:SCL_BON,bd:SCL_BDN};
  Object.keys(nm).forEach(function(f){
    var el=document.getElementById('dp-cur-'+f);
    if(el)el.textContent=nm[f][DP_ED.look[f]|0]||'';
  });
}
function dpEdSave(){
  var L=DP_ED.look;
  var lk={st:L.st|0,hm:L.hm|0,hb:L.hb|0,bp:L.bp|0,ax:L.ax|0,rim:L.rim|0,gg:L.gg|0,hr:L.hr|0,gl:L.gl|0,bo:L.bo|0,bd:L.bd|0,bodyCol:sclNormCol(L.bodyCol)};
  try{localStorage.setItem('gb_deadpeak',JSON.stringify(lk));}catch(e){}
  RTD._lookC={};
  fetch(BACKEND+'/deadpeak',{method:'POST',headers:{'Content-Type':'application/json','ngrok-skip-browser-warning':'1'},
    body:JSON.stringify({user_id:S.userId,look:lk})})
    .then(function(r){if(!r.ok)throw 0;return r.json();})
    .then(function(d){
      if(d&&d.ok&&d.look){try{localStorage.setItem('gb_deadpeak',JSON.stringify(d.look));}catch(e){}RTD._lookC={};}
      toast('✅ Scalatore salvato','ok',2000);TWS.play('gold',0.7);
    })
    .catch(function(){toast('⚠️ Salvato solo su questo dispositivo — verrà risincronizzato','warn',3000);});
  if(typeof grHaptic==='function')grHaptic('pick');
  dpEdClose();
}
function dpEdClose(){
  if(DP_ED.raf){cancelAnimationFrame(DP_ED.raf);DP_ED.raf=null;}
  rtdOvClose();
  if(RTD.ui==='lobby'||RTD.ui==='')rtdShowLobby();
}
function dpEdDraw(){
  var cv=document.getElementById('dp-ed-cv');if(!cv)return;
  var ctx=cv.getContext('2d');
  var now=performance.now(),W=cv.width,H=cv.height;
  if(!DP_ED.bgCv){
    var b=document.createElement('canvas');b.width=W;b.height=H;
    var bc=b.getContext('2d');
    var sky=bc.createLinearGradient(0,0,0,H);
    sky.addColorStop(0,'#0b1322');sky.addColorStop(1,'#05070c');
    bc.fillStyle=sky;bc.fillRect(0,0,W,H);
    var sd=7,s2;
    for(s2=0;s2<26;s2++){
      sd=(sd*16807)%2147483647;var sx2=sd%W;
      sd=(sd*16807)%2147483647;var sy2=sd%Math.floor(H*0.5);
      bc.fillStyle='rgba(226,232,240,'+(0.15+(s2%3)*0.12).toFixed(2)+')';
      bc.fillRect(sx2,sy2,1.6,1.6);
    }
    bc.fillStyle='#1b2333';bc.fillRect(W*0.56,0,W*0.2,H);
    bc.fillStyle='#232e44';bc.fillRect(W*0.56,0,5,H);
    bc.fillStyle='#141c2c';bc.fillRect(W*0.76-5,0,5,H);
    for(s2=0;s2<12;s2++){
      sd=(sd*16807)%2147483647;
      var hx=W*0.58+(sd%Math.floor(W*0.14)),hy=16+s2*(H-30)/12;
      bc.fillStyle='rgba(0,0,0,.4)';bc.fillRect(hx,hy,9,3.5);
      bc.fillStyle='rgba(255,255,255,.07)';bc.fillRect(hx,hy-1.5,9,1.5);
    }
    bc.fillStyle='rgba(0,0,0,.5)';bc.fillRect(0,H*0.30-2,W*0.56,4);
    bc.fillStyle='#1b2333';bc.fillRect(W*0.05,H*0.74+8,W*0.51,14);
    bc.fillStyle='#232e44';bc.fillRect(W*0.05,H*0.74+8,W*0.51,2.5);
    bc.fillStyle='rgba(0,0,0,.35)';bc.fillRect(W*0.05,H*0.74+22,W*0.51,5);
    bc.fillStyle='#94a3b8';bc.fillRect(W*0.63,6,2.5,20);
    bc.fillStyle='#f87171';
    bc.beginPath();bc.moveTo(W*0.63+2.5,7);bc.lineTo(W*0.63+17,11.5);bc.lineTo(W*0.63+2.5,16);bc.closePath();bc.fill();
    DP_ED.bgCv=b;
  }
  ctx.drawImage(DP_ED.bgCv,0,0);
  var lk=sclNormLook(DP_ED.look),ci=DP_ED.ci;
  var T=6400,t=(now-DP_ED.t0)%T,cyc=Math.floor((now-DP_ED.t0)/T);
  var pr=22;
  var bladeY=H*0.30,gy=H*0.74;
  var x0=W*0.17,x1=W*0.50,k;
  var px=x0,py=gy,vx=0,vy=0,air=false,winp=false;
  if(t<1600){
    px=x0;
  }else if(t<2900){
    k=(t-1600)/1300;px=x0+(x1-x0)*k;vx=4.2;
  }else if(t<4200){
    k=(t-2900)/1300;px=x1-(x1-x0)*k;vx=-4.2;
  }else if(t<5000){
    k=(t-4200)/800;px=x0;
    py=gy-56*Math.sin(k*3.1416);
    vy=Math.cos(k*3.1416)*10;
    air=k<0.96;
  }else{
    k=(t-5000)/1400;px=x0;winp=true;
    py=gy-Math.abs(Math.sin(k*6.283))*7;
  }
  var bk=0.5+0.5*Math.sin(now/1900),bx=W*0.32+(W*0.20)*bk,brad=17;
  ctx.save();
  ctx.translate(bx,bladeY);ctx.rotate(now/70);
  ctx.fillStyle='#9ca3af';ctx.beginPath();ctx.arc(0,0,brad,0,6.283);ctx.fill();
  ctx.fillStyle='#4b5563';
  for(var th2=0;th2<8;th2++){ctx.save();ctx.rotate(th2*0.785);ctx.fillRect(brad-3,-3,7,6);ctx.restore();}
  ctx.fillStyle='#1f2937';ctx.beginPath();ctx.arc(0,0,5,0,6.283);ctx.fill();
  ctx.restore();
  ctx.globalAlpha=0.22;ctx.fillStyle='#000';
  var shk=Math.max(0.45,1-(gy-py)/90);
  ctx.beginPath();ctx.ellipse(px,gy+pr*0.2,pr*0.9*shk,pr*0.3*shk,0,0,6.283);ctx.fill();
  ctx.globalAlpha=1;
  ctx.save();
  ctx.translate(px,py);
  var edAn=DP_ED._an||(DP_ED._an={rig:null,vxs:0,vys:0,grazeT:0});
  edAn.vxs=vx;edAn.vys=vy;
  var edRr=DP_ED._rr||(DP_ED._rr=[0,2,10]);
  edRr[7]=vx;edRr[8]=vy;
  var edFl=winp?32:(air?2:1);
  sclPose(edAn,edRr,edFl,now,true,ci);
  sclRigBlend(edAn,999,0.016);
  if(edAn.landT&&now-edAn.landT<40&&DP_ED.clangCyc!==cyc){
    DP_ED.clangCyc=cyc;
    for(var fi=0;fi<8;fi++){
      var sp=DP_ED.spark[fi];sp.on=1;sp.x=px;sp.y=gy+4;
      sp.vx=(fi%2?1:-1)*(18+Math.random()*40);sp.vy=-14-Math.random()*26;sp.t0=now;
    }
  }
  sclDrawClimber(ctx,edAn.rig,lk,ci,true,pr,now);
  ctx.restore();
  for(var qi=0;qi<DP_ED.spark.length;qi++){
    var pf=DP_ED.spark[qi];
    if(!pf.on)continue;
    var pk=(now-pf.t0)/650;
    if(pk>=1){pf.on=0;continue;}
    ctx.globalAlpha=(1-pk)*0.7;ctx.fillStyle=qi%2?'#cbd5e1':'#94a3b8';
    ctx.fillRect(pf.x+pf.vx*pk,pf.y+pf.vy*pk+40*pk*pk,3,3);
  }
  ctx.globalAlpha=1;
}
function dpSeen(){try{return JSON.parse(localStorage.getItem('gb_cos_seen_scalata')||'[]')||[];}catch(e){return [];}}
function dpSeenAdd(id){try{var s=dpSeen();if(s.indexOf(id)<0){s.push(id);localStorage.setItem('gb_cos_seen_scalata',JSON.stringify(s));}}catch(e){}}
function dpReqLabel(cd){
  var st=cd.challenge.stat,g=cd.challenge.goal;
  if(/_games$/.test(st))return 'Gioca '+g+' DEAD PEAK';
  if(/_wins$/.test(st))return 'Vinci '+g+' DEAD PEAK';
  if(/_kills$/.test(st))return 'Fai fuori '+g+' rivali';
  if(/_deaths$/.test(st))return 'Muori '+g+' volte';
  return g+' × '+st;
}
function dpCosLoad(){
  if(!S.userId){dpEdGrid();return;}
  fetch(BACKEND+'/cosmetics_data?v=2&modi=scalata&user_id='+S.userId,{headers:{'ngrok-skip-browser-warning':'1'}})
    .then(function(r){return r.json();})
    .then(function(d){
      if(!d||!d.ok)return;
      COS.data=d;
      S.rtStats=d.stats||d.progress||null;
      S.cosmetics={unlocked:d.unlocked||{},equipped:d.equipped||{}};
      dpEdOnCos('scalata');
    })
    .catch(function(){});
}
function dpEdGrid(){
  var host=document.getElementById('dp-skins');
  if(!host)return;
  if(typeof COS==='undefined'||!COS.data||!COS.data.catalog||!COS.data.catalog.scalata){
    host.innerHTML='<div style="grid-column:1/-1;text-align:center;color:var(--txt3);font-size:10px;padding:14px;">⏳ Caricamento skin…</div>';
    return;
  }
  var cat=COS.data.catalog.scalata,prog=COS.data.progress||{};
  var unl=(COS.data.unlocked&&COS.data.unlocked.scalata)||[];
  var eq=(COS.data.equipped&&COS.data.equipped.scalata)||null;
  var seen=dpSeen(),html='';
  cat.forEach(function(cd){
    var goal=cd.challenge.goal,p=prog[cd.challenge.stat]||0,pct=Math.min(100,Math.round(p/goal*100));
    var isU=unl.indexOf(cd.id)>=0,isE=(eq===cd.id),claim=(!isU&&p>=goal);
    var isNew=claim||(isU&&!isE&&seen.indexOf(cd.id)<0);
    var btn;
    if(isE)btn='<button class="db-sk-btn" disabled style="background:linear-gradient(145deg,#39ff14,#10b981);color:#000;">EQUIPAGGIATA ✓</button>';
    else if(isU)btn='<button class="db-sk-btn" onclick="dpCosEquip(\''+cd.id+'\')" style="background:linear-gradient(145deg,#ffd700,#ff9500);color:#000;">EQUIPAGGIA</button>';
    else if(claim)btn='<button class="db-sk-btn" onclick="dpCosClaim(\''+cd.id+'\')" style="background:linear-gradient(145deg,#22d3ee,#a855f7);color:#000;">RISCUOTI 🎉</button>';
    else btn='<button class="db-sk-btn" disabled style="background:rgba(255,255,255,.06);color:#71717a;">🔒 BLOCCATA</button>';
    html+='<div class="db-sk-card rar-'+cd.rarity+'">'
      +(isNew?'<span class="db-sk-new">NEW</span>':'')
      +(!isU&&!claim?'<span class="db-sk-lock">🔒</span>':'')
      +'<canvas id="dpsk_'+cd.id+'" width="64" height="58" style="width:64px;height:58px;"></canvas>'
      +'<div class="db-sk-name">'+cd.name+'</div>'
      +'<div class="db-sk-req">'+(isU?cd.desc:dpReqLabel(cd))+'</div>'
      +'<div class="db-sk-bar"><div class="db-sk-fill" style="width:'+(isU?100:pct)+'%;"></div></div>'
      +'<div class="db-sk-req" style="margin-top:2px;">'+(isU?'SBLOCCATA':Math.min(p,goal)+' / '+goal)+'</div>'
      +'<div>'+btn+'</div></div>';
  });
  host.innerHTML=html;
  cat.forEach(function(cd){
    var cv=document.getElementById('dpsk_'+cd.id);
    if(cv)dpSkinPrev(cv,cd.look_patch,unl.indexOf(cd.id)<0);
  });
}
function dpSkinPrev(cv,patch,silhouette){
  var ctx=cv.getContext('2d');
  ctx.clearRect(0,0,cv.width,cv.height);
  var b=DP_ED.look||deadpeakLook(),lk={},k;
  for(k in b)lk[k]=b[k];
  if(patch)for(k in patch)lk[k]=patch[k];
  lk=sclNormLook(lk);
  var spr=sclSprite(DP_ED.ci,false,lk);
  if(silhouette){
    var tc2=document.createElement('canvas');tc2.width=64;tc2.height=64;
    var t2=tc2.getContext('2d');
    t2.drawImage(spr,0,0);
    t2.globalCompositeOperation='source-in';
    t2.fillStyle='#181f2c';t2.fillRect(0,0,64,64);
    ctx.globalAlpha=0.9;ctx.drawImage(tc2,0,-4);ctx.globalAlpha=1;
  }else ctx.drawImage(spr,0,-4);
}
