  if(raw&&raw.p)for(var i=0;i<raw.p.length;i++)
    if(String(raw.p[i][0])===wid){wx=raw.p[i][1];wy=raw.p[i][2];break;}
  SC.win={t0:performance.now(),wid:wid,x:wx,y:wy};
