    ctx.strokeStyle='rgba(125,211,252,.85)';ctx.lineWidth=1.2*d;ctx.stroke();
    ctx.fillStyle='#e0f2fe';ctx.textAlign='center';
    ctx.fillText(lab,px+pw/2+(k?-5*d:5*d),sy);
    var cx=k?(px+pw-9*d):(px+9*d),s=k?1:-1;
    ctx.fillStyle='#7dd3fc';
