      var ty=H2*(0.15+rnd()*0.6);
      c.fillRect(cxp-cw*1.6,ty,cw*4.2,Math.max(1,H2*0.012));
      c.fillRect(cxp-cw*1.2,ty+H2*0.22,cw*3.4,Math.max(1,H2*0.010));
