  for(var i=0;i<3;i++){
    var wx=wr[1]+(wr[3]===0?i-1:0)+0.5,wy=wr[2]+(wr[3]===1?i-1:0)+0.5;
    var px=SC.ox+wx*cell,py=SC.hh2+(SC.cam.y-wy)*cell;
    sclP(px,py,(Math.random()-0.5)*70,-(20+Math.random()*50)*RTD.dpr,450+Math.random()*250,'#a8a29e',(2+Math.random()*2)*RTD.dpr,140*RTD.dpr,0,0.97);
    sclP(px,py,(Math.random()-0.5)*50,-(10+Math.random()*30)*RTD.dpr,620,'rgba(120,113,108,.6)',3*RTD.dpr,60*RTD.dpr,0,0.985);
  }
