function frCopyLink(){
  var link = frGetLink();
  try{
    if(navigator.clipboard && navigator.clipboard.writeText){
      navigator.clipboard.writeText(link);
    }else{
      var ta = document.createElement('textarea');
      ta.value = link; document.body.appendChild(ta);
      ta.select(); document.execCommand('copy');
      document.body.removeChild(ta);
    }
    toast('\u2705 '+((window.GB_LANG==='en')?'Link copied!':'Link copiato!'),'ok',1500);
  }catch(e){
    toast('Copy failed: '+e.message,'err',2000);
  }
}
function frShareLink(){
  var link = frGetLink();
  var text = GB_AMICI[(window.GB_LANG==='en')?'en':'it'].share + link;
  if(tg && tg.openTelegramLink){
    var shareUrl = 'https://t.me/share/url?url=' + encodeURIComponent(link) + '&text=' + encodeURIComponent(text);
    try{tg.openTelegramLink(shareUrl); return;}catch(e){}
  }
  if(navigator.share){
    navigator.share({title:'Gambler Bot', text:text, url:link}).catch(function(){frCopyLink();});
    return;
  }
  frCopyLink();
}
function plShuffleArray(arr){
  var a = arr.slice();
  for(var i = a.length - 1; i > 0; i--){
    var j = Math.floor(Math.random() * (i + 1));
    var tmp = a[i]; a[i] = a[j]; a[j] = tmp;
  }
  return a;
}
